14:   --gold: #e6c46a;
15:   --gold-2: #f7e6a8;
16:   --gold-dim: #a88b45;
17:   --text: #f1ebdd;
18:   --muted: #a79fb2;
19:   --muted-2: #7b7388;
20:   --green: #65d67a;
21:   --blue: #5aa9ff;
22:   --red: #ff5d73;
23:   --purple: #b079ff;
24:   --orange: #ffb23e;
25:   --serif: Georgia, 'Times New Roman', 'Palatino Linotype', serif;
26:   --sans: Inter, ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
27:   --shadow: 0 18px 55px rgba(0, 0, 0, 0.55);
28:   --safe-b: env(safe-area-inset-bottom, 0px);
29:   --safe-l: env(safe-area-inset-left, 0px);
