32: 
33: * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
34: html, body { height: 100%; margin: 0; padding: 0; }
35: body {
36:   background: var(--ink);
37:   color: var(--text);
38:   font-family: var(--sans);
39:   overflow: hidden;
40:   overscroll-behavior: none;
41:   user-select: none;
42:   -webkit-user-select: none;
43: }
44: button, input, select { font: inherit; color: inherit; }
45: button { cursor: pointer; }
46: .hidden { display: none !important; }
47: ::-webkit-scrollbar { width: 7px; height: 7px; }
48: ::-webkit-scrollbar-thumb { background: rgba(230, 196, 106, 0.25); border-radius: 99px; }
49: ::-webkit-scrollbar-track { background: transparent; }
50: 
51: #app { position: fixed; inset: 0; overflow: hidden; background: #08070d; }
52: #gameCanvas {
53:   position: absolute; inset: 0; width: 100%; height: 100%;
