55: }
56: #vignette {
57:   position: absolute; inset: 0; pointer-events: none;
58:   background:
59:     radial-gradient(ellipse at 50% 42%, transparent 42%, rgba(4, 3, 9, 0.34) 100%),
60:     linear-gradient(to bottom, rgba(4, 3, 9, 0.35), transparent 18%, transparent 78%, rgba(4, 3, 9, 0.42));
