100: .bar.mana .bar-fill { background: linear-gradient(180deg, #6db7ff, #2451b6); }
101: .bar.xp { height: 8px; }
102: .bar.xp .bar-fill { background: linear-gradient(90deg, #8b6a1e, var(--gold), #fff0b0); }
