115:   background: rgba(12, 10, 18, 0.86); border: 1px solid var(--line); font-size: 11px;
116:   box-shadow: 0 3px 16px rgba(0,0,0,0.3);
117: }
118: .pill b { font-weight: 700; letter-spacing: .3px; }
119: .pill.gold span { color: var(--gold); }
120: .pill.gems span { color: #8fe2ff; }
121: .quick-row { display: flex; gap: 5px; }
122: .quick-btn {
123:   width: 38px; height: 38px; border-radius: 10px; border: 1px solid var(--line);
124:   background: linear-gradient(160deg, rgba(38, 31, 55, 0.9), rgba(14, 11, 21, 0.92));
