131: 
132: .minimap-wrap {
133:   position: absolute; top: 126px; right: 12px; width: 108px;
134:   border-radius: 12px; overflow: hidden; border: 1px solid var(--line);
135:   background: rgba(8,7,14,0.8); box-shadow: var(--shadow);
136: }
