144: 
145: .quest-tracker {
146:   position: absolute; top: 248px; left: 12px; width: min(214px, 53vw);
147:   padding: 9px 10px; border-radius: 11px; border: 1px solid var(--line);
148:   background: linear-gradient(160deg, rgba(26,21,38,0.9), rgba(12,10,18,0.85));
149:   box-shadow: 0 8px 28px rgba(0,0,0,0.35); backdrop-filter: blur(5px); cursor: pointer;
150: }
151: .qt-head { display: flex; align-items: center; gap: 6px; font-family: var(--serif); font-size: 12px; color: var(--gold-2); }
152: .qt-icon { color: var(--gold); font-size: 10px; }
153: .qt-desc { font-size: 9px; line-height: 1.35; color: var(--muted); margin: 4px 0 5px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
154: .qt-progress { height: 4px; border-radius: 9px; background: rgba(255,255,255,0.08); overflow: hidden; }
