164: .boss-title { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--serif); font-size: 12px; color: #ffb08a; margin-bottom: 4px; }
165: .boss-title em { font-style: normal; font-size: 9px; color: var(--muted); }
166: .boss-track { height: 10px; border-radius: 6px; background: rgba(0,0,0,0.6); overflow: hidden; border: 1px solid rgba(255,255,255,0.08); }
167: #bossFill { height: 100%; width: 100%; background: linear-gradient(180deg, #ff7a5c, #a61e24); transition: width .18s; }
168: 
169: .event-feed {
170:   position: absolute; left: 12px; bottom: calc(150px + var(--safe-b)); width: min(270px, 52vw);
171:   display: flex; flex-direction: column; gap: 3px; pointer-events: none;
172: }
173: .feed-line { font-size: 9px; color: rgba(240,232,215,0.75); background: rgba(8,7,14,0.55); padding: 3px 7px; border-radius: 4px; width: fit-content; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; animation: feedIn .3s ease; }
174: .feed-line.gold { color: var(--gold-2); }
