187: /* ---------------- controls ---------------- */
188: #controls { position: absolute; inset: 0; pointer-events: none; }
189: .joystick {
190:   position: absolute; left: calc(18px + var(--safe-l)); bottom: calc(18px + var(--safe-b));
191:   width: 120px; height: 120px; border-radius: 50%; pointer-events: auto;
192:   background: radial-gradient(circle at 50% 50%, rgba(30,24,44,0.55), rgba(10,8,16,0.35));
193:   border: 1px solid rgba(230,196,106,0.16); touch-action: none;
194: }
195: .joy-ring { position: absolute; inset: 10px; border-radius: 50%; border: 1px dashed rgba(230,196,106,0.18); }
196: .joy-knob {
197:   position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px;
198:   border-radius: 50%; background: radial-gradient(circle at 38% 32%, #4b3d68, #211a33);
199:   border: 1px solid var(--line-strong); box-shadow: 0 6px 18px rgba(0,0,0,.4), inset 0 0 12px rgba(230,196,106,0.12);
200:   will-change: transform;
201: }
202: .joy-hint { position: absolute; bottom: 6px; width: 100%; text-align: center; font-size: 7px; letter-spacing: 2px; color: rgba(230,196,106,0.35); }
203: 
204: .action-cluster { position: absolute; right: calc(12px + var(--safe-r)); bottom: calc(16px + var(--safe-b)); width: 190px; height: 196px; pointer-events: none; }
205: .act {
206:   position: absolute; pointer-events: auto; border-radius: 50%; border: 1px solid rgba(230,196,106,0.28);
207:   background: radial-gradient(circle at 38% 30%, rgba(54,44,76,0.95), rgba(18,14,28,0.96));
