238: /* ============================== START ============================== */
239: .start-screen {
240:   position: absolute; inset: 0; z-index: 60; overflow: hidden;
241:   background:
242:     radial-gradient(ellipse at 68% 32%, rgba(94, 74, 140, 0.28), transparent 55%),
243:     radial-gradient(ellipse at 24% 80%, rgba(120, 60, 40, 0.18), transparent 55%),
