652:       : item.kind === 'stone'
653:         ? `${CLASSES[item.classId].name} · ${BONUS_STATS[item.stat].name} +${item.value}${item.stat === 'crit' ? '%' : ''}`
654:         : `${SLOT_NAME[item.slot]} · ${RARITIES[item.rarity].name} · T${item.tier}`;
