985:       p(ctx, -2, -12, 1, 12, '#5d4430');
986:       p(ctx, -5, -2, 3, 2, '#4a3324');           // root
987:       p(ctx, 3, -2, 3, 2, '#4a3324');
988:       p(ctx, -9 + sway, -22, 18, 11, leaf3);
989:       p(ctx, -9 + sway, -22, 18, 3, leaf);
990:       p(ctx, -7 + sway, -31, 14, 11, leaf);
991:       p(ctx, -7 + sway, -31, 14, 2, leaf2);
992:       p(ctx, -5 + sway, -39, 10, 10, leaf);
993:       p(ctx, -2 + sway, -44, 4, 7, leaf);
994:       if (snow) {
995:         p(ctx, -9 + sway, -22, 18, 2, '#eef6fa');
996:         p(ctx, -7 + sway, -31, 14, 2, '#eef6fa');
997:         p(ctx, -5 + sway, -39, 10, 2, '#eef6fa');
998:         p(ctx, -2 + sway, -44, 4, 2, '#fff');
999:         p(ctx, -11 + sway, -18, 4, 2, '#d7e6ef');
1000:         p(ctx, 5 + sway, -16, 3, 2, '#d7e6ef');
1001:       } else {
1002:         p(ctx, -4 + sway, -28, 9, 2, shade(leaf, 0.24));
1003:         p(ctx, 2 + sway, -20, 6, 2, shade(leaf, 0.1));
1004:       }
1005:       break;
1006:     }
1007:     case 'dead_tree': {
1008:       p(ctx, -2, -26, 5, 26, '#4a3a34');
1009:       p(ctx, -2, -26, 2, 26, '#5d4a44');
1010:       p(ctx, -10, -30, 9, 3, '#4a3a34');
1011:       p(ctx, -12, -36, 3, 7, '#4a3a34');
1012:       p(ctx, 5, -26, 8, 3, '#4a3a34');
1013:       p(ctx, 10, -33, 3, 8, '#4a3a34');
1014:       p(ctx, 10, -39, 4, 6, '#4a3a34');
1015:       p(ctx, -6, -20, 7, 2, '#3a2c2a');
1016:       p(ctx, -1, -30, 6, 2, '#3a2c2a');
1017:       if (v % 3 === 0) {
