1266:   drawMinimap(canvas, game) {
1267:     const ctx = canvas.getContext('2d');
1268:     const world = this.world;
1269:     const w = canvas.width, h = canvas.height;
1270:     ctx.clearRect(0, 0, w, h);
1271:     ctx.fillStyle = 'rgba(8,7,14,0.88)';
1272:     ctx.fillRect(0, 0, w, h);
1273:     if (!world) return;
1274:     const pad = 4;
1275:     const scale = Math.min((w - pad * 2) / world.size, (h - pad * 2) / world.size);
1276:     const ox = (w - world.size * scale) / 2;
1277:     const oy = (h - world.size * scale) / 2;
1278:     for (let y = 0; y < world.size; y++) {
1279:       for (let x = 0; x < world.size; x++) {
1280:         const t = world.tiles[y * world.size + x];
1281:         let col = '#2b3d2e';
1282:         if (t.type === 'water') col = '#25505c';
1283:         else if (t.type === 'path' || t.type === 'plaza') col = '#6b5a3d';
1284:         else if (t.type === 'void') col = '#0a0918';
1285:         else if (t.type === 'ground2') col = shade(world.region.palette.ground2, -0.1);
1286:         else if (t.type === 'ground3') col = shade(world.region.palette.ground3, -0.1);
1287:         ctx.fillStyle = col;
1288:         ctx.fillRect(ox + x * scale, oy + y * scale, Math.ceil(scale), Math.ceil(scale));
1289:       }
1290:     }
1291:     // npcs
1292:     for (const n of world.npcs) {
1293:       ctx.fillStyle = '#ffd166';
1294:       ctx.fillRect(ox + n.x * scale - 1, oy + n.y * scale - 1, 3, 3);
1295:     }
1296:     // enemies
1297:     for (const e of world.enemies) {
1298:       if (!e.alive) continue;
1299:       ctx.fillStyle = e.boss ? '#ff4d4d' : e.elite ? '#ffd166' : 'rgba(255,110,110,0.75)';
1300:       const sz = e.boss ? 4 : 2;
1301:       ctx.fillRect(ox + e.x * scale - sz / 2, oy + e.y * scale - sz / 2, sz, sz);
1302:     }
1303:     // player
1304:     const px = ox + game.player.x * scale;
1305:     const py = oy + game.player.y * scale;
1306:     ctx.fillStyle = '#fff3c4';
1307:     ctx.beginPath(); ctx.arc(px, py, 3, 0, Math.PI * 2); ctx.fill();
1308:     ctx.strokeStyle = '#1a1520'; ctx.lineWidth = 1; ctx.stroke();
1309:     // border + region label
1310:     ctx.strokeStyle = 'rgba(230,196,106,0.35)';
1311:     ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
1312:   }
1313: }
