734:             <span class="tag">${item.kind === 'equip' ? RARITIES[item.rarity].name : item.kind === 'stone' ? 'Boss Stone' : 'Material'}</span>
735:             ${item.kind === 'equip' ? `<span class="tag">${SLOT_NAME[item.slot]}</span>` : ''}
736:             ${equippedSlot ? '<span class="tag green">Equipped</span>' : ''}
