173:   p(ctx, -6, headY + 9, 12, 1, skinShade);
174:   // neck
175:   p(ctx, -2, headY + 10, 4, 3, skinShade);
176:   // eyes
177:   p(ctx, -4, headY + 5, 2, 2, '#f7f4ea');
178:   p(ctx, 2, headY + 5, 2, 2, '#f7f4ea');
179:   p(ctx, -3, headY + 5, 1, 2, o.eyeColor || '#3f8cff');
180:   p(ctx, 3, headY + 5, 1, 2, o.eyeColor || '#3f8cff');
181:   if (female) { p(ctx, -5, headY + 4, 2, 1, OUT2); p(ctx, 3, headY + 4, 2, 1, OUT2); }
182:   // mouth
183:   p(ctx, -1, headY + 9, 2, 1, shade(skin, -0.25));
184: 
185:   // horn/halo faction detail
186:   if (demon) {
187:     p(ctx, -5, headY - 3, 2, 3, '#3d1f2b');
188:     p(ctx, -6, headY - 5, 2, 3, '#5c2637');
189:     p(ctx, 3, headY - 3, 2, 3, '#3d1f2b');
190:     p(ctx, 4, headY - 5, 2, 3, '#5c2637');
191:   }
192: 
193:   // hair styles (drawn before helmet)
194:   drawHair(ctx, o.hairStyle, hair, headY, female, time);
195: 
196:   // helmet overrides hair partly
197:   if (eq.helmet) drawHelmet(ctx, o.classId, eq.helmet, headY, pal, demon);
198: 
199:   // earrings
200:   if (eq.earrings) {
201:     p(ctx, -7, headY + 6, 1, 2, EQUIP_COLOR(eq.earrings.rarity, '#ffd166'));
202:     p(ctx, 6, headY + 6, 1, 2, EQUIP_COLOR(eq.earrings.rarity, '#ffd166'));
203:   }
204: 
205:   // halo for angels — a small hollow pixel ring, not a flat bar
206:   if (!demon) {
207:     ctx.save();
208:     ctx.globalAlpha = 0.9;
209:     const hy = Math.round(headY - (eq.helmet ? 7 : 8));
210:     p(ctx, -4, hy, 8, 1, '#fff4c4');
211:     p(ctx, -5, hy + 1, 1, 1, '#ffe9a3');
212:     p(ctx, 4, hy + 1, 1, 1, '#ffe9a3');
213:     p(ctx, -4, hy + 2, 8, 1, '#e8c46a');
214:     ctx.restore();
215:   }
216: 
217:   // ---- arms + weapon ----
218:   drawArmsAndWeapon(ctx, o, pal, skin, attack, casting, time, swing);
219: 
220:   ctx.restore();
221: 
222:   // ---- aura tier (subtle, inside sprite space) ----
223:   if (o.aura) {
224:     ctx.save();
225:     ctx.globalAlpha = 0.22 + (o.aura.strength || 0) * 0.09;
226:     ctx.fillStyle = o.aura.color;
227:     ctx.beginPath();
228:     ctx.ellipse(0, -22, 14 + (o.aura.strength || 0) * 2, 24 + (o.aura.strength || 0) * 2, 0, 0, Math.PI * 2);
229:     ctx.fill();
230:     ctx.restore();
231:   }
232: 
233:   ctx.restore();
234: }
