236: function drawHair(ctx, style, color, headY, female, time) {
237:   const c = color;
238:   const d = shade(c, -0.16);
239:   const l = shade(c, 0.14);
240:   switch (style) {
241:     case 'swept':
242:       p(ctx, -6, headY - 2, 12, 3, c);
243:       p(ctx, -6, headY, 2, 4, c);
244:       p(ctx, 4, headY - 1, 3, 2, l);
245:       p(ctx, -7, headY + 1, 1, 5, c);
246:       p(ctx, 5, headY + 1, 1, 5, d);
247:       break;
248:     case 'braid':
249:       p(ctx, -6, headY - 2, 12, 3, c);
250:       p(ctx, -7, headY + 1, 2, 7, c);
251:       p(ctx, 5, headY + 1, 2, 11, d);
252:       p(ctx, 4, headY + 10, 4, 3, c);
253:       p(ctx, 5, headY + 13, 2, 2, d);
254:       break;
255:     case 'wild':
256:       p(ctx, -7, headY - 3, 14, 4, c);
257:       p(ctx, -7, headY - 1, 2, 7, c);
258:       p(ctx, 5, headY - 1, 2, 7, c);
259:       p(ctx, -5, headY - 5, 2, 3, c);
260:       p(ctx, -1, headY - 6, 2, 3, c);
261:       p(ctx, 3, headY - 5, 2, 3, c);
262:       p(ctx, 6, headY + 1, 2, 5, d);
263:       break;
264:     case 'topknot':
265:       p(ctx, -5, headY - 2, 10, 3, c);
266:       p(ctx, -5, headY + 1, 1, 4, c);
267:       p(ctx, 4, headY + 1, 1, 3, d);
268:       p(ctx, -2, headY - 6, 5, 4, c);
269:       p(ctx, 2, headY - 7, 2, 2, l);
270:       break;
271:     case 'long':
272:       p(ctx, -7, headY - 2, 14, 4, c);
273:       p(ctx, -8, headY + 1, 3, 16, c);
274:       p(ctx, 5, headY + 1, 3, 16, d);
275:       p(ctx, -6, headY, 2, 7, c);
276:       p(ctx, 4, headY, 2, 7, d);
277:       p(ctx, -8, headY + 16, 3, 3, d);
278:       p(ctx, 5, headY + 16, 3, 3, shade(d, -0.08));
279:       break;
280:     case 'pony':
281:       p(ctx, -6, headY - 2, 12, 3, c);
282:       p(ctx, -7, headY + 1, 2, 6, c);
283:       p(ctx, 5, headY, 2, 4, d);
284:       p(ctx, 4, headY - 4, 5, 2, c);
285:       p(ctx, 7, headY - 2, 3, 9, c);
286:       p(ctx, 8, headY + 7, 2, 3, d);
287:       break;
288:     case 'twin':
289:       p(ctx, -6, headY - 2, 12, 3, c);
290:       p(ctx, -8, headY + 1, 3, 12, d);
291:       p(ctx, 5, headY + 1, 3, 12, d);
292:       p(ctx, -8, headY + 13, 3, 2, c);
293:       p(ctx, 5, headY + 13, 3, 2, c);
294:       p(ctx, -6, headY, 2, 5, c);
295:       p(ctx, 4, headY, 2, 5, c);
296:       break;
297:     case 'bob':
298:       p(ctx, -7, headY - 2, 14, 3, c);
299:       p(ctx, -8, headY + 1, 3, 8, c);
300:       p(ctx, 5, headY + 1, 3, 8, d);
301:       p(ctx, -6, headY, 2, 5, c);
302:       p(ctx, 4, headY, 2, 5, d);
303:       break;
304:     case 'bun':
305:       p(ctx, -6, headY - 2, 12, 3, c);
306:       p(ctx, -2, headY - 7, 6, 5, c);
307:       p(ctx, 0, headY - 8, 3, 2, l);
308:       p(ctx, -7, headY + 1, 2, 5, c);
309:       p(ctx, 5, headY + 1, 2, 5, d);
310:       break;
311:     default: // short
312:       p(ctx, -6, headY - 2, 12, 3, c);
313:       p(ctx, -7, headY + 1, 2, 5, c);
314:       p(ctx, 5, headY + 1, 2, 5, d);
315:       p(ctx, -4, headY - 1, 4, 2, l);
316:       break;
317:   }
318: }
