575:     p(ctx, -9, -9, 3, 9 + leg2, dark); p(ctx, -9, 0 + leg2, 5, 2, '#2a1b16');
576:     // neck/head
577:     p(ctx, 13, -27, 5, 10, c);
578:     p(ctx, 16, -30, 8, 6, c);
579:     p(ctx, 23, -28, 5, 4, light);
580:     px(ctx, 25, -27, 1, 1, '#ffd166');
581:     p(ctx, 16, -32, 2, 3, dark);
582:     // spikes / tail
583:     p(ctx, 12, -29, 1, 2, '#d5a44c');
584:     p(ctx, -14, -17, 2, 8, dark);
585:     p(ctx, -17, -11, 4, 2, dark);
