596: export function drawPet(ctx, pet, time) {
597:   const bob = Math.sin(time * 3) * 2;
598:   ctx.save();
599:   ctx.translate(0, bob);
600:   const c = pet.color || '#8fe2ff';
601:   if (pet.kind === 'wisp') {
602:     p(ctx, -3, -8, 6, 6, shade(c, -0.2));
603:     p(ctx, -2, -9, 4, 8, c);
604:     p(ctx, -1, -7, 2, 2, '#fff');
605:     p(ctx, -5, -6, 1, 1, c); p(ctx, 4, -7, 1, 1, c);
606:   } else if (pet.kind === 'imp') {
607:     p(ctx, -4, -11, 8, 7, c);
608:     p(ctx, -3, -13, 2, 3, shade(c, -0.2));
609:     p(ctx, 2, -13, 2, 3, shade(c, -0.2));
610:     p(ctx, -3, -8, 1, 1, '#ffe066'); p(ctx, 2, -8, 1, 1, '#ffe066');
611:     p(ctx, -5, -10, 2, 3, shade(c, -0.25)); p(ctx, 4, -10, 2, 3, shade(c, -0.25));
