628: export function drawEnemy(ctx, e, time) {
629:   const def = e.def;
630:   const kind = def.kind;
631:   const c = def.color || '#7bd66b';
632:   const dark = shade(c, -0.22);
633:   const light = shade(c, 0.18);
634:   const run = e.state === 'chase' ? Math.sin(time * 11 + (e.anim || 0) * 6) : Math.sin(time * 2.4 + (e.anim || 0) * 1.2) * 0.25;
635:   const atk = e.attackAnim ? Math.sin(e.attackAnim * Math.PI) : 0;
636:   const bob = Math.sin(time * 3 + e.anim) * (kind === 'ghost' ? 3 : 1) - (e.state === 'chase' ? Math.abs(run) * 0.7 : 0);
637:   const s = e.scale || 1;
638:   ctx.save();
639:   ctx.scale((e.facing || 1) * s, s);
640:   ctx.translate(atk * 3.2, bob);   // lunge forward during an attack swing
641:   const flash = e.hitFlash > 0;
642:   const C = (col) => flash ? '#fff6e0' : col;
643: 
644:   switch (kind) {
645:     case 'slime': {
646:       p(ctx, -10, -10, 20, 10, C(dark));
647:       p(ctx, -9, -13, 18, 8, C(c));
648:       p(ctx, -6, -15, 12, 4, C(light));
649:       p(ctx, -5, -11, 3, 3, '#19221e');
650:       p(ctx, 3, -11, 3, 3, '#19221e');
651:       p(ctx, -1, -8, 3, 1, '#19221e');
652:       p(ctx, -7, -12, 2, 2, 'rgba(255,255,255,0.5)');
653:       break;
654:     }
655:     case 'wolf': {
656:       p(ctx, -11, -11, 20, 8, C(c));
657:       p(ctx, -11, -11, 20, 2, C(light));
658:       p(ctx, -4, -18, 7, 7, C(c));
659:       p(ctx, -12, -16, 5, 5, C(dark));
660:       p(ctx, -13, -13, 4, 3, C(dark));
661:       p(ctx, -6, -20, 2, 4, C(dark)); p(ctx, 0, -20, 2, 4, C(dark));
662:       p(ctx, -3, -15, 2, 2, '#ffd166'); p(ctx, 1, -15, 2, 2, '#ffd166');
663:       p(ctx, -9, -4, 3, 4 + run, C(dark)); p(ctx, 2, -4, 3, 4 - run, C(dark));
664:       p(ctx, -2, -13, 3, 1, '#f7f0dc');
665:       // tail
666:       p(ctx, 8, -15, 4, 2, C(dark)); p(ctx, 11, -18, 2, 4, C(dark));
667:       break;
668:     }
669:     case 'humanoid': case 'raider': {
670:       const cloth = C(c), metal = C(shade(c, -0.3));
671:       p(ctx, -5, -26, 10, 12, cloth);
672:       p(ctx, -6, -25, 12, 2, metal);
