981:       ctx.strokeStyle = 'rgba(230,196,106,0.5)';
982:       ctx.lineWidth = 1;
983:       this.roundRect(ctx, s.x - tw / 2, y - 11, tw, 16, 4);
984:       ctx.stroke();
