1022:   addLight(ctx, x, y, radius, color, alpha = 0.2) {
1023:     ctx.save();
1024:     ctx.globalCompositeOperation = 'lighter';
1025:     const g = ctx.createRadialGradient(x, y, 2, x, y, radius);
1026:     g.addColorStop(0, this.hexAlpha(color, alpha));
1027:     g.addColorStop(1, this.hexAlpha(color, 0));
1028:     ctx.fillStyle = g;
1029:     ctx.fillRect(x - radius, y - radius, radius * 2, radius * 2);
1030:     ctx.restore();
1031:   }
