21:   const n = parseInt(h.length === 3 ? h.split('').map(c => c + c).join('') : h, 16);
22:   let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
23:   r = Math.max(0, Math.min(255, Math.round(r + 255 * amt)));
24:   g = Math.max(0, Math.min(255, Math.round(g + 255 * amt)));
25:   b = Math.max(0, Math.min(255, Math.round(b + 255 * amt)));
26:   return '#' + [r, g, b].map(v => v.toString(16).padStart(2, '0')).join('');
27: }
