29: const CLASS_PAL = {
30:   warrior: { cloth: '#8f2d33', cloth2: '#5e1f2a', metal: '#aab2c2', metal2: '#646f82', trim: '#d5a44c', skin: '#efc39c', hair: '#5b3a25' },
31:   mage: { cloth: '#274a8f', cloth2: '#1a2f63', metal: '#c8a84f', metal2: '#7a6227', trim: '#79d6ff', skin: '#efc39c', hair: '#d8d2c4' },
32:   archer: { cloth: '#2f6b4f', cloth2: '#1e4736', metal: '#8f7b50', metal2: '#5a4c2e', trim: '#a8e07a', skin: '#efc39c', hair: '#7a3f22' }
33: };
