161:     this.player.attackAnim = Math.max(0, this.player.attackAnim - dt * 3.2);
162:     this.player.casting = Math.max(0, this.player.casting - dt * 2);
163:     this.screenShake = Math.max(0, this.screenShake - dt * 20);
164:     this.lootToastCd = Math.max(0, this.lootToastCd - dt);
165: 
166:     this.updatePlayer(dt, stats);
167:     this.updateEnemies(dt);
168:     this.updateProjectiles(dt);
169:     this.updateLoot(dt);
170:     this.updateEffects(dt);
171:     this.updateInteraction(dt);
172:     this.updateRegen(dt, stats);
173:     this.updateBossBar();
174: 
175:     this.marketTick += dt;
176:     if (this.marketTick > 4) {
177:       this.marketTick = 0;
178:       const sold = this.state.tickMarket();
179:       for (const s of sold) {
180:         Events.emit('toast', {
181:           msg: `Market sale: ${s.item.name} → +${fmt(s.price)} gold (simulated buyer)`,
182:           type: 'success', duration: 5200
183:         });
184:         this.sfx.play('coin');
185:       }
186:     }
187:     this.saveTick += dt;
188:     if (this.saveTick >= CONFIG.autosaveSeconds) {
189:       this.saveTick = 0;
190:       this.state.char.x = this.player.x;
191:       this.state.char.y = this.player.y;
192:       this.state.save();
193:     }
194:   }
195: 
196:   updatePlayer(dt, stats) {
197:     let sx = 0, sy = 0;
198:     if (this.input.up) sy -= 1;
199:     if (this.input.down) sy += 1;
200:     if (this.input.left) sx -= 1;
201:     if (this.input.right) sx += 1;
202:     if (Math.abs(this.input.joyX) > 0.12 || Math.abs(this.input.joyY) > 0.12) {
203:       sx = this.input.joyX;
204:       sy = this.input.joyY;
205:     }
206:     let moving = false;
207:     let vx = 0, vy = 0;
208:     if (sx || sy) {
209:       // screen direction -> isometric world direction
210:       vx = sx + sy;
211:       vy = sy - sx;
212:       const len = Math.hypot(vx, vy) || 1;
213:       vx /= len; vy /= len;
214:       this.input.moveTarget = null;
215:     } else if (this.input.moveTarget) {
216:       const mt = this.input.moveTarget;
217:       const d = Math.hypot(mt.x - this.player.x, mt.y - this.player.y);
218:       if (d < 0.18) {
219:         this.input.moveTarget = null;
220:       } else {
221:         vx = (mt.x - this.player.x) / d;
222:         vy = (mt.y - this.player.y) / d;
223:       }
224:     }
225:     if (vx || vy) {
226:       const speed = stats.moveSpeed;
227:       const nx = this.player.x + vx * speed * dt;
228:       const ny = this.player.y + vy * speed * dt;
229:       if (!isBlocked(this.world, nx, this.player.y, 0.22)) this.player.x = nx;
230:       if (!isBlocked(this.world, this.player.x, ny, 0.22)) this.player.y = ny;
231:       this.player.x = clamp(this.player.x, 1.05, this.world.size - 1.05);
232:       this.player.y = clamp(this.player.y, 1.05, this.world.size - 1.05);
233:       moving = true;
234:       if (Math.abs(vx - vy) > 0.1) {
235:         const screenDx = (vx - vy);
236:         if (Math.abs(screenDx) > 0.12) this.player.facing = screenDx > 0 ? 1 : -1;
237:       }
238:       // footstep dust
239:       if (Math.random() < dt * 7) {
240:         this.addParticle({ x: this.player.x, y: this.player.y, type: 'dust', color: '#d8c8a0', life: 0.4 });
241:       }
242:     }
243:     this.player.moving = moving;
244:     this.state.char.x = this.player.x;
245:     this.state.char.y = this.player.y;
246: 
247:     // target validity / auto-acquire
248:     if (this.target && (!this.target.alive || this.target.hp <= 0)) this.target = null;
249:     if (this.state.data.settings.autoAttack) {
250:       if (!this.target) {
251:         const near = this.nearestEnemy(stats.attackRange + 0.5);
252:         if (near) this.target = near;
253:       }
254:       if (this.target) {
255:         const d = Math.hypot(this.target.x - this.player.x, this.target.y - this.player.y);
256:         if (d <= stats.attackRange + 0.15 && this.attackCd <= 0) this.normalAttack(true);
257:       }
258:     }
259:   }
260: 
261:   updateRegen(dt, stats) {
262:     if (Date.now() - this.player.lastDamageAt > 4200) {
263:       const hp = stats.maxHp * 0.012 * dt;
264:       const mp = stats.maxMana * 0.018 * dt;
265:       if (this.state.char.hp < stats.maxHp) this.state.char.hp = Math.min(stats.maxHp, this.state.char.hp + hp);
266:       if (this.state.char.mana < stats.maxMana) this.state.char.mana = Math.min(stats.maxMana, this.state.char.mana + mp);
267:     }
268:   }
269: 
270:   // ------------------------------------------------------------
271:   // ENEMIES
272:   // ------------------------------------------------------------
273:   updateEnemies(dt) {
274:     const stats = this.state.stats();
275:     const now = Date.now();
276:     for (const e of this.world.enemies) {
277:       if (!e.alive) {
278:         if (now >= e.respawnAt) this.respawnEnemy(e);
279:         continue;
280:       }
281:       e.anim += dt;
282:       e.hitFlash = Math.max(0, e.hitFlash - dt);
283:       e.attackAnim = Math.max(0, (e.attackAnim || 0) - dt * 3);
284:       if (e.stunUntil && now < e.stunUntil) continue;
285: 
286:       const d = Math.hypot(this.player.x - e.x, this.player.y - e.y);
287:       const aggro = e.boss ? e.def.aggro + 2 : e.def.aggro;
288:       if (!e.aggroed && d < aggro && !this.player.dead) {
289:         e.aggroed = true;
290:         if (e.boss) {
291:           this.sfx.play('boss');
292:           Events.emit('toast', { msg: `${e.def.name} has noticed you!`, type: 'danger' });
293:         }
294:       }
295:       if (e.aggroed) {
296:         const homeDist = Math.hypot(e.x - e.homeX, e.y - e.homeY);
297:         if (d > 16 || homeDist > 22 || this.player.dead) {
298:           e.aggroed = false;
299:           continue;
300:         }
301:         if (d > e.def.range) {
302:           const speed = e.def.speed * (e.elite ? 1.08 : 1);
303:           const vx = (this.player.x - e.x) / d;
304:           const vy = (this.player.y - e.y) / d;
305:           const nx = e.x + vx * speed * dt;
306:           const ny = e.y + vy * speed * dt;
307:           if (!isBlocked(this.world, nx, e.y, 0.2)) e.x = nx;
308:           if (!isBlocked(this.world, e.x, ny, 0.2)) e.y = ny;
309:           e.facing = (vx - vy) > 0 ? 1 : -1;
310:           e.state = 'chase';
311:         } else {
312:           e.state = 'attack';
313:           if (!e.attackCd || e.attackCd <= now) {
314:             e.attackCd = now + e.def.attackSpeed * 1000;
315:             e.attackAnim = 1;
316:             this.enemyHitPlayer(e);
317:           }
318:         }
319:         // boss ground slam
320:         if (e.boss) {
321:           e.bossCd = (e.bossCd || 0) - dt;
322:           if (e.bossCd <= 0 && d < 5.5) {
323:             e.bossCd = 8 + Math.random() * 3;
324:             this.bossSlam(e);
325:           }
326:         }
327:       } else {
328:         // idle wander
329:         e.wanderT = (e.wanderT || 0) - dt;
330:         if (e.wanderT <= 0) {
331:           e.wanderT = 2 + Math.random() * 4;
332:           e.wanderX = e.homeX + (Math.random() - 0.5) * 4;
333:           e.wanderY = e.homeY + (Math.random() - 0.5) * 4;
334:         }
335:         const wd = Math.hypot(e.wanderX - e.x, e.wanderY - e.y);
336:         if (wd > 0.3) {
337:           const vx = (e.wanderX - e.x) / wd;
338:           const vy = (e.wanderY - e.y) / wd;
339:           const nx = e.x + vx * e.def.speed * 0.34 * dt;
340:           const ny = e.y + vy * e.def.speed * 0.34 * dt;
341:           if (!isBlocked(this.world, nx, e.y, 0.15)) e.x = nx;
342:           if (!isBlocked(this.world, e.x, ny, 0.15)) e.y = ny;
343:         }
344:       }
345:     }
346:   }
347: 
348:   enemyHitPlayer(enemy) {
349:     if (this.player.dead) return;
350:     const raw = enemy.atk * (0.85 + Math.random() * 0.3);
351:     const dmg = this.state.damagePlayer(raw);
352:     this.player.lastDamageAt = Date.now();
353:     this.screenShake = 7;
354:     this.addEffect({ type: 'dmg', x: this.player.x, y: this.player.y, text: `-${dmg}`, color: '#ff7a7a', life: 0.9, maxLife: 0.9 });
355:     this.sfx.play('hit');
356:     Events.emit('playerHit', { damage: dmg, hp: this.state.char.hp });
357:     if (this.state.char.hp <= 0) this.playerDie();
358:   }
359: 
360:   bossSlam(boss) {
361:     const d = Math.hypot(this.player.x - boss.x, this.player.y - boss.y);
362:     this.addEffect({ type: 'ring', x: boss.x, y: boss.y, radius: 3.2, color: '#ff5a3c', life: 0.75, maxLife: 0.75, width: 4 });
363:     this.sfx.play('boss');
364:     this.screenShake = 12;
365:     if (d < 3.4) {
366:       const dmg = this.state.damagePlayer(boss.atk * 1.55);
367:       this.player.lastDamageAt = Date.now();
368:       this.addEffect({ type: 'dmg', x: this.player.x, y: this.player.y, text: `-${dmg}`, color: '#ffb08a', big: true, life: 1.1, maxLife: 1.1 });
369:       if (this.state.char.hp <= 0) this.playerDie();
370:     }
371:   }
372: 
373:   respawnEnemy(enemy) {
374:     const spot = respawnPosition(this.world, enemy);
375:     enemy.x = spot.x; enemy.y = spot.y; enemy.homeX = spot.x; enemy.homeY = spot.y;
376:     enemy.hp = enemy.maxHp;
377:     enemy.alive = true;
378:     enemy.aggroed = false;
379:     enemy.stunUntil = 0;
380:     enemy.attackCd = 0;
381:     enemy.hitFlash = 0;
382:     enemy.facing = 1;
383:   }
384: 
385:   // ------------------------------------------------------------
386:   // PLAYER COMBAT
387:   // ------------------------------------------------------------
388:   nearestEnemy(maxRange = 99) {
389:     let best = null, bestD = maxRange;
390:     for (const e of this.world.enemies) {
391:       if (!e.alive) continue;
392:       const d = Math.hypot(e.x - this.player.x, e.y - this.player.y);
393:       if (d < bestD) { bestD = d; best = e; }
394:     }
395:     return best;
396:   }
397: 
398:   attackPressed() {
399:     if (this.transitioning || this.player.dead) return;
400:     const stats = this.state.stats();
401:     const near = this.nearestEnemy(stats.attackRange + 0.4);
402:     if (near) this.target = near;
403:     this.normalAttack(false);
404:   }
405: 
406:   normalAttack(auto = false) {
407:     const stats = this.state.stats();
408:     if (this.attackCd > 0) return;
409:     if (!this.target || !this.target.alive) {
410:       const near = this.nearestEnemy(stats.attackRange + 0.35);
411:       if (!near) {
412:         if (!auto) this.sfx.play('error');
413:         return;
414:       }
415:       this.target = near;
416:     }
417:     const d = Math.hypot(this.target.x - this.player.x, this.target.y - this.player.y);
418:     if (d > stats.attackRange + 0.35) {
419:       if (!auto) this.input.moveTarget = { x: this.target.x, y: this.target.y };
420:       return;
421:     }
422:     this.attackCd = stats.attackInterval;
423:     this.player.attackAnim = 1;
424:     this.player.facing = (this.target.x - this.target.y) > (this.player.x - this.player.y) ? 1 : -1;
425:     this.sfx.play('attack');
426:     const dmg = this.rollDamage(1.0);
427:     if (this.state.char.classId === 'warrior') {
428:       this.addEffect({ type: 'slash', x: this.target.x, y: this.target.y, color: '#ffe0a0', life: 0.25, maxLife: 0.25 });
429:       this.applyDamage(this.target, dmg.amount, dmg.crit);
430:     } else {
431:       this.spawnProjectile({
432:         type: this.state.char.classId === 'archer' ? 'arrow' : 'fire',
433:         target: this.target, amount: dmg.amount, crit: dmg.crit,
434:         speed: this.state.char.classId === 'archer' ? 14 : 9,
435:         color: this.state.char.classId === 'archer' ? '#e8dcc0' : '#ffb23e'
436:       });
437:     }
438:   }
439: 
440:   skillPressed() {
441:     if (this.transitioning || this.player.dead) return;
442:     const stats = this.state.stats();
443:     const skill = this.state.cls.skill;
444:     if (this.skillCd > 0) {
445:       Events.emit('toast', { msg: `${skill.name} is on cooldown (${this.skillCd.toFixed(1)}s).`, type: 'warn', small: true });
446:       this.sfx.play('error');
447:       return;
448:     }
449:     if (this.state.char.mana < skill.mana) {
450:       Events.emit('toast', { msg: 'Not enough mana.', type: 'warn', small: true });
451:       this.sfx.play('error');
452:       return;
453:     }
454:     this.state.char.mana -= skill.mana;
455:     this.skillCd = skill.cooldown;
456:     this.player.casting = 1;
457:     this.sfx.play('skill');
458: 
459:     const level = this.state.char.skillLevel;
460:     const mult = skill.multiplier * (1 + (level - 1) * 0.16);
461:     const radius = skill.radius + (level - 1) * 0.06;
462:     const targets = this.world.enemies.filter(e => e.alive && Math.hypot(e.x - this.player.x, e.y - this.player.y) <= radius);
463:     this.addEffect({ type: 'ring', x: this.player.x, y: this.player.y, radius, color: skill.id === 'nova' ? '#79d6ff' : skill.id === 'whirlwind' ? '#ffb23e' : '#a8e07a', life: 0.5, maxLife: 0.5, width: 4 });
464:     this.addEffect({ type: 'burst', x: this.player.x, y: this.player.y, color: '#ffe08a', life: 0.55, maxLife: 0.55 });
465: 
466:     if (skill.id === 'whirlwind') {
467:       for (const e of targets) {
468:         const dmg = this.rollDamage(mult);
469:         this.applyDamage(e, dmg.amount, dmg.crit);
470:       }
471:       if (!targets.length) Events.emit('toast', { msg: 'Whirlwind strikes empty air.', type: 'warn', small: true });
472:       this.screenShake = 4;
473:     } else if (skill.id === 'nova') {
474:       for (const e of targets) {
475:         const dmg = this.rollDamage(mult);
476:         this.applyDamage(e, dmg.amount, dmg.crit);
477:         e.stunUntil = Date.now() + 1200;
478:         this.addEffect({ type: 'burst', x: e.x, y: e.y, color: '#79d6ff', life: 0.4, maxLife: 0.4 });
479:       }
480:     } else {
481:       const volley = targets.slice(0, 6);
482:       if (!volley.length) {
483:         const t = this.nearestEnemy(radius + 2);
484:         if (t) volley.push(t);
485:       }
486:       for (const e of volley) {
487:         const dmg = this.rollDamage(mult);
488:         this.spawnProjectile({ type: 'arrow', target: e, amount: dmg.amount, crit: dmg.crit, speed: 18, color: '#d7ffb0' });
489:       }
490:       if (!volley.length) Events.emit('toast', { msg: 'Arrow Storm finds no target.', type: 'warn', small: true });
491:     }
492:     Events.emit('skillUsed', { skill, level });
493:   }
494: 
495:   rollDamage(mult = 1) {
496:     const stats = this.state.stats();
497:     const variance = 0.9 + Math.random() * 0.2;
498:     const crit = Math.random() < stats.crit;
499:     let amount = stats.attack * mult * variance;
500:     if (crit) amount *= stats.critDamage;
501:     return { amount: Math.max(1, Math.round(amount)), crit };
502:   }
503: 
504:   applyDamage(enemy, amount, crit) {
505:     if (!enemy.alive) return;
506:     enemy.hp -= amount;
507:     enemy.hitFlash = 0.12;
508:     this.addEffect({
509:       type: 'dmg', x: enemy.x, y: enemy.y,
510:       text: crit ? `${fmt(amount)}!` : fmt(amount),
511:       color: crit ? '#ffd166' : '#ffe8d0', big: crit,
512:       dx: (Math.random() - 0.5) * 24, offset: Math.random() * 8,
513:       life: 0.85, maxLife: 0.85
514:     });
515:     this.sfx.play(crit ? 'crit' : 'hit');
516:     if (enemy.hp <= 0) this.killEnemy(enemy);
517:     Events.emit('enemyHit', { enemy, amount, crit });
518:   }
519: 
520:   spawnProjectile(opts) {
521:     this.projectiles.push({
522:       type: opts.type,
523:       x: this.player.x, y: this.player.y,
524:       target: opts.target, speed: opts.speed || 12,
525:       amount: opts.amount, crit: opts.crit,
526:       color: opts.color, life: 3
527:     });
528:   }
529: 
530:   updateProjectiles(dt) {
531:     for (const pr of [...this.projectiles]) {
532:       pr.life -= dt;
533:       if (!pr.target || !pr.target.alive || pr.life <= 0) {
534:         this.projectiles = this.projectiles.filter(p => p !== pr);
535:         continue;
536:       }
537:       const d = Math.hypot(pr.target.x - pr.x, pr.target.y - pr.y);
538:       if (d < 0.35) {
539:         this.applyDamage(pr.target, pr.amount, pr.crit);
540:         this.projectiles = this.projectiles.filter(p => p !== pr);
541:         continue;
542:       }
543:       const step = Math.min(d, pr.speed * dt);
544:       pr.x += (pr.target.x - pr.x) / d * step;
545:       pr.y += (pr.target.y - pr.y) / d * step;
546:     }
547:   }
548: 
549:   // ------------------------------------------------------------
550:   // DEATH & LOOT
551:   // ------------------------------------------------------------
552:   killEnemy(enemy) {
553:     if (!enemy.alive) return;
554:     enemy.alive = false;
555:     enemy.hp = 0;
556:     enemy.deadT = Date.now();
557:     const def = enemy.def;
558:     const boss = def.boss;
559:     enemy.respawnAt = Date.now() + (boss ? CONFIG.combat.bossRespawnSeconds : enemy.elite ? CONFIG.combat.eliteRespawnSeconds : CONFIG.combat.respawnSeconds) * 1000;
560:     this.state.onKill(enemy.type);
561: 
562:     const rawGold = Math.round(enemy.gold * (CONFIG.drops.goldVariance[0] + Math.random() * (CONFIG.drops.goldVariance[1] - CONFIG.drops.goldVariance[0])));
563:     this.state.addGold(rawGold, 'monster', def.name);
564:     this.state.gainXp(enemy.xp, 'combat');
565:     this.addEffect({ type: 'dmg', x: enemy.x, y: enemy.y, text: `+${fmt(rawGold)}g`, color: '#ffd166', life: 1.2, maxLife: 1.2, offset: 16 });
566:     this.sfx.play('coin');
567: 
568:     const drops = [];
569:     // equipment (always T3)
570:     let gearRolls = 0;
571:     if (Math.random() < CONFIG.drops.equipmentChance) gearRolls = 1;
572:     if (boss) gearRolls = 1 + (Math.random() < (CONFIG.drops.bossEquipmentChance - 1) ? 1 : 0);
573:     if (enemy.elite && Math.random() < 0.25) gearRolls = Math.max(gearRolls, 1);
574:     for (let i = 0; i < gearRolls; i++) {
575:       const item = this.state.rollEquipmentDrop({ level: enemy.level }, { preferPlayer: boss });
576:       if (item) {
577:         this.groundLoot.push({ lid: uid('loot'), x: enemy.x + (Math.random() - 0.5) * 0.9, y: enemy.y + (Math.random() - 0.5) * 0.9, item, kind: 'equip', expires: Date.now() + 120000, bob: Math.random() * 6 });
578:         drops.push(item.name);
579:       }
580:     }
581:     // boss stones
582:     if (Math.random() < CONFIG.drops.stoneChance || boss) {
583:       const count = boss ? (enemy.level >= 40 ? 2 : 1) : 1;
584:       for (let i = 0; i < count; i++) {
585:         const stone = this.state.rollStone({ level: enemy.level });
586:         this.groundLoot.push({ lid: uid('loot'), x: enemy.x + (Math.random() - 0.5) * 1.1, y: enemy.y + (Math.random() - 0.5) * 1.1, item: stone, kind: 'stone', expires: Date.now() + 120000, bob: Math.random() * 6 });
587:         drops.push(stone.name);
588:       }
589:     }
590:     // region material
591:     if (Math.random() < CONFIG.drops.materialChance || boss) {
592:       const mat = this.world.region.material;
593:       const count = boss ? 2 : 1;
594:       for (let i = 0; i < count; i++) {
595:         this.groundLoot.push({
596:           lid: uid('loot'), x: enemy.x + (Math.random() - 0.5) * 1.1, y: enemy.y + (Math.random() - 0.5) * 1.1,
597:           item: { uid: uid('mat'), kind: 'material', materialId: mat.id, name: mat.name, icon: mat.icon, count: 1 },
598:           kind: 'material', expires: Date.now() + 120000, bob: Math.random() * 6
599:         });
600:       }
601:       drops.push(`${mat.name} ×${count}`);
602:     }
603:     // boss core (legendary crafting)
604:     if (boss) {
605:       this.groundLoot.push({
606:         lid: uid('loot'), x: enemy.x, y: enemy.y + 0.5,
607:         item: { uid: uid('mat'), kind: 'material', materialId: 'mat_primordial_core', name: 'Primordial Core', icon: '◉', count: 1 },
608:         kind: 'material', expires: Date.now() + 180000, bob: 0, special: true
609:       });
610:       drops.push('Primordial Core');
611:       this.sfx.play('level');
612:       Events.emit('toast', { msg: `${def.name} defeated! Boss loot dropped.`, type: 'success', duration: 5500 });
613:       if (this.currentDungeon && !this.dungeonCleared && def.id === this.currentDungeon.boss) {
614:         this.dungeonCleared = true;
615:         this.state.char.dungeons = (this.state.char.dungeons || 0) + 1;
616:         const bonus = 10000 + this.currentDungeon.level * 500;
