934:   handleTap(sx, sy) {
935:     const world = this.world;
936:     if (!world) return;
937:     // enemy click (screen distance)
938:     let picked = null, pickedD = 42;
939:     for (const e of world.enemies) {
940:       if (!e.alive) continue;
941:       const s = this.renderer.worldToScreen(e.x, e.y);
942:       const d = Math.hypot(s.x - sx, s.y - (sy + 18));
943:       if (d < pickedD + (e.boss ? 26 : 0)) { picked = e; pickedD = d; }
944:     }
945:     if (picked) {
946:       this.target = picked;
947:       const stats = this.state.stats();
948:       const d = Math.hypot(picked.x - this.player.x, picked.y - this.player.y);
949:       if (d > stats.attackRange + 0.2) {
950:         this.input.moveTarget = { x: picked.x, y: picked.y };
951:       } else {
952:         this.normalAttack(false);
953:       }
954:       return;
955:     }
956:     // npc click
957:     for (const npc of world.npcs) {
958:       const s = this.renderer.worldToScreen(npc.x, npc.y);
959:       if (Math.hypot(s.x - sx, s.y - (sy + 20)) < 34) {
960:         const d = Math.hypot(npc.x - this.player.x, npc.y - this.player.y);
961:         if (d < 2.6) {
962:           Events.emit('npc', npc);
963:         } else {
964:           this.input.moveTarget = { x: npc.x + 0.9, y: npc.y + 0.9 };
965:         }
966:         return;
967:       }
968:     }
969:     // node / chest click
970:     for (const node of world.nodes) {
971:       if (node.respawnAt > Date.now()) continue;
972:       const s = this.renderer.worldToScreen(node.x, node.y);
973:       if (Math.hypot(s.x - sx, s.y - (sy + 12)) < 28) {
974:         const d = Math.hypot(node.x - this.player.x, node.y - this.player.y);
975:         if (d < 2.1) this.gatherNode(node);
976:         else this.input.moveTarget = { x: node.x, y: node.y };
977:         return;
978:       }
979:     }
980:     // ground move
981:     const w = this.renderer.screenToWorld(sx, sy);
982:     if (w.x > 1 && w.y > 1 && w.x < world.size - 1 && w.y < world.size - 1 && !isBlocked(world, w.x, w.y, 0.2)) {
983:       this.input.moveTarget = { x: w.x, y: w.y };
984:       this.target = null;
985:     }
986:   }
