566:   equipmentAura() {
567:     let best = null;
568:     for (const s of SLOTS) {
569:       const it = this.state.data.equipped[s.id];
570:       if (!it) continue;
571:       const score = (8 - it.tier) * 10 + (RARITIES[it.rarity]?.order || 0) * 4;
572:       if (!best || score > best.score) best = { score, tier: it.tier, rarity: it.rarity };
573:     }
574:     if (!best) return null;
575:     if (best.tier === 3 && (RARITIES[best.rarity]?.order || 0) < 4) return null;
576:     return { color: RARITIES[best.rarity].color, strength: best.tier === 1 ? 3 : best.tier === 2 ? 2 : 1 };
