898:     // equipment aura
899:     const aura = this.equipmentAura(state);
900:     if (aura) {
901:       this.addLight(ctx, s.x, s.y - 45, 80 + aura.strength * 20, aura.color, 0.13 + aura.strength * 0.05);
902:       ctx.save();
903:       ctx.globalAlpha = 0.25 + aura.strength * 0.08;
904:       ctx.strokeStyle = aura.color;
905:       ctx.lineWidth = 1.5;
906:       ctx.beginPath();
907:       ctx.ellipse(s.x, s.y, 26 + aura.strength * 5, 10 + aura.strength * 2, 0, 0, Math.PI * 2);
908:       ctx.stroke();
909:       ctx.restore();
910:     }
911:     this.drawShadow(ctx, s.x, s.y, mount ? 24 : 13, mount ? 0.32 : 0.26);
912: 
913:     // arcane sigil while casting
914:     if (game.player.casting) {
915:       const sigC = c.classId === 'mage' ? '#79d6ff' : '#ffb23e';
916:       ctx.save();
917:       ctx.globalAlpha = 0.4 + Math.sin(this.time * 9) * 0.15;
918:       ctx.strokeStyle = sigC;
919:       ctx.lineWidth = 1.4;
920:       ctx.beginPath();
921:       ctx.ellipse(s.x, s.y, 16, 7, 0, 0, Math.PI * 2);
922:       ctx.stroke();
923:       ctx.globalAlpha *= 0.7;
924:       ctx.beginPath();
925:       ctx.ellipse(s.x, s.y, 9, 4, 0, 0, Math.PI * 2);
926:       ctx.stroke();
927:       const spin = this.time * 6;
928:       for (let i = 0; i < 6; i++) {
929:         const a = spin + i * Math.PI / 3;
930:         ctx.fillStyle = sigC;
931:         ctx.fillRect(s.x + Math.cos(a) * 16, s.y + Math.sin(a) * 7, 1.5, 1.5);
932:       }
933:       ctx.restore();
934:     }
935: 
936:     ctx.save();
937:     ctx.translate(s.x, s.y);
938:     ctx.scale(S, S);
939:     drawCharacter(ctx, {
940:       faction: c.faction, classId: c.classId, gender: c.gender,
941:       hairStyle: c.hair, hairColor: state.hairColorHex(), eyeColor: state.eyeColorHex(),
942:       equipment: eq, wings, mount, cosmetic,
943:       time: this.time, moving: game.player.moving,
944:       facing: game.player.facing || 1,
945:       attack: game.player.attackAnim,
946:       casting: game.player.casting,
947:       aura: aura,
948:       weaponFx: state.weaponFxDef()
949:     });
950:     ctx.restore();
951: 
952:     // weapon fx particles
953:     if (state.weaponFxDef()) {
954:       const fx = state.weaponFxDef();
955:       ctx.save();
956:       ctx.globalAlpha = 0.6;
957:       for (let i = 0; i < 3; i++) {
958:         const a = this.time * 2 + i * 2.1;
959:         ctx.fillStyle = fx.color;
960:         ctx.fillRect(s.x + Math.cos(a) * 18, s.y - 40 + Math.sin(a * 1.3) * 22, 2, 2);
961:       }
962:       ctx.restore();
963:     }
