508: export function drawMount(ctx, mount, time, moving) {
509:   const kind = mount.kind || 'horse';
510:   const c = mount.color || '#8a5a3c';
511:   const dark = shade(c, -0.2);
512:   const light = shade(c, 0.15);
513:   const gait = moving ? Math.sin(time * 12) : Math.sin(time * 2) * 0.3;
514:   const leg1 = Math.round(gait * 3);
515:   const leg2 = Math.round(-gait * 3);
516: 
517:   if (kind === 'horse') {
518:     p(ctx, -13, -18, 26, 10, c);
519:     p(ctx, -13, -18, 26, 3, light);
520:     p(ctx, -12, -8, 7, 4, dark);
521:     p(ctx, 5, -8, 7, 4, dark);
522:     // legs
523:     p(ctx, 9, -9, 3, 9 + leg1, dark); p(ctx, 10, -1 + leg1, 4, 2, '#2e2118');
524:     p(ctx, -10, -9, 3, 9 + leg2, dark); p(ctx, -11, -1 + leg2, 4, 2, '#2e2118');
525:     p(ctx, 5, -9, 3, 8 - leg1, c); p(ctx, 5, 0 - leg1, 4, 2, '#2e2118');
526:     p(ctx, -5, -9, 3, 8 - leg2, c); p(ctx, -6, 0 - leg2, 4, 2, '#2e2118');
527:     // neck + head
528:     p(ctx, 13, -27, 5, 12, c);
529:     p(ctx, 16, -29, 8, 6, c);
530:     p(ctx, 23, -27, 4, 4, light);
531:     p(ctx, 16, -31, 2, 3, dark);
532:     px(ctx, 22, -27, 1, 1, '#120e18');
533:     // mane/tail
534:     p(ctx, 12, -28, 2, 10, dark);
535:     p(ctx, -14, -19, 2, 9, dark);
536:     p(ctx, -15, -11, 2, 4, dark);
537:     // saddle
538:     p(ctx, -5, -21, 10, 4, '#7a2c2c');
539:     p(ctx, -5, -21, 10, 1, '#d5a44c');
540:   } else if (kind === 'wolf') {
541:     p(ctx, -14, -16, 25, 9, c);
542:     p(ctx, -14, -16, 25, 3, light);
543:     p(ctx, -11, -21, 7, 7, c);
544:     p(ctx, 5, -21, 8, 7, c);
545:     // legs
546:     p(ctx, 8, -7, 3, 7 + leg1, dark); p(ctx, 8, 0 + leg1, 4, 2, dark);
547:     p(ctx, -10, -7, 3, 7 + leg2, dark); p(ctx, -10, 0 + leg2, 4, 2, dark);
548:     p(ctx, 4, -7, 3, 7 - leg1, c);
549:     p(ctx, -5, -7, 3, 7 - leg2, c);
550:     // head
551:     p(ctx, 14, -24, 7, 8, c);
552:     p(ctx, 19, -21, 5, 4, light);
553:     px(ctx, 22, -22, 1, 1, '#0d0b12');
554:     p(ctx, 14, -27, 2, 4, dark); p(ctx, 18, -27, 2, 4, dark);
555:     p(ctx, 19, -18, 2, 1, '#f2e7d0');
556:     // tail
557:     p(ctx, -15, -14, 3, 5, dark); p(ctx, -17, -10, 3, 3, dark);
558:     // saddle
559:     p(ctx, -4, -19, 9, 4, '#3c2a4a');
560:     p(ctx, -4, -19, 9, 1, '#b18cff');
561:   } else { // drake
562:     ctx.save();
563:     ctx.translate(0, 0);
564:     // wings
565:     p(ctx, -1, -30, 8, 2, shade(c, -0.05));
566:     p(ctx, -10, -32, 8, 3, shade(c, 0.1));
567:     p(ctx, 12, -28, 8, 3, shade(c, 0.1));
568:     // body
569:     p(ctx, -12, -18, 25, 11, c);
570:     p(ctx, -12, -18, 25, 3, light);
571:     p(ctx, -13, -9, 4, 5, dark);
572:     p(ctx, 9, -9, 4, 5, dark);
573:     // legs
574:     p(ctx, 7, -9, 3, 9 + leg1, dark); p(ctx, 7, 0 + leg1, 5, 2, '#2a1b16');
575:     p(ctx, -9, -9, 3, 9 + leg2, dark); p(ctx, -9, 0 + leg2, 5, 2, '#2a1b16');
576:     // neck/head
577:     p(ctx, 13, -27, 5, 10, c);
578:     p(ctx, 16, -30, 8, 6, c);
579:     p(ctx, 23, -28, 5, 4, light);
