1010:   drawGroundLights(ctx, world) {
1011:     // static warm pools around campfires and forges (flickering gently)
1012:     const vw = this.viewW(), vh = this.viewH();
1013:     for (const prop of world.props) {
1014:       if (!['campfire', 'forge', 'brazier'].includes(prop.kind)) continue;
1015:       const s = this.worldToView(prop.x, prop.y);
1016:       if (s.x < -120 || s.x > vw + 120 || s.y < -80 || s.y > vh + 80) continue;
1017:       const fl = 0.9 + Math.sin(this.time * 7 + prop.x * 3) * 0.08 + Math.sin(this.time * 3.1 + prop.y) * 0.05;
1018:       this.addLight(ctx, s.x, s.y - 8, (prop.kind === 'forge' ? 100 : 70) * fl, '#ff9a4a', 0.16);
1019:     }
1020:   }
