381:   updateHUD(game) {
382:     const state = this.state;
383:     if (!state?.data || !state.char) return;
384:     this.game = game || this.game;
385:     const c = state.char;
386:     const st = state.stats();
387:     this.el.hudName.textContent = c.name;
388:     this.el.hudClass.textContent = `${FACTIONS[c.faction].name.replace(/s$/, '')} ${CLASSES[c.classId].name}`;
389:     this.el.hudLevel.textContent = c.level;
390:     this.el.hudGold.textContent = fmt(c.gold);
391:     this.el.hudGems.textContent = fmt(c.gems);
392:     const hp = Math.max(0, Math.round(c.hp));
393:     const mp = Math.max(0, Math.round(c.mana));
394:     this.el.hpFill.style.width = `${Math.min(100, hp / st.maxHp * 100)}%`;
395:     this.el.hpText.textContent = `${hp} / ${st.maxHp}`;
396:     this.el.manaFill.style.width = `${Math.min(100, mp / st.maxMana * 100)}%`;
397:     this.el.manaText.textContent = `${mp} / ${st.maxMana}`;
398:     const xpNeed = state.xpToNext();
399:     this.el.xpFill.style.width = `${Math.min(100, c.xp / xpNeed * 100)}%`;
400:     this.el.xpText.textContent = `${Math.floor(c.xp)} / ${xpNeed}`;
401:     this.el.hudRegion.textContent = this.game?.currentDungeon ? this.game.currentDungeon.name : state.region().name;
402:     this.el.minimapRegion.textContent = this.game?.currentDungeon ? 'Dungeon' : state.region().name;
403:     this.el.minimapCoords.textContent = `${Math.round(c.x)}, ${Math.round(c.y)}`;
404:     this.el.portraitIcon.textContent = this.classIcon();
405:     this.el.potionCount.textContent = String(
406:       (c.consumables.health_large || 0) + (c.consumables.health_medium || 0) + (c.consumables.health_small || 0)
407:     );
408: 
409:     // skill
410:     const skill = CLASSES[c.classId].skill;
411:     this.el.skillIcon.textContent = skill.icon;
412:     this.el.skillName.textContent = `${skill.name} · ${c.skillLevel}`;
413:     const cd = this.game?.skillCd || 0;
414:     const cdPct = cd > 0 ? cd / skill.cooldown : 0;
415:     this.el.skillCdMask.style.setProperty('--cd', `${cdPct * 360}deg`);
416:     this.el.skillCdText.textContent = cd > 0 ? cd.toFixed(1) : '';
417:     this.el.btnSkill.style.opacity = c.mana < skill.mana ? '0.55' : '1';
418: 
419:     // interact
420:     const target = this.game?.interactTarget;
421:     this.el.interactPrompt.classList.toggle('hidden', !target);
422:     this.el.btnInteract.classList.toggle('interact-ready', !!target);
423:     if (target) {
424:       this.el.interactText.textContent = this.game.interactLabel;
425:     }
426:     // mount / auto
427:     this.el.btnMount.classList.toggle('active', !!c.mountActive);
428:     const mountKind = state.mountDef()?.kind;
429:     this.el.btnMount.querySelector('span').textContent = ({ horse: '🐎', wolf: '🐺', drake: '🐉' })[mountKind] || '🐎';
430:     this.el.btnAuto.classList.toggle('active', !!state.data.settings.autoAttack);
431: 
432:     // quest tracker
433:     const tracked = state.trackQuest();
434:     if (!tracked) {
435:       this.el.questTracker.classList.add('hidden');
436:     } else {
437:       this.el.questTracker.classList.remove('hidden');
438:       const q = tracked.def;
439:       const progress = state.questProgress(q);
440:       const complete = progress >= q.required;
441:       this.el.qtTitle.textContent = q.title;
442:       this.el.qtDesc.textContent = q.desc;
443:       this.el.qtFill.style.width = `${Math.min(100, progress / q.required * 100)}%`;
444:       this.el.qtCount.textContent = complete ? 'Ready to claim — tap here' : `${progress} / ${q.required}`;
445:       this.el.qtFill.style.background = complete ? 'linear-gradient(90deg,#3a9f57,#7dffc1)' : '';
446:     }
447:     this.updateMinimap();
448:   }
