683:           <span class="tag ${can.ok ? 'green' : 'red'}">${this.itemRestriction(item)} only</span>
684:         </div>
685:         ${item.bonuses?.length ? `<div class="row wrap mt8">${item.bonuses.map(b => `<span class="tag green">${BONUS_STATS[b.stat].icon} +${b.value}${b.stat === 'crit' ? '%' : ''}</span>`).join('')}</div>` : ''}
686:         <div class="row wrap mt12">
687:           ${equippedSlot
688:             ? `<button class="btn btn-sm" data-act="unequip" data-slot="${equippedSlot}">Unequip</button>`
689:             : insideInventory && can.ok
