127:       p(ctx, -shoulder - 3, -31, 2, 3, '#7a2335');
128:       p(ctx, shoulder + 1, -31, 2, 3, '#7a2335');
129:     } else {
130:       p(ctx, -shoulder + 4, -29, 2, 2, pal.trim);
131:       p(ctx, shoulder - 6, -29, 2, 2, pal.trim);
132:     }
133:   } else if (o.classId === 'mage') {
134:     p(ctx, -shoulder + 1, -29, shoulder * 2 - 2, 12, chestPrimary);
135:     p(ctx, -shoulder + 3, -27, shoulder * 2 - 6, 4, shade(chestPrimary, 0.12));
136:     p(ctx, -8, -18, 16, 3, pal.trim);
137:     // robe trim
138:     p(ctx, -1, -29, 2, 11, pal.trim);
139:     p(ctx, -5, -25, 3, 3, shade(chestPrimary, 0.2));
140:     // shoulder mantle
141:     p(ctx, -shoulder, -29, 5, 4, pal.cloth2);
142:     p(ctx, shoulder - 5, -29, 5, 4, pal.cloth2);
143:     p(ctx, -shoulder, -29, 5, 1, pal.trim);
144:     p(ctx, shoulder - 5, -29, 5, 1, pal.trim);
145:   } else {
146:     p(ctx, -shoulder + 1, -29, shoulder * 2 - 2, 12, pal.cloth);
147:     p(ctx, -shoulder + 2, -27, shoulder * 2 - 4, 6, shade(chestPrimary, 0.02));
148:     p(ctx, -shoulder + 1, -29, shoulder * 2 - 2, 2, pal.cloth2);
149:     // leather straps
150:     p(ctx, -5, -28, 2, 11, pal.metal2);
151:     p(ctx, 3, -28, 2, 11, pal.metal2);
152:     p(ctx, -5, -24, 10, 2, pal.metal2);
153:     p(ctx, -shoulder + 1, -18, shoulder * 2 - 2, 3, pal.cloth2);
154:     p(ctx, -2, -18, 4, 2, pal.trim);
155:   }
156: 
157:   // necklace / chain / earrings
158:   if (eq.necklace) {
159:     p(ctx, -3, -30, 6, 1, '#d9b45a');
160:     p(ctx, -1, -29, 2, 3, EQUIP_COLOR(eq.necklace.rarity, '#d9b45a'));
161:     p(ctx, -1, -27, 1, 1, '#fff3c4');
162:   }
163:   if (eq.chain) {
164:     p(ctx, -7, -18, 14, 1, EQUIP_COLOR(eq.chain.rarity, '#c8a84f'));
165:     p(ctx, -5, -17, 1, 1, '#f5df9a');
166:     p(ctx, 3, -17, 1, 1, '#f5df9a');
167:   }
168: 
169:   // ---- head ----
170:   const headY = -43;
171:   p(ctx, -6, headY, 12, 11, skin);
172:   p(ctx, -6, headY, 12, 1, shade(skin, 0.08));
173:   p(ctx, -6, headY + 9, 12, 1, skinShade);
174:   // neck
175:   p(ctx, -2, headY + 10, 4, 3, skinShade);
176:   // eyes
177:   p(ctx, -4, headY + 5, 2, 2, '#f7f4ea');
178:   p(ctx, 2, headY + 5, 2, 2, '#f7f4ea');
179:   p(ctx, -3, headY + 5, 1, 2, o.eyeColor || '#3f8cff');
180:   p(ctx, 3, headY + 5, 1, 2, o.eyeColor || '#3f8cff');
181:   if (female) { p(ctx, -5, headY + 4, 2, 1, OUT2); p(ctx, 3, headY + 4, 2, 1, OUT2); }
182:   // mouth
183:   p(ctx, -1, headY + 9, 2, 1, shade(skin, -0.25));
184: 
185:   // horn/halo faction detail
186:   if (demon) {
187:     p(ctx, -5, headY - 3, 2, 3, '#3d1f2b');
188:     p(ctx, -6, headY - 5, 2, 3, '#5c2637');
189:     p(ctx, 3, headY - 3, 2, 3, '#3d1f2b');
190:     p(ctx, 4, headY - 5, 2, 3, '#5c2637');
