628: export function drawEnemy(ctx, e, time) {
629:   const def = e.def;
630:   const kind = def.kind;
631:   const c = def.color || '#7bd66b';
632:   const dark = shade(c, -0.22);
633:   const light = shade(c, 0.18);
634:   const run = e.state === 'chase' ? Math.sin(time * 11 + (e.anim || 0) * 6) : Math.sin(time * 2.4 + (e.anim || 0) * 1.2) * 0.25;
635:   const atk = e.attackAnim ? Math.sin(e.attackAnim * Math.PI) : 0;
636:   const bob = Math.sin(time * 3 + e.anim) * (kind === 'ghost' ? 3 : 1) - (e.state === 'chase' ? Math.abs(run) * 0.7 : 0);
637:   const s = e.scale || 1;
638:   ctx.save();
639:   ctx.scale((e.facing || 1) * s, s);
640:   ctx.translate(atk * 3.2, bob);   // lunge forward during an attack swing
641:   const flash = e.hitFlash > 0;
642:   const C = (col) => flash ? '#fff6e0' : col;
643: 
644:   switch (kind) {
645:     case 'slime': {
646:       p(ctx, -10, -10, 20, 10, C(dark));
647:       p(ctx, -9, -13, 18, 8, C(c));
648:       p(ctx, -6, -15, 12, 4, C(light));
649:       p(ctx, -5, -11, 3, 3, '#19221e');
650:       p(ctx, 3, -11, 3, 3, '#19221e');
651:       p(ctx, -1, -8, 3, 1, '#19221e');
652:       p(ctx, -7, -12, 2, 2, 'rgba(255,255,255,0.5)');
653:       break;
654:     }
655:     case 'wolf': {
656:       p(ctx, -11, -11, 20, 8, C(c));
657:       p(ctx, -11, -11, 20, 2, C(light));
658:       p(ctx, -4, -18, 7, 7, C(c));
659:       p(ctx, -12, -16, 5, 5, C(dark));
660:       p(ctx, -13, -13, 4, 3, C(dark));
661:       p(ctx, -6, -20, 2, 4, C(dark)); p(ctx, 0, -20, 2, 4, C(dark));
662:       p(ctx, -3, -15, 2, 2, '#ffd166'); p(ctx, 1, -15, 2, 2, '#ffd166');
663:       p(ctx, -9, -4, 3, 4 + run, C(dark)); p(ctx, 2, -4, 3, 4 - run, C(dark));
664:       p(ctx, -2, -13, 3, 1, '#f7f0dc');
665:       // tail
666:       p(ctx, 8, -15, 4, 2, C(dark)); p(ctx, 11, -18, 2, 4, C(dark));
667:       break;
668:     }
669:     case 'humanoid': case 'raider': {
670:       const cloth = C(c), metal = C(shade(c, -0.3));
671:       p(ctx, -5, -26, 10, 12, cloth);
672:       p(ctx, -6, -25, 12, 2, metal);
673:       p(ctx, -5, -14, 4, 9, '#3a2c22');
674:       p(ctx, 2, -14, 4, 9, '#3a2c22');
675:       p(ctx, -4, -35, 8, 9, C('#d6a37a'));
676:       p(ctx, -5, -37, 10, 4, metal);
677:       p(ctx, -3, -31, 2, 2, '#1b141d'); p(ctx, 2, -31, 2, 2, '#1b141d');
678:       // weapon raises over the head while striking
679:       const wr = Math.round(atk * 4);
680:       p(ctx, 8, -30 - wr, 2, 20, '#8a6a45');
681:       p(ctx, 6, -32 - wr, 6, 2, '#c7ccd6');
682:       break;
683:     }
684:     case 'tree': {
685:       p(ctx, -6, -26, 12, 26, C('#5a3f27'));
686:       p(ctx, -10, -38, 20, 14, C(dark));
687:       p(ctx, -8, -45, 16, 10, C(c));
688:       p(ctx, -12, -34, 8, 8, C(c));
689:       p(ctx, 4, -33, 7, 7, C(light));
690:       p(ctx, -5, -28, 3, 3, '#ffb23e'); p(ctx, 2, -28, 3, 3, '#ffb23e');
691:       p(ctx, -4, -22, 8, 2, '#2b1d14');
692:       p(ctx, -11, -42, 4, 3, C(light));
693:       break;
694:     }
695:     case 'boar': {
696:       p(ctx, -12, -12, 23, 10, C(c));
697:       p(ctx, -12, -12, 23, 3, C(light));
698:       p(ctx, -6, -19, 10, 8, C(c));
699:       p(ctx, -9, -21, 3, 4, C(dark)); p(ctx, 1, -21, 3, 4, C(dark));
700:       p(ctx, -12, -8, 4, 3, '#f2e5c8');
701:       p(ctx, -12, -8, 2, 4, '#f7f0dc');
702:       p(ctx, -7, -16, 2, 2, '#ff5a3c');
703:       p(ctx, -9, -3, 3, 4 + run, C(dark)); p(ctx, 2, -3, 3, 4 - run, C(dark));
704:       p(ctx, -3, -10, 2, 2, '#5a3a24');
705:       break;
706:     }
707:     case 'golem': {
708:       const rock = C(c), rockD = C(dark);
709:       p(ctx, -11, -30, 22, 20, rock);
710:       p(ctx, -8, -34, 16, 6, rockD);
711:       p(ctx, -14, -28, 5, 12, rockD);
712:       p(ctx, 9, -28, 5, 12, rockD);
713:       p(ctx, -10, -12, 6, 12, rockD);
714:       p(ctx, 4, -12, 6, 12, rockD);
715:       p(ctx, -7, -38, 14, 8, rock);
716:       p(ctx, -4, -35, 3, 3, '#ffb23e'); p(ctx, 2, -35, 3, 3, '#ffb23e');
717:       p(ctx, -6, -26, 3, 3, C(light)); p(ctx, 5, -20, 3, 4, C(light));
718:       break;
719:     }
720:     case 'spider': {
721:       for (const [sx, sy, ex, ey] of [[-5,-12,-16,-3],[-4,-13,-12,2],[4,-12,14,-3],[5,-13,12,2],[-4,-8,-13,-9],[4,-8,12,-9]]) {
722:         ctx.strokeStyle = C(dark); ctx.lineWidth = 2;
723:         ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke();
724:       }
725:       p(ctx, -9, -18, 18, 11, C(c));
726:       p(ctx, -7, -21, 14, 6, C(light));
727:       p(ctx, -5, -18, 3, 3, '#ff4d6d'); p(ctx, 2, -18, 3, 3, '#ff4d6d');
728:       p(ctx, -3, -14, 6, 1, C(dark));
729:       break;
730:     }
731:     case 'lurker': case 'toad': {
732:       const wide = kind === 'toad' ? 14 : 11;
733:       p(ctx, -wide, -13, wide * 2, 13, C(c));
734:       p(ctx, -wide + 2, -17, wide * 2 - 4, 6, C(light));
735:       p(ctx, -6, -17, 4, 4, '#ffd166'); p(ctx, 2, -17, 4, 4, '#ffd166');
736:       p(ctx, -8, -4, 4, 4, C(dark)); p(ctx, 4, -4, 4, 4, C(dark));
737:       p(ctx, -4, -8, 8, 2, C(dark));
738:       if (kind === 'toad') {
739:         p(ctx, -9, -11, 2, 3, C(light)); p(ctx, 7, -11, 2, 3, C(light));
740:       } else {
741:         p(ctx, -12, -10, 3, 8, C(dark)); p(ctx, 9, -10, 3, 8, C(dark));
742:       }
743:       break;
744:     }
745:     case 'ghost': {
746:       ctx.globalAlpha = 0.85;
747:       p(ctx, -8, -28, 16, 16, C(c));
748:       p(ctx, -7, -33, 14, 7, C(light));
749:       p(ctx, -9, -30, 3, 8, C(dark)); p(ctx, 6, -30, 3, 8, C(dark));
750:       p(ctx, -5, -25, 3, 3, '#1a1a2a'); p(ctx, 2, -25, 3, 3, '#1a1a2a');
751:       p(ctx, -6, -15, 12, 10, C(c));
752:       p(ctx, -6, -6, 3, 4, 'rgba(180,220,255,0.35)');
753:       p(ctx, 0, -9, 3, 6, 'rgba(180,220,255,0.35)');
754:       p(ctx, 5, -6, 2, 3, 'rgba(180,220,255,0.3)');
755:       ctx.globalAlpha = 1;
756:       break;
757:     }
758:     case 'skeleton': {
759:       p(ctx, -5, -27, 10, 2, C('#d8d5c8'));
760:       p(ctx, -1, -25, 2, 12, C('#c9c6b8'));
761:       for (let i = 0; i < 3; i++) p(ctx, -5, -24 + i * 3, 10, 1, C('#c9c6b8'));
762:       p(ctx, -6, -14, 3, 10, C('#c9c6b8')); p(ctx, 3, -14, 3, 10, C('#c9c6b8'));
763:       p(ctx, -4, -35, 8, 8, C('#e2dfd2'));
764:       p(ctx, -3, -32, 2, 2, '#3c2f55'); p(ctx, 2, -32, 2, 2, '#3c2f55');
765:       p(ctx, -1, -28, 2, 1, '#3c2f55');
766:       // sword
767:       const ws = Math.round(atk * 4);
768:       p(ctx, 8, -29 - ws, 2, 18, '#c7ccd6');
769:       p(ctx, 6, -13 - ws, 6, 2, '#8a6a45');
770:       // cape
771:       p(ctx, -8, -25, 3, 16, C(dark));
772:       break;
773:     }
774:     case 'hound': {
775:       p(ctx, -12, -12, 24, 8, C(c));
776:       p(ctx, -14, -16, 7, 6, C(dark));
777:       p(ctx, -9, -19, 4, 5, C(dark)); p(ctx, -2, -20, 4, 5, C(dark));
778:       p(ctx, -6, -15, 3, 3, '#ff4d6d'); p(ctx, 2, -15, 3, 3, '#ff4d6d');
779:       p(ctx, -9, -3, 3, 4 + run, C(dark)); p(ctx, 4, -3, 3, 4 - run, C(dark));
780:       p(ctx, -4, -11, 8, 2, C(light));
781:       p(ctx, 10, -18, 4, 2, C(dark)); p(ctx, 13, -14, 2, 6, C(dark));
782:       break;
783:     }
784:     case 'elemental': {
785:       p(ctx, -10, -30, 20, 22, C(c));
786:       p(ctx, -7, -36, 14, 8, C(light));
787:       p(ctx, -4, -32, 3, 3, '#fff'); p(ctx, 2, -33, 3, 3, '#fff');
788:       p(ctx, -12, -25, 4, 10, C(dark)); p(ctx, 8, -25, 4, 10, C(dark));
789:       p(ctx, -8, -8, 5, 7, C(dark)); p(ctx, 3, -8, 5, 7, C(dark));
790:       p(ctx, -5, -22, 2, 8, 'rgba(255,255,255,0.4)');
791:       p(ctx, 2, -28, 2, 12, 'rgba(255,255,255,0.3)');
792:       break;
793:     }
794:     case 'yeti': {
795:       p(ctx, -12, -28, 24, 20, C(c));
796:       p(ctx, -10, -34, 20, 9, C(light));
797:       p(ctx, -6, -31, 4, 4, '#3c2f55'); p(ctx, 2, -31, 4, 4, '#3c2f55');
798:       p(ctx, -8, -24, 16, 3, C(dark));
799:       p(ctx, -14, -24, 5, 13, C(dark)); p(ctx, 9, -24, 5, 13, C(dark));
800:       p(ctx, -9, -9, 7, 9, C(dark)); p(ctx, 2, -9, 7, 9, C(dark));
801:       p(ctx, -4, -26, 8, 2, '#f2e5c8');
802:       break;
803:     }
804:     case 'scarab': {
805:       p(ctx, -9, -14, 18, 10, C(c));
806:       p(ctx, -6, -17, 12, 5, C(light));
807:       p(ctx, -2, -17, 4, 8, C(dark));
808:       for (const sx of [-8, -4, 4, 8]) { p(ctx, sx, -6, 2, 5 + (sx < 0 ? run : -run), C(dark)); }
809:       p(ctx, -7, -20, 2, 3, C(dark)); p(ctx, 5, -20, 2, 3, C(dark));
810:       p(ctx, -3, -12, 6, 3, 'rgba(255,230,150,0.5)');
811:       break;
812:     }
813:     case 'scorpion': {
814:       p(ctx, -11, -12, 22, 8, C(c));
815:       p(ctx, -8, -15, 16, 4, C(light));
816:       p(ctx, -14, -10, 5, 3, C(dark)); p(ctx, 9, -10, 5, 3, C(dark));
817:       for (const sx of [-8, -3, 3, 8]) p(ctx, sx, -5, 2, 5, C(dark));
818:       // tail
819:       p(ctx, 8, -17, 3, 7, C(dark)); p(ctx, 5, -23, 4, 7, C(c)); p(ctx, 0, -26, 6, 4, C(dark));
820:       p(ctx, -1, -28, 3, 3, '#ffd166');
821:       p(ctx, -6, -14, 2, 2, '#ff4d6d');
822:       break;
823:     }
824:     case 'wyrm': {
825:       p(ctx, -15, -14, 20, 9, C(c));
826:       p(ctx, -14, -17, 16, 5, C(light));
827:       p(ctx, 2, -20, 9, 9, C(dark));
828:       p(ctx, 8, -26, 6, 8, C(c));
829:       p(ctx, 12, -28, 5, 4, C(light));
830:       px(ctx, 15, -27, 1, 1, '#ffd166');
831:       p(ctx, -17, -12, 5, 4, C(dark));
832:       p(ctx, -18, -9, 4, 3, C(dark));
833:       // spikes
834:       p(ctx, -9, -20, 2, 4, C(light)); p(ctx, -3, -19, 2, 3, C(light)); p(ctx, 3, -22, 2, 3, C(light));
835:       // wings
836:       p(ctx, -6, -28, 12, 3, C(dark)); p(ctx, -10, -31, 8, 4, C(c)); p(ctx, 5, -31, 7, 4, C(c));
837:       break;
838:     }
839:     case 'demon': {
840:       p(ctx, -6, -26, 12, 14, C(c));
841:       p(ctx, -8, -24, 4, 10, C(dark)); p(ctx, 5, -24, 4, 10, C(dark));
842:       p(ctx, -5, -14, 4, 9, C(dark)); p(ctx, 2, -14, 4, 9, C(dark));
843:       p(ctx, -4, -35, 9, 9, C('#d19a88'));
844:       p(ctx, -6, -38, 2, 4, C(dark)); p(ctx, 4, -38, 2, 4, C(dark));
845:       p(ctx, -3, -32, 2, 2, '#ffd166'); p(ctx, 2, -32, 2, 2, '#ffd166');
846:       // wings
847:       p(ctx, -10, -30, 8, 2, C(shade(c, -0.2)));
848:       p(ctx, -14, -34, 6, 5, C(dark));
849:       p(ctx, 3, -30, 8, 2, C(shade(c, -0.2)));
850:       p(ctx, 9, -34, 6, 5, C(dark));
851:       // weapon
852:       p(ctx, 8, -28, 2, 18, '#c24a35');
853:       p(ctx, 6, -12, 6, 2, '#4a2b2b');
854:       break;
855:     }
856:     case 'knight': {
857:       p(ctx, -7, -27, 14, 14, C(c));
858:       p(ctx, -8, -26, 16, 2, C(light));
859:       p(ctx, -6, -14, 5, 10, C(dark)); p(ctx, 2, -14, 5, 10, C(dark));
860:       p(ctx, -6, -36, 12, 9, C(shade(c, -0.1)));
861:       p(ctx, -4, -33, 8, 2, '#ff5a3c');
862:       p(ctx, -10, -30, 4, 7, C(dark)); p(ctx, 6, -30, 4, 7, C(dark));
