864:       const wa = Math.round(atk * 3);
865:       p(ctx, 10, -33 - wa, 2, 28, '#4a2b2b');
866:       p(ctx, 7, -34 - wa, 8, 6, '#aab2c2');
867:       p(ctx, 7, -30 - wa, 8, 2, '#e8ecf4');
868:       break;
869:     }
870:     case 'sentinel': {
871:       ctx.translate(0, -6);
872:       p(ctx, -8, -22, 16, 16, C(c));
873:       p(ctx, -5, -27, 10, 6, C(light));
874:       p(ctx, -3, -23, 6, 3, '#fff');
875:       p(ctx, -10, -20, 2, 10, C(dark)); p(ctx, 9, -20, 2, 10, C(dark));
876:       p(ctx, -5, -6, 3, 6, C(dark)); p(ctx, 3, -6, 3, 6, C(dark));
877:       p(ctx, -2, -4, 4, 1, C(light));
878:       // floating shards
879:       p(ctx, -13, -26, 3, 3, C(light)); p(ctx, 11, -30, 2, 2, C(light));
880:       break;
881:     }
882:     case 'seraph': {
883:       p(ctx, -5, -26, 10, 14, C('#e8dcc0'));
884:       p(ctx, -5, -14, 4, 9, C('#d8c8a0')); p(ctx, 2, -14, 4, 9, C('#d8c8a0'));
885:       p(ctx, -4, -34, 9, 9, C('#f0c9a4'));
886:       p(ctx, -5, -36, 11, 3, C('#e8dcc0'));
887:       p(ctx, -3, -31, 2, 2, '#ffb23e'); p(ctx, 2, -31, 2, 2, '#ffb23e');
888:       // wings
889:       drawWings(ctx, { style: 'seraph', palette: ['#fffbe8', '#ffe08a', '#ffb23e'] }, time, -26, false);
890:       // halo
891:       p(ctx, -3, -38, 7, 1, '#ffe9a3');
892:       p(ctx, 7, -26, 2, 16, '#d5a44c');
893:       break;
894:     }
895:     default: {
896:       p(ctx, -8, -22, 16, 22, C(c));
897:       p(ctx, -6, -27, 12, 6, C(light));
898:       p(ctx, -4, -24, 2, 2, '#1b141d'); p(ctx, 2, -24, 2, 2, '#1b141d');
899:     }
900:   }
901:   ctx.restore();
902: }
