907: export function drawNpc(ctx, npc, time) {
908:   const c = npc.color || '#d9c07a';
909:   const bob = Math.sin(time * 1.8 + (npc.anim || 0)) * 0.5;
910:   ctx.save();
911:   ctx.translate(0, bob);
912:   const dark = shade(c, -0.22);
913:   const light = shade(c, 0.16);
914:   // robe
915:   p(ctx, -6, -28, 12, 18, c);
916:   p(ctx, -7, -12, 14, 12, dark);
917:   p(ctx, -5, -30, 10, 3, light);
918:   p(ctx, -6, -24, 12, 1, light);
919:   p(ctx, -2, -28, 2, 15, light);
920:   // arms
921:   p(ctx, -8, -27, 3, 11, dark);
922:   p(ctx, 5, -27, 3, 11, dark);
923:   p(ctx, -8, -16, 3, 3, '#e8b98f');
924:   p(ctx, 5, -16, 3, 3, '#e8b98f');
925:   // head
926:   p(ctx, -5, -38, 10, 9, '#e8b98f');
927:   p(ctx, -4, -34, 2, 2, '#2a2133');
928:   p(ctx, 2, -34, 2, 2, '#2a2133');
929:   // hair/hood
930:   p(ctx, -6, -41, 12, 4, '#3a2c2a');
931:   p(ctx, -6, -38, 2, 5, '#3a2c2a');
932:   p(ctx, 4, -38, 2, 5, '#3a2c2a');
