332:     } else if (regionId === 'venomwood' && type === 'ground1' && t.variant % 8 === 0) {
333:       ctx.fillStyle = 'rgba(24,34,18,0.35)';
334:       ctx.fillRect(cx - 6, cy + 1, 9, 1);
335:       ctx.fillStyle = '#8f4fb0';
336:       ctx.fillRect(cx + 4, cy - 2, 1, 1);
337:     } else if (regionId === 'ironcrag' && grassy && t.variant % 9 === 0) {
338:       ctx.fillStyle = '#7d7872';
339:       ctx.fillRect(cx - 3, cy + 3, 3, 2);
340:       ctx.fillStyle = '#96908a';
341:       ctx.fillRect(cx - 2, cy + 3, 1, 1);
342:     }
343: 
344:     if (type !== 'path' && type !== 'plaza' && type !== 'plaza_light' && t.variant % 11 === 0) {
345:       ctx.fillStyle = shade(base, 0.14);
346:       ctx.fillRect(cx - 2, cy - 3, 1, 3);
347:       ctx.fillRect(cx + 2, cy + 1, 1, 2);
348:     }
349:     if (type === 'path' || type === 'plaza') {
350:       // cobble hints
351:       if (t.variant % 4 === 0) {
352:         ctx.fillStyle = shade(base, 0.09);
353:         ctx.fillRect(cx - 5, cy - 2, 5, 1);
354:         ctx.fillRect(cx + 2, cy + 2, 4, 1);
355:         ctx.fillStyle = shade(base, -0.07);
356:         ctx.fillRect(cx - 2, cy + 3, 6, 1);
357:       }
358:       // set cobblestone stones on some tiles
359:       if (t.variant % 3 === 0) {
360:         const stones = 1 + (t.variant % 2);
361:         for (let i = 0; i < stones; i++) {
362:           const sx = 12 + ((t.variant * 7 + i * 31) % 13);
363:           const sy = 4 + ((t.variant * 13 + i * 17) % 9);
364:           ctx.fillStyle = shade(base, 0.13);
365:           ctx.fillRect(cx - sx / 2, cy - 2 + sy * 0.6, sx, 2);
366:           ctx.fillStyle = shade(base, -0.1);
367:           ctx.fillRect(cx - sx / 2, cy + sy * 0.6, sx, 1);
368:         }
369:       }
370:       // path-side pebbles / weeds
371:       if (t.variant % 7 === 0) {
372:         ctx.fillStyle = shade(base, 0.05);
373:         ctx.fillRect(cx + w * 0.55, cy - 1, 2, 1);
374:         ctx.fillStyle = shade(base, -0.12);
375:         ctx.fillRect(cx - w * 0.6, cy + 1, 2, 1);
376:       }
377:     }
378:     if (type === 'plaza_light') {
379:       ctx.fillStyle = shade(base, 0.1);
380:       ctx.fillRect(cx - 14, cy - 2, 28, 1);
381:     }
382:   }
