1237:   roundRect(ctx, x, y, w, h, r) {
1238:     ctx.beginPath();
1239:     ctx.moveTo(x + r, y);
1240:     ctx.arcTo(x + w, y, x + w, y + h, r);
1241:     ctx.arcTo(x + w, y + h, x, y + h, r);
1242:     ctx.arcTo(x, y + h, x, y, r);
1243:     ctx.arcTo(x, y, x + w, y, r);
1244:     ctx.closePath();
