173:       case 'shore': base = shade(pal.ground1, 0.12); break;
174:       case 'water': base = pal.water; break;
175:       case 'void': base = '#05040c'; break;
176:       case 'ground2': base = pal.ground2; break;
177:       case 'ground3': base = pal.ground3; break;
178:       default: base = pal.ground1;
179:     }
180:     const w = TW / 2, h = TH / 2;
181:     const size = world ? world.size : 0;
182:     const nbType = (dx, dy) => {
183:       if (!world) return null;
184:       const nx = tx + dx, ny = ty + dy;
185:       if (nx < 0 || ny < 0 || nx >= size || ny >= size) return null;
186:       return world.tiles[ny * size + nx]?.type || null;
187:     };
188:     const waterAlong = world ? ['water'].some(k => [nbType(1, 0), nbType(-1, 0), nbType(0, 1), nbType(0, -1), nbType(1, 1), nbType(1, -1), nbType(-1, 1), nbType(-1, -1)].includes(k)) : false;
189: 
190:     if (type === 'water') {
191:       const deep = ['water'].includes(nbType(1, 0)) && ['water'].includes(nbType(-1, 0)) && ['water'].includes(nbType(0, 1)) && ['water'].includes(nbType(0, -1))
192:         && ['water'].includes(nbType(1, 1)) && ['water'].includes(nbType(-1, -1)) && ['water'].includes(nbType(1, -1)) && ['water'].includes(nbType(-1, 1));
193:       base = deep ? shade(pal.water, -0.16) : shade(pal.water, 0.02);
194:       const v = (t.variant % 9) - 4;
195:       base = shade(base, v * 0.005);
196:       ctx.beginPath();
197:       ctx.moveTo(cx, cy - h); ctx.lineTo(cx + w, cy); ctx.lineTo(cx, cy + h); ctx.lineTo(cx - w, cy);
198:       ctx.closePath();
199:       ctx.fillStyle = base;
200:       ctx.fill();
201:       // depth shading toward the centre of lakes
202:       if (deep) {
203:         ctx.fillStyle = 'rgba(4,12,26,0.18)';
204:         ctx.beginPath();
205:         ctx.ellipse(cx, cy, w * 0.42, h * 0.42, 0, 0, Math.PI * 2);
206:         ctx.fill();
207:         ctx.fillStyle = 'rgba(255,255,255,0.05)';
208:         ctx.fillRect(cx - 12, cy - 2, 9, 1);
209:         ctx.fillRect(cx + 3, cy + 3, 6, 1);
210:       } else {
211:         // shallow sandy bottom showing through + foam flecks
212:         ctx.fillStyle = shade(pal.water, 0.14);
213:         ctx.fillRect(cx - 8, cy - 1, 14, 1);
214:         ctx.fillStyle = 'rgba(255,255,255,0.2)';
215:         ctx.fillRect(cx - 11, cy - 4, 6, 1);
216:         ctx.fillRect(cx + 5, cy + 1, 4, 1);
217:         ctx.fillRect(cx - 2, cy - 7, 3, 1);
218:       }
219:       return;
220:     }
221:     if (type === 'void') {
222:       ctx.beginPath();
223:       ctx.moveTo(cx, cy - h); ctx.lineTo(cx + w, cy); ctx.lineTo(cx, cy + h); ctx.lineTo(cx - w, cy);
224:       ctx.closePath();
225:       ctx.fillStyle = '#05040c';
226:       ctx.fill();
227:       const rngV = (t.variant * 9301 + 49297) % 233280;
228:       for (let i = 0; i < 4; i++) {
229:         const rx = ((rngV * (i + 5) + 311) % 100) / 100;
230:         const ry = ((rngV * (i + 11) + 733) % 100) / 100;
231:         const dx = (rx - 0.5) * w * 0.9, dy = (ry - 0.5) * h * 0.9;
232:         if (Math.abs(dx) / w + Math.abs(dy) / h > 0.8) continue;
233:         ctx.fillStyle = i === 0 ? 'rgba(180,160,255,0.55)' : 'rgba(140,120,220,0.28)';
234:         ctx.fillRect(cx + dx, cy + dy, 1, 1);
235:       }
236:       if ((t.variant + tx + ty) % 23 === 0) {
237:         ctx.fillStyle = 'rgba(169,155,255,0.16)';
238:         ctx.beginPath(); ctx.ellipse(cx, cy, 9, 4, 0, 0, Math.PI * 2); ctx.fill();
239:       }
240:       return;
241:     }
242: 
243:     // land diamond + soft water-edge halo
244:     const v = (t.variant % 9) - 4;
245:     base = shade(base, v * 0.006);
246:     ctx.beginPath();
247:     ctx.moveTo(cx, cy - h); ctx.lineTo(cx + w, cy); ctx.lineTo(cx, cy + h); ctx.lineTo(cx - w, cy);
248:     ctx.closePath();
249:     ctx.fillStyle = base;
250:     ctx.fill();
251:     if (waterAlong && type === 'shore') {
252:       ctx.fillStyle = 'rgba(240,236,210,0.28)';
253:       ctx.fillRect(cx - 4, cy - 2, 8, 1);
254:     }
255: 
256:     // texture specks inside the diamond
257:     const rngV = (t.variant * 9301 + 49297) % 233280;
258:     const dots = 4 + (t.variant % 5);
259:     for (let i = 0; i < dots; i++) {
260:       const rx = ((rngV * (i + 3) + 137) % 100) / 100;
261:       const ry = ((rngV * (i + 7) + 911) % 100) / 100;
262:       const dx = (rx - 0.5) * w * 1.15;
263:       const dy = (ry - 0.5) * h * 0.95;
264:       if (Math.abs(dx) / w + Math.abs(dy) / h > 0.85) continue;
265:       const light = (t.variant + i) % 3 !== 0;
266:       ctx.fillStyle = light ? shade(base, 0.09) : shade(base, -0.08);
267:       ctx.fillRect(cx + dx, cy + dy, 2, 1);
268:     }
269: 
270:     const regionId = world ? world.regionId : '';
271:     const grassy = type === 'ground1' || type === 'ground2' || type === 'ground3' || type === 'shore';
272: 
273:     if (grassy && type !== 'path' && type !== 'plaza' && type !== 'plaza_light') {
274:       // grass tufts: paired light/dark blades
275:       const tufts = type === 'ground1' ? 2 : 1;
276:       for (let i = 0; i < tufts; i++) {
277:         const rx = ((rngV * (i + 17) + 551) % 100) / 100;
278:         const ry = ((rngV * (i + 29) + 197) % 100) / 100;
279:         const dx = (rx - 0.5) * w * 0.9;
280:         const dy = (ry - 0.5) * h * 0.7;
281:         if (Math.abs(dx) / w + Math.abs(dy) / h > 0.7) continue;
282:         ctx.fillStyle = shade(base, 0.17);
283:         ctx.fillRect(cx + dx, cy + dy - 2, 1, 3);
284:         ctx.fillRect(cx + dx + 2, cy + dy - 1, 1, 2);
285:         ctx.fillStyle = shade(base, -0.13);
286:         ctx.fillRect(cx + dx - 2, cy + dy, 1, 2);
287:       }
288:       // wildflower accents (region palette driven)
289:       if (type === 'ground1' && t.variant % 13 === 0) {
290:         const flowerColors = {
291:           greendale: ['#ffd166', '#ff8fa3'], ironcrag: ['#ffb23e'], venomwood: ['#b06bff', '#9b6bff'],
292:           mistgrave: ['#c9d8e8'], frostpeak: ['#bfefff'], sunscorch: ['#ffd166', '#ff9a4a'],
293:           ashen: ['#ff7a3c'], tower: ['#a99bff']
294:         };
295:         const cols = flowerColors[regionId] || ['#ffd166'];
296:         const rx = ((rngV * 41 + 97) % 100) / 100;
297:         const ry = ((rngV * 53 + 41) % 100) / 100;
298:         const dx = (rx - 0.5) * w * 0.7, dy = (ry - 0.5) * h * 0.55;
299:         if (Math.abs(dx) / w + Math.abs(dy) / h < 0.62) {
300:           ctx.fillStyle = '#3f6a38';
301:           ctx.fillRect(cx + dx, cy + dy, 1, 2);
302:           ctx.fillStyle = cols[(t.variant + tx) % cols.length];
303:           ctx.fillRect(cx + dx - 1, cy + dy - 1, 2, 2);
304:         }
305:       }
306:     }
307: 
308:     // region ground accents
309:     if (regionId === 'frostpeak' && grassy && t.variant % 5 === 0) {
310:       ctx.fillStyle = 'rgba(238,246,250,0.5)';
311:       ctx.fillRect(cx - 6 + (t.variant % 7), cy - 2, 6, 1);
312:       ctx.fillRect(cx + 2 + (v % 3), cy + 2, 4, 1);
313:     } else if (regionId === 'sunscorch' && grassy && t.variant % 4 === 0) {
314:       ctx.fillStyle = shade(base, 0.12);
315:       ctx.fillRect(cx - 7, cy + 1, 10, 1);
316:       ctx.fillRect(cx - 3, cy - 3, 8, 1);
317:     } else if (regionId === 'ashen' && grassy && t.variant % 6 === 0) {
318:       ctx.fillStyle = 'rgba(20,12,12,0.3)';
319:       ctx.fillRect(cx - 8, cy, 5, 1);
320:       ctx.fillRect(cx - 2, cy + 2, 7, 1);
321:       if (t.variant % 12 === 0) {
322:         ctx.fillStyle = '#ff7a3c';
323:         ctx.fillRect(cx + 6, cy - 1, 1, 1);
324:       }
325:     } else if (regionId === 'tower' && grassy && t.variant % 7 === 0) {
326:       ctx.fillStyle = 'rgba(169,155,255,0.22)';
327:       ctx.fillRect(cx - 1, cy + 5, 4, 1);
328:       ctx.fillRect(cx + 3, cy + 3, 2, 1);
329:     } else if (regionId === 'mistgrave' && grassy && t.variant % 6 === 0) {
330:       ctx.fillStyle = 'rgba(190,205,220,0.12)';
331:       ctx.beginPath(); ctx.ellipse(cx + (v % 5), cy - 3, 7, 3, 0, 0, Math.PI * 2); ctx.fill();
332:     } else if (regionId === 'venomwood' && type === 'ground1' && t.variant % 8 === 0) {
333:       ctx.fillStyle = 'rgba(24,34,18,0.35)';
334:       ctx.fillRect(cx - 6, cy + 1, 9, 1);
335:       ctx.fillStyle = '#8f4fb0';
336:       ctx.fillRect(cx + 4, cy - 2, 1, 1);
337:     } else if (regionId === 'ironcrag' && grassy && t.variant % 9 === 0) {
338:       ctx.fillStyle = '#7d7872';
339:       ctx.fillRect(cx - 3, cy + 3, 3, 2);
340:       ctx.fillStyle = '#96908a';
341:       ctx.fillRect(cx - 2, cy + 3, 1, 1);
342:     }
343: 
344:     if (type !== 'path' && type !== 'plaza' && type !== 'plaza_light' && t.variant % 11 === 0) {
345:       ctx.fillStyle = shade(base, 0.14);
346:       ctx.fillRect(cx - 2, cy - 3, 1, 3);
347:       ctx.fillRect(cx + 2, cy + 1, 1, 2);
348:     }
349:     if (type === 'path' || type === 'plaza') {
350:       // cobble hints
351:       if (t.variant % 4 === 0) {
352:         ctx.fillStyle = shade(base, 0.09);
353:         ctx.fillRect(cx - 5, cy - 2, 5, 1);
354:         ctx.fillRect(cx + 2, cy + 2, 4, 1);
355:         ctx.fillStyle = shade(base, -0.07);
356:         ctx.fillRect(cx - 2, cy + 3, 6, 1);
357:       }
358:       // set cobblestone stones on some tiles
359:       if (t.variant % 3 === 0) {
360:         const stones = 1 + (t.variant % 2);
361:         for (let i = 0; i < stones; i++) {
362:           const sx = 12 + ((t.variant * 7 + i * 31) % 13);
363:           const sy = 4 + ((t.variant * 13 + i * 17) % 9);
364:           ctx.fillStyle = shade(base, 0.13);
365:           ctx.fillRect(cx - sx / 2, cy - 2 + sy * 0.6, sx, 2);
366:           ctx.fillStyle = shade(base, -0.1);
367:           ctx.fillRect(cx - sx / 2, cy + sy * 0.6, sx, 1);
368:         }
369:       }
370:       // path-side pebbles / weeds
371:       if (t.variant % 7 === 0) {
372:         ctx.fillStyle = shade(base, 0.05);
373:         ctx.fillRect(cx + w * 0.55, cy - 1, 2, 1);
374:         ctx.fillStyle = shade(base, -0.12);
375:         ctx.fillRect(cx - w * 0.6, cy + 1, 2, 1);
376:       }
377:     }
378:     if (type === 'plaza_light') {
379:       ctx.fillStyle = shade(base, 0.1);
380:       ctx.fillRect(cx - 14, cy - 2, 28, 1);
381:     }
382:   }
