384:   // ------------------------------------------------------------
385:   // WEATHER
386:   // ------------------------------------------------------------
387:   makeWeather(kind) {
388:     const n = WEATHER_COUNT[kind] || 24;
389:     this.particles = [];
390:     for (let i = 0; i < n; i++) {
391:       this.particles.push({
392:         x: Math.random() * this.width,
393:         y: Math.random() * this.height,
394:         vx: (Math.random() - 0.5) * 12,
395:         vy: 8 + Math.random() * 26,
396:         size: 1 + Math.random() * 2,
397:         phase: Math.random() * Math.PI * 2,
398:         speed: 0.4 + Math.random() * 1.6,
399:         alpha: 0.25 + Math.random() * 0.5
400:       });
401:     }
402:     this.weatherKind = kind;
403:   }
404: 
405:   updateWeather(dt) {
406:     const kind = this.weatherKind;
407:     for (const p of this.particles) {
408:       p.phase += dt * p.speed;
409:       if (kind === 'embers') {
410:         p.y -= (14 + p.speed * 22) * dt;
411:         p.x += Math.sin(p.phase * 2) * 14 * dt;
412:       } else if (kind === 'snow') {
413:         p.y += p.vy * dt;
414:         p.x += Math.sin(p.phase) * 16 * dt;
415:       } else if (kind === 'sand') {
416:         p.x += (40 + p.speed * 45) * dt;
417:         p.y += Math.sin(p.phase) * 8 * dt;
418:       } else if (kind === 'stars') {
419:         // static twinkle
420:       } else if (kind === 'mist') {
421:         p.x += (4 + p.speed * 4) * dt;
422:         p.y += Math.sin(p.phase) * 2 * dt;
423:       } else {
424:         p.y += p.vy * dt * 0.7;
425:         p.x += Math.sin(p.phase * 1.4) * 20 * dt;
426:       }
427:       if (p.y > this.height + 20) { p.y = -20; p.x = Math.random() * this.width; }
428:       if (p.y < -30) { p.y = this.height + 10; p.x = Math.random() * this.width; }
429:       if (p.x > this.width + 20) p.x = -20;
430:       if (p.x < -20) p.x = this.width + 20;
431:     }
432:   }
433: 
434:   drawWeather(ctx) {
435:     const kind = this.weatherKind;
436:     const pal = this.world.region.palette;
437:     ctx.save();
438:     if (kind === 'leaves') {
439:       for (const p of this.particles) {
440:         ctx.globalAlpha = p.alpha;
441:         ctx.fillStyle = Math.sin(p.phase) > 0 ? pal.accent : '#d5a44c';
442:         ctx.fillRect(p.x, p.y, p.size + 1, p.size);
443:       }
444:     } else if (kind === 'embers') {
445:       for (const p of this.particles) {
446:         ctx.globalAlpha = p.alpha * (0.7 + Math.sin(p.phase * 2) * 0.3);
447:         ctx.fillStyle = Math.sin(p.phase) > 0 ? '#ffb23e' : '#ff5a3c';
448:         ctx.fillRect(p.x, p.y, p.size, p.size);
449:       }
450:     } else if (kind === 'spores') {
451:       for (const p of this.particles) {
452:         ctx.globalAlpha = p.alpha * (0.5 + Math.sin(p.phase) * 0.5);
453:         ctx.fillStyle = '#c9a0ff';
454:         ctx.fillRect(p.x, p.y, p.size, p.size);
455:         ctx.globalAlpha *= 0.4;
456:         ctx.fillRect(p.x - 1, p.y - 1, p.size + 2, p.size + 2);
457:       }
458:     } else if (kind === 'snow') {
459:       for (const p of this.particles) {
460:         ctx.globalAlpha = p.alpha;
461:         ctx.fillStyle = '#f2fbff';
462:         ctx.fillRect(p.x, p.y, p.size, p.size);
463:       }
464:     } else if (kind === 'sand') {
465:       for (const p of this.particles) {
466:         ctx.globalAlpha = p.alpha * 0.6;
467:         ctx.fillStyle = '#f0d79a';
468:         ctx.fillRect(p.x, p.y, p.size + 2, 1);
469:       }
470:     } else if (kind === 'stars') {
471:       for (const p of this.particles) {
472:         ctx.globalAlpha = 0.25 + Math.abs(Math.sin(p.phase)) * 0.6;
473:         ctx.fillStyle = Math.sin(p.phase * 2) > 0 ? '#fff4c4' : '#c9b4ff';
474:         ctx.fillRect(p.x, p.y, p.size, p.size);
475:       }
476:     } else if (kind === 'mist') {
477:       for (const p of this.particles) {
478:         ctx.globalAlpha = 0.05 + p.alpha * 0.05;
479:         ctx.fillStyle = '#b7d4ea';
480:         ctx.beginPath();
481:         ctx.ellipse(p.x, p.y, 90 + p.size * 25, 22 + p.size * 5, 0, 0, Math.PI * 2);
482:         ctx.fill();
483:       }
484:     }
485:     ctx.restore();
486:   }
487: 
488:   // ------------------------------------------------------------
489:   // MAIN RENDER
490:   // ------------------------------------------------------------
491:   render(game, dt) {
492:     const ctx = this.ctx;
493:     this.time += dt;
494:     this.updateWeather(dt);
495:     this.updateDust(dt);
496:     const world = this.world;
497:     if (!world || !game.player) return;
498:     const z = this.viewZoom;
499:     const vw = this.viewW(), vh = this.viewH();
500: 
501:     // camera follow (still smoothly centered on the player)
502:     const p = this.iso(game.player.x, game.player.y);
503:     this.camTarget.x = lerp(this.camTarget.x, p.x - vw / 2, 0.18);
504:     this.camTarget.y = lerp(this.camTarget.y, p.y - vh / 2 - 34, 0.18);
505:     this.clampCamera(this.camTarget);
506:     this.cam.x = lerp(this.cam.x, this.camTarget.x, 0.22);
507:     this.cam.y = lerp(this.cam.y, this.camTarget.y, 0.22);
508:     if (Math.abs(this.cam.x - this.camTarget.x) < 0.05) this.cam.x = this.camTarget.x;
509:     if (Math.abs(this.cam.y - this.camTarget.y) < 0.05) this.cam.y = this.camTarget.y;
510: 
511:     // ---- sky backdrop (screen space) ----
512:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
513:     ctx.imageSmoothingEnabled = false;
514:     const pal = world.region.palette;
515:     const bg = ctx.createLinearGradient(0, 0, 0, this.height);
516:     bg.addColorStop(0, pal.sky);
517:     bg.addColorStop(1, shade(pal.sky, -0.12));
518:     ctx.fillStyle = bg;
519:     ctx.fillRect(0, 0, this.width, this.height);
520: 
521:     // ---- world (zoomed slightly out to show more of the surrounding land) ----
522:     ctx.setTransform(this.dpr * z, 0, 0, this.dpr * z, 0, 0);
523:     // ground is the only pre-rendered bitmap — smooth its downscale so the pixel art stays clean
524:     ctx.imageSmoothingEnabled = true;
525:     if ('imageSmoothingQuality' in ctx) ctx.imageSmoothingQuality = 'high';
526:     ctx.drawImage(this.ground, -Math.round(this.cam.x), -Math.round(this.cam.y));
527:     ctx.imageSmoothingEnabled = false;
528: 
529:     this.drawWaterFX(ctx);
530: 
531:     // lights beneath objects
532:     this.drawGroundLights(ctx, world);
533: 
534:     // player running dust behind entities
535:     this.spawnDust(game);
536:     this.drawDust(ctx);
537: 
538:     // collect drawables
539:     const drawables = [];
540:     const margin = 260;
541:     const visible = (sx, sy) => sx > -margin && sx < vw + margin && sy > -margin - 100 && sy < vh + margin;
542: 
543:     for (const prop of world.props) {
544:       const s = this.worldToView(prop.x, prop.y);
545:       if (visible(s.x, s.y - 80)) drawables.push({ z: prop.x + prop.y, read: () => this.drawPropSprite(ctx, prop, s) });
546:     }
547:     for (const node of world.nodes) {
548:       if (node.respawnAt > Date.now()) continue;
549:       const s = this.worldToView(node.x, node.y);
550:       if (visible(s.x, s.y)) drawables.push({ z: node.x + node.y, read: () => this.drawNodeSprite(ctx, node, s) });
551:     }
552:     for (const h of world.hidden) {
553:       if (h.opened) continue;
554:       const s = this.worldToView(h.x, h.y);
555:       if (visible(s.x, s.y)) drawables.push({ z: h.x + h.y, read: () => this.drawChestSprite(ctx, h, s) });
556:     }
557:     for (const npc of world.npcs) {
558:       const s = this.worldToView(npc.x, npc.y);
559:       if (visible(s.x, s.y)) drawables.push({ z: npc.x + npc.y, read: () => this.drawNpcSprite(ctx, npc, s, game) });
560:     }
561:     for (const enemy of world.enemies) {
562:       if (!enemy.alive) continue;
563:       const s = this.worldToView(enemy.x, enemy.y);
564:       if (visible(s.x, s.y)) drawables.push({ z: enemy.x + enemy.y + 0.01, read: () => this.drawEnemySprite(ctx, enemy, s, game) });
565:     }
566:     if (game.groundLoot) {
567:       for (const loot of game.groundLoot) {
568:         const s = this.worldToView(loot.x, loot.y);
569:         if (visible(s.x, s.y)) drawables.push({ z: loot.x + loot.y + 0.005, read: () => this.drawLootSprite(ctx, loot, s) });
570:       }
571:     }
572:     // player
573:     const ps = this.worldToView(game.player.x, game.player.y);
574:     drawables.push({ z: game.player.x + game.player.y + 0.02, read: () => this.drawPlayerSprite(ctx, game, ps) });
575: 
576:     drawables.sort((a, b) => a.z - b.z);
577:     for (const d of drawables) d.read();
578: 
579:     // target ring under current target
580:     if (game.target && game.target.alive) this.drawTargetRing(ctx, game.target);
581:     if (game.interactTarget) this.drawInteractRing(ctx, game.interactTarget);
582: 
583:     // pets (drawn above world)
584:     if (game.state.char.petActive && game.state.petDef()) {
585:       const off = this.iso(game.player.x, game.player.y);
586:       ctx.save();
587:       const S = this.spriteScale();
588:       ctx.translate(ps.x + 28, ps.y - 20);
589:       ctx.scale(S * 0.8, S * 0.8);
590:       drawPet(ctx, game.state.petDef(), this.time);
591:       ctx.restore();
592:     }
593: 
594:     // skill / combat effects and projectiles
595:     this.drawEffects(ctx, game);
596: 
597:     // ---- screen-space atmosphere ----
598:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
599: 
600:     // soft light shafts over the forests
601:     if (['greendale', 'venomwood', 'ironcrag'].includes(world.regionId)) this.drawSunShafts(ctx);
602: 
603:     // weather
604:     this.drawWeather(ctx);
605: 
606:     // ambient fog / region tint
607:     ctx.save();
608:     const fog = ctx.createRadialGradient(this.width / 2, this.height / 2, Math.min(this.width, this.height) * 0.2, this.width / 2, this.height / 2, Math.max(this.width, this.height) * 0.76);
609:     fog.addColorStop(0, pal.fog);
610:     fog.addColorStop(1, 'rgba(5,4,10,0.46)');
611:     ctx.fillStyle = fog;
612:     ctx.fillRect(0, 0, this.width, this.height);
613:     ctx.restore();
614: 
615:     if (world.mode === 'dungeon') {
616:       ctx.fillStyle = 'rgba(8,4,14,0.16)';
617:       ctx.fillRect(0, 0, this.width, this.height);
618:     }
619: 
620:     // minimap occasionally
621:     const now = performance.now();
622:     if (this.minimapCanvas && now - this.lastMinimap > 220) {
623:       this.lastMinimap = now;
624:       this.drawMinimap(this.minimapCanvas, game);
625:     }
626:   }
