485:   toast({ msg, type = 'info', duration = 3000, small = false, color }) {
486:     if (!msg) return;
487:     // suppress duplicate consecutive toasts
488:     const last = this.el.toastHost.lastElementChild;
489:     if (last && last.dataset.msg === msg) return;
490:     const div = document.createElement('div');
491:     div.className = `toast ${type}${small ? ' small' : ''}`;
492:     div.dataset.msg = msg;
493:     div.textContent = msg;
494:     if (color) div.style.borderColor = color;
495:     this.el.toastHost.appendChild(div);
496:     while (this.el.toastHost.children.length > 5) this.el.toastHost.firstElementChild.remove();
497:     if (type === 'combat' || type === 'loot' || type === 'danger') this.addFeed(msg, type);
498:     setTimeout(() => {
499:       div.classList.add('out');
500:       setTimeout(() => div.remove(), 260);
501:     }, duration);
502:   }
