629:     if (!item || item.kind !== 'equip') return '';
630:     return `${CLASSES[item.classId].name} · ${FACTIONS[item.faction].name}`;
631:   }
632:   statName(k) {
633:     return { str: 'Strength', int: 'Intelligence', dex: 'Dexterity', vit: 'Vitality', atk: 'Attack', def: 'Defense', crit: 'Crit' }[k] || k;
