938: // ------------------------------------------------------------
939: export function drawProp(ctx, prop, time, biome = {}) {
940:   const v = prop.variant || 0;
941:   const s = prop.scale || 1;
942:   const flick = Math.sin(time * 4 + v) * 0.5 + 0.5;
943:   const type = prop.kind || prop.type;
944:   ctx.save();
945:   if (prop.flip) ctx.scale(-1, 1);
946:   ctx.scale(s, s);
947:   switch (type) {
948:     case 'tree': {
949:       const leaf = biome.leaf || '#4f8a4b';
950:       const leaf2 = shade(leaf, 0.14);
951:       const leaf3 = shade(leaf, -0.2);
952:       const leaf4 = shade(leaf, 0.24);
953:       const sway = Math.sin(time * 1.4 + v * 0.7) * 0.7;
954:       const sway2 = Math.sin(time * 1.4 + v * 0.7 + 0.9) * 0.9;
955:       // trunk with moss and root flare
956:       p(ctx, -3, -18, 6, 18, '#6a4a2f');
957:       p(ctx, -3, -18, 2, 18, '#7d5836');
958:       p(ctx, -5, -14, 3, 3, '#5a8a3e');           // moss clump
959:       p(ctx, 2, -8, 2, 2, shade('#5a8a3e', -0.1));
960:       p(ctx, -5, -14, 4, 2, '#5a3f27');
961:       p(ctx, -2, -1, 10, 2, '#5a3f27');           // root flare
962:       // crown layers (sway with the wind)
963:       p(ctx, -18 + sway, -26, 9, 8, leaf3);
964:       p(ctx, 9 + sway, -28, 7, 7, leaf);
965:       p(ctx, -12 + sway, -30, 24, 14, leaf3);
966:       p(ctx, -10 + sway, -38, 20, 12, leaf);
967:       p(ctx, -7 + sway2, -44, 14, 9, leaf2);
968:       p(ctx, -3 + sway2, -47, 8, 5, shade(leaf, 0.3));
969:       p(ctx, 4 + sway, -36, 5, 3, leaf2);
970:       p(ctx, 12 + sway, -33, 5, 4, shade(leaf, 0.2));
971:       // sunlit edge + shadowed underside
972:       p(ctx, -12 + sway, -30, 24, 2, leaf4);
973:       p(ctx, -12 + sway, -18, 20, 2, 'rgba(0,0,10,0.18)');
974:       p(ctx, -8 + sway, -41, 4, 2, 'rgba(255,255,255,0.14)');
975:       p(ctx, 2 + sway2, -45, 3, 2, 'rgba(255,255,255,0.2)');
976:       break;
977:     }
978:     case 'pine': case 'pine_snow': {
979:       const snow = type === 'pine_snow';
980:       const leaf = snow ? '#2f5946' : (biome.pine || '#356044');
981:       const leaf2 = shade(leaf, 0.16);
982:       const leaf3 = shade(leaf, -0.16);
983:       const sway = Math.sin(time * 1.1 + v) * 0.6;
984:       p(ctx, -2, -12, 4, 12, '#4a3324');
985:       p(ctx, -2, -12, 1, 12, '#5d4430');
986:       p(ctx, -5, -2, 3, 2, '#4a3324');           // root
987:       p(ctx, 3, -2, 3, 2, '#4a3324');
988:       p(ctx, -9 + sway, -22, 18, 11, leaf3);
989:       p(ctx, -9 + sway, -22, 18, 3, leaf);
990:       p(ctx, -7 + sway, -31, 14, 11, leaf);
991:       p(ctx, -7 + sway, -31, 14, 2, leaf2);
992:       p(ctx, -5 + sway, -39, 10, 10, leaf);
993:       p(ctx, -2 + sway, -44, 4, 7, leaf);
994:       if (snow) {
995:         p(ctx, -9 + sway, -22, 18, 2, '#eef6fa');
996:         p(ctx, -7 + sway, -31, 14, 2, '#eef6fa');
997:         p(ctx, -5 + sway, -39, 10, 2, '#eef6fa');
998:         p(ctx, -2 + sway, -44, 4, 2, '#fff');
999:         p(ctx, -11 + sway, -18, 4, 2, '#d7e6ef');
1000:         p(ctx, 5 + sway, -16, 3, 2, '#d7e6ef');
1001:       } else {
1002:         p(ctx, -4 + sway, -28, 9, 2, shade(leaf, 0.24));
1003:         p(ctx, 2 + sway, -20, 6, 2, shade(leaf, 0.1));
1004:       }
1005:       break;
1006:     }
1007:     case 'dead_tree': {
1008:       p(ctx, -2, -26, 5, 26, '#4a3a34');
1009:       p(ctx, -2, -26, 2, 26, '#5d4a44');
1010:       p(ctx, -10, -30, 9, 3, '#4a3a34');
1011:       p(ctx, -12, -36, 3, 7, '#4a3a34');
1012:       p(ctx, 5, -26, 8, 3, '#4a3a34');
1013:       p(ctx, 10, -33, 3, 8, '#4a3a34');
1014:       p(ctx, 10, -39, 4, 6, '#4a3a34');
1015:       p(ctx, -6, -20, 7, 2, '#3a2c2a');
1016:       p(ctx, -1, -30, 6, 2, '#3a2c2a');
1017:       if (v % 3 === 0) {
1018:         p(ctx, -6, -18, 3, 2, '#4e4048');       // woodpecker hole
1019:         p(ctx, -5, -17, 1, 1, '#241c20');
1020:       }
1021:       break;
1022:     }
1023:     case 'bush': {
1024:       const c = biome.bush || '#3f7a44';
1025:       const d = shade(c, -0.18), l = shade(c, 0.2);
1026:       p(ctx, -7, -6, 14, 6, d);
1027:       p(ctx, -6, -9, 12, 5, c);
1028:       p(ctx, -4, -11, 5, 3, l);
1029:       p(ctx, 3, -8, 3, 3, l);
1030:       p(ctx, -6, -4, 4, 2, shade(c, -0.26));
1031:       p(ctx, 6, -7, 2, 2, shade(c, -0.26));
1032:       if (v % 3 === 0) {
1033:         px(ctx, -3, -10, '#ff5a6b');
1034:         px(ctx, 1, -9, '#ff5a6b');
1035:         px(ctx, -2, -8, '#ffd166');
1036:       } else if (v % 3 === 1) {
1037:         px(ctx, 0, -11, '#e8f0ff');
1038:         px(ctx, -4, -9, '#e8f0ff');
1039:       }
1040:       break;
1041:     }
1042:     case 'flowers': {
1043:       const cols = ['#ffd166', '#ff8fa3', '#a99bff', '#8fe2ff', '#f7f4ea'];
1044:       for (let i = 0; i < 7; i++) {
1045:         const fx = -6 + (i * 4) % 13;
1046:         const fy = -4 + ((i * 5) % 5);
1047:         p(ctx, fx, fy, 1, 4, i % 2 ? '#4f7a43' : '#5d8a4d');
1048:         px(ctx, fx, fy - 1, cols[(v + i) % cols.length]);
1049:         if (i % 3 === 0) px(ctx, fx - 1, fy - 1, cols[(v + i + 2) % cols.length]);
1050:       }
1051:       break;
1052:     }
1053:     case 'stump': {
1054:       p(ctx, -5, -6, 10, 6, '#5a3f27');
