24:     this.width = 0;
25:     this.height = 0;
26:     this.time = 0;
27:     this.viewZoom = 1;
28:     this.setZoom();
29:     this.particles = [];
30:     this.dust = [];
31:     this.waterTiles = [];
32:     this.minimapCanvas = null;
33:     this.lastMinimap = 0;
34:     this.snapped = false;
35:     this.resize();
36:   }
37: 
38:   setMinimap(canvas) { this.minimapCanvas = canvas; }
39: 
40:   setZoom() {
41:     const short = Math.min(this.width || window.innerWidth, this.height || window.innerHeight);
42:     // zoomed slightly further out: mobile keeps a comfortable 0.9, desktop shows more world at 0.8
43:     this.viewZoom = short < 620 ? 0.9 : 0.8;
44:   }
45: 
46:   viewW() { return this.width / this.viewZoom; }
47:   viewH() { return this.height / this.viewZoom; }
48: 
49:   resize() {
50:     const rect = this.canvas.getBoundingClientRect();
51:     this.dpr = Math.min(window.devicePixelRatio || 1, 2);
52:     this.width = Math.max(320, rect.width || window.innerWidth);
53:     this.height = Math.max(320, rect.height || window.innerHeight);
54:     this.canvas.width = Math.floor(this.width * this.dpr);
55:     this.canvas.height = Math.floor(this.height * this.dpr);
56:     this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
57:     this.ctx.imageSmoothingEnabled = false;
58:     this.setZoom();
59:     if (this.world) this.snapCamera(true);
60:   }
61: 
62:   setWorld(world, opts = {}) {
63:     this.world = world;
64:     const size = world.size;
65:     this.offsetX = (size - 1) * TW / 2 + 96;
66:     this.offsetY = 96;
67:     this.groundW = size * TW + 192;
68:     this.groundH = size * TH + 192;
69:     this.ground = this.buildGround(world);
70:     this.waterTiles = [];
71:     for (const t of world.tiles) if (t.type === 'water') this.waterTiles.push(t);
72:     this.makeWeather(world.region.weather);
73:     this.snapped = false;
74:     if (opts.snap !== false) this.snapCamera(true);
75:     this.worldRef = world;
76:   }
77: 
78:   iso(x, y) {
79:     return {
80:       x: this.offsetX + (x - y) * TW / 2,
81:       y: this.offsetY + (x + y) * TH / 2
82:     };
83:   }
84: 
85:   worldToView(x, y) {
86:     const p = this.iso(x, y);
87:     return { x: p.x - this.cam.x, y: p.y - this.cam.y };
88:   }
89: 
90:   // For input mapping: returns CSS pixel coordinates (zoom-adjusted)
91:   worldToScreen(x, y) {
92:     const p = this.iso(x, y);
93:     return { x: (p.x - this.cam.x) * this.viewZoom, y: (p.y - this.cam.y) * this.viewZoom };
94:   }
95: 
96:   screenToWorld(sx, sy) {
97:     const z = this.viewZoom;
98:     const ix = sx / z + this.cam.x - this.offsetX;
99:     const iy = sy / z + this.cam.y - this.offsetY;
100:     const a = ix / (TW / 2);
101:     const b = iy / (TH / 2);
102:     return { x: (a + b) / 2, y: (b - a) / 2 };
103:   }
104: 
105:   snapCamera(instant = false) {
106:     const g = this.game;
107:     if (!g || !g.player) return;
108:     const p = this.iso(g.player.x, g.player.y);
109:     this.camTarget.x = p.x - this.viewW() / 2;
110:     this.camTarget.y = p.y - this.viewH() / 2 - 30;
111:     this.clampCamera(this.camTarget);
112:     if (instant || !this.snapped) {
113:       this.cam.x = this.camTarget.x;
114:       this.cam.y = this.camTarget.y;
115:       this.snapped = true;
116:     }
117:   }
118: 
119:   clampCamera(c) {
120:     const vw = this.viewW(), vh = this.viewH();
121:     const maxX = Math.max(0, this.groundW - vw);
122:     const maxY = Math.max(0, this.groundH - vh);
123:     if (this.groundW < vw) c.x = (this.groundW - vw) / 2;
124:     else c.x = clamp(c.x, 0, maxX);
125:     if (this.groundH < vh) c.y = (this.groundH - vh) / 2;
126:     else c.y = clamp(c.y, 0, maxY);
127:   }
128: 
129:   // ------------------------------------------------------------
130:   // GROUND PRE-RENDER
131:   // ------------------------------------------------------------
132:   buildGround(world) {
133:     const c = document.createElement('canvas');
134:     c.width = this.groundW;
135:     c.height = this.groundH;
136:     const ctx = c.getContext('2d');
137:     ctx.imageSmoothingEnabled = false;
138:     const pal = world.region.palette;
139: 
140:     const g = ctx.createLinearGradient(0, 0, 0, this.groundH);
141:     g.addColorStop(0, shade(pal.sky, 0.04));
142:     g.addColorStop(1, shade(pal.sky, -0.1));
143:     ctx.fillStyle = g;
144:     ctx.fillRect(0, 0, c.width, c.height);
145: 
146:     for (let y = 0; y < world.size; y++) {
147:       for (let x = 0; x < world.size; x++) {
148:         const t = world.tiles[y * world.size + x];
149:         const cx = this.offsetX + (x - y) * TW / 2;
150:         const cy = this.offsetY + (x + y) * TH / 2;
151:         this.drawTile(ctx, t, cx, cy, pal, x, y, world);
152:       }
153:     }
154: 
155:     // subtle map border fade
156:     ctx.save();
157:     const edge = ctx.createLinearGradient(0, 0, 0, 160);
158:     edge.addColorStop(0, 'rgba(3,4,8,0.6)');
159:     edge.addColorStop(1, 'rgba(3,4,8,0)');
160:     ctx.fillStyle = edge;
161:     ctx.fillRect(0, 0, c.width, 160);
162:     ctx.restore();
163:     return c;
164:   }
165: 
166:   drawTile(ctx, t, cx, cy, pal, tx, ty, world) {
167:     const type = t.type;
168:     let base;
169:     switch (type) {
170:       case 'path': base = pal.path; break;
171:       case 'plaza': base = shade(pal.path, 0.08); break;
172:       case 'plaza_light': base = shade(pal.path, 0.18); break;
173:       case 'shore': base = shade(pal.ground1, 0.12); break;
174:       case 'water': base = pal.water; break;
175:       case 'void': base = '#05040c'; break;
176:       case 'ground2': base = pal.ground2; break;
177:       case 'ground3': base = pal.ground3; break;
178:       default: base = pal.ground1;
179:     }
180:     const w = TW / 2, h = TH / 2;
181:     const size = world ? world.size : 0;
182:     const nbType = (dx, dy) => {
183:       if (!world) return null;
184:       const nx = tx + dx, ny = ty + dy;
185:       if (nx < 0 || ny < 0 || nx >= size || ny >= size) return null;
186:       return world.tiles[ny * size + nx]?.type || null;
187:     };
188:     const waterAlong = world ? ['water'].some(k => [nbType(1, 0), nbType(-1, 0), nbType(0, 1), nbType(0, -1), nbType(1, 1), nbType(1, -1), nbType(-1, 1), nbType(-1, -1)].includes(k)) : false;
189: 
190:     if (type === 'water') {
191:       const deep = ['water'].includes(nbType(1, 0)) && ['water'].includes(nbType(-1, 0)) && ['water'].includes(nbType(0, 1)) && ['water'].includes(nbType(0, -1))
192:         && ['water'].includes(nbType(1, 1)) && ['water'].includes(nbType(-1, -1)) && ['water'].includes(nbType(1, -1)) && ['water'].includes(nbType(-1, 1));
193:       base = deep ? shade(pal.water, -0.16) : shade(pal.water, 0.02);
194:       const v = (t.variant % 9) - 4;
195:       base = shade(base, v * 0.005);
196:       ctx.beginPath();
197:       ctx.moveTo(cx, cy - h); ctx.lineTo(cx + w, cy); ctx.lineTo(cx, cy + h); ctx.lineTo(cx - w, cy);
198:       ctx.closePath();
199:       ctx.fillStyle = base;
200:       ctx.fill();
201:       // depth shading toward the centre of lakes
202:       if (deep) {
203:         ctx.fillStyle = 'rgba(4,12,26,0.18)';
204:         ctx.beginPath();
205:         ctx.ellipse(cx, cy, w * 0.42, h * 0.42, 0, 0, Math.PI * 2);
206:         ctx.fill();
207:         ctx.fillStyle = 'rgba(255,255,255,0.05)';
208:         ctx.fillRect(cx - 12, cy - 2, 9, 1);
209:         ctx.fillRect(cx + 3, cy + 3, 6, 1);
210:       } else {
211:         // shallow sandy bottom showing through + foam flecks
212:         ctx.fillStyle = shade(pal.water, 0.14);
213:         ctx.fillRect(cx - 8, cy - 1, 14, 1);
214:         ctx.fillStyle = 'rgba(255,255,255,0.2)';
215:         ctx.fillRect(cx - 11, cy - 4, 6, 1);
216:         ctx.fillRect(cx + 5, cy + 1, 4, 1);
217:         ctx.fillRect(cx - 2, cy - 7, 3, 1);
218:       }
219:       return;
220:     }
221:     if (type === 'void') {
222:       ctx.beginPath();
223:       ctx.moveTo(cx, cy - h); ctx.lineTo(cx + w, cy); ctx.lineTo(cx, cy + h); ctx.lineTo(cx - w, cy);
224:       ctx.closePath();
225:       ctx.fillStyle = '#05040c';
226:       ctx.fill();
227:       const rngV = (t.variant * 9301 + 49297) % 233280;
228:       for (let i = 0; i < 4; i++) {
229:         const rx = ((rngV * (i + 5) + 311) % 100) / 100;
230:         const ry = ((rngV * (i + 11) + 733) % 100) / 100;
231:         const dx = (rx - 0.5) * w * 0.9, dy = (ry - 0.5) * h * 0.9;
232:         if (Math.abs(dx) / w + Math.abs(dy) / h > 0.8) continue;
233:         ctx.fillStyle = i === 0 ? 'rgba(180,160,255,0.55)' : 'rgba(140,120,220,0.28)';
234:         ctx.fillRect(cx + dx, cy + dy, 1, 1);
235:       }
236:       if ((t.variant + tx + ty) % 23 === 0) {
237:         ctx.fillStyle = 'rgba(169,155,255,0.16)';
238:         ctx.beginPath(); ctx.ellipse(cx, cy, 9, 4, 0, 0, Math.PI * 2); ctx.fill();
239:       }
240:       return;
241:     }
242: 
243:     // land diamond + soft water-edge halo
244:     const v = (t.variant % 9) - 4;
245:     base = shade(base, v * 0.006);
246:     ctx.beginPath();
247:     ctx.moveTo(cx, cy - h); ctx.lineTo(cx + w, cy); ctx.lineTo(cx, cy + h); ctx.lineTo(cx - w, cy);
248:     ctx.closePath();
249:     ctx.fillStyle = base;
250:     ctx.fill();
251:     if (waterAlong && type === 'shore') {
252:       ctx.fillStyle = 'rgba(240,236,210,0.28)';
253:       ctx.fillRect(cx - 4, cy - 2, 8, 1);
254:     }
255: 
256:     // texture specks inside the diamond
257:     const rngV = (t.variant * 9301 + 49297) % 233280;
258:     const dots = 4 + (t.variant % 5);
259:     for (let i = 0; i < dots; i++) {
260:       const rx = ((rngV * (i + 3) + 137) % 100) / 100;
261:       const ry = ((rngV * (i + 7) + 911) % 100) / 100;
262:       const dx = (rx - 0.5) * w * 1.15;
263:       const dy = (ry - 0.5) * h * 0.95;
264:       if (Math.abs(dx) / w + Math.abs(dy) / h > 0.85) continue;
265:       const light = (t.variant + i) % 3 !== 0;
266:       ctx.fillStyle = light ? shade(base, 0.09) : shade(base, -0.08);
267:       ctx.fillRect(cx + dx, cy + dy, 2, 1);
268:     }
269: 
270:     const regionId = world ? world.regionId : '';
271:     const grassy = type === 'ground1' || type === 'ground2' || type === 'ground3' || type === 'shore';
272: 
273:     if (grassy && type !== 'path' && type !== 'plaza' && type !== 'plaza_light') {
274:       // grass tufts: paired light/dark blades
275:       const tufts = type === 'ground1' ? 2 : 1;
276:       for (let i = 0; i < tufts; i++) {
277:         const rx = ((rngV * (i + 17) + 551) % 100) / 100;
278:         const ry = ((rngV * (i + 29) + 197) % 100) / 100;
279:         const dx = (rx - 0.5) * w * 0.9;
280:         const dy = (ry - 0.5) * h * 0.7;
281:         if (Math.abs(dx) / w + Math.abs(dy) / h > 0.7) continue;
282:         ctx.fillStyle = shade(base, 0.17);
283:         ctx.fillRect(cx + dx, cy + dy - 2, 1, 3);
284:         ctx.fillRect(cx + dx + 2, cy + dy - 1, 1, 2);
285:         ctx.fillStyle = shade(base, -0.13);
286:         ctx.fillRect(cx + dx - 2, cy + dy, 1, 2);
287:       }
288:       // wildflower accents (region palette driven)
289:       if (type === 'ground1' && t.variant % 13 === 0) {
290:         const flowerColors = {
291:           greendale: ['#ffd166', '#ff8fa3'], ironcrag: ['#ffb23e'], venomwood: ['#b06bff', '#9b6bff'],
292:           mistgrave: ['#c9d8e8'], frostpeak: ['#bfefff'], sunscorch: ['#ffd166', '#ff9a4a'],
293:           ashen: ['#ff7a3c'], tower: ['#a99bff']
294:         };
295:         const cols = flowerColors[regionId] || ['#ffd166'];
296:         const rx = ((rngV * 41 + 97) % 100) / 100;
297:         const ry = ((rngV * 53 + 41) % 100) / 100;
298:         const dx = (rx - 0.5) * w * 0.7, dy = (ry - 0.5) * h * 0.55;
299:         if (Math.abs(dx) / w + Math.abs(dy) / h < 0.62) {
300:           ctx.fillStyle = '#3f6a38';
301:           ctx.fillRect(cx + dx, cy + dy, 1, 2);
302:           ctx.fillStyle = cols[(t.variant + tx) % cols.length];
303:           ctx.fillRect(cx + dx - 1, cy + dy - 1, 2, 2);
304:         }
305:       }
306:     }
307: 
308:     // region ground accents
309:     if (regionId === 'frostpeak' && grassy && t.variant % 5 === 0) {
310:       ctx.fillStyle = 'rgba(238,246,250,0.5)';
311:       ctx.fillRect(cx - 6 + (t.variant % 7), cy - 2, 6, 1);
312:       ctx.fillRect(cx + 2 + (v % 3), cy + 2, 4, 1);
313:     } else if (regionId === 'sunscorch' && grassy && t.variant % 4 === 0) {
314:       ctx.fillStyle = shade(base, 0.12);
315:       ctx.fillRect(cx - 7, cy + 1, 10, 1);
316:       ctx.fillRect(cx - 3, cy - 3, 8, 1);
317:     } else if (regionId === 'ashen' && grassy && t.variant % 6 === 0) {
318:       ctx.fillStyle = 'rgba(20,12,12,0.3)';
319:       ctx.fillRect(cx - 8, cy, 5, 1);
320:       ctx.fillRect(cx - 2, cy + 2, 7, 1);
321:       if (t.variant % 12 === 0) {
322:         ctx.fillStyle = '#ff7a3c';
323:         ctx.fillRect(cx + 6, cy - 1, 1, 1);
324:       }
325:     } else if (regionId === 'tower' && grassy && t.variant % 7 === 0) {
326:       ctx.fillStyle = 'rgba(169,155,255,0.22)';
327:       ctx.fillRect(cx - 1, cy + 5, 4, 1);
328:       ctx.fillRect(cx + 3, cy + 3, 2, 1);
329:     } else if (regionId === 'mistgrave' && grassy && t.variant % 6 === 0) {
330:       ctx.fillStyle = 'rgba(190,205,220,0.12)';
331:       ctx.beginPath(); ctx.ellipse(cx + (v % 5), cy - 3, 7, 3, 0, 0, Math.PI * 2); ctx.fill();
332:     } else if (regionId === 'venomwood' && type === 'ground1' && t.variant % 8 === 0) {
333:       ctx.fillStyle = 'rgba(24,34,18,0.35)';
334:       ctx.fillRect(cx - 6, cy + 1, 9, 1);
335:       ctx.fillStyle = '#8f4fb0';
336:       ctx.fillRect(cx + 4, cy - 2, 1, 1);
337:     } else if (regionId === 'ironcrag' && grassy && t.variant % 9 === 0) {
338:       ctx.fillStyle = '#7d7872';
339:       ctx.fillRect(cx - 3, cy + 3, 3, 2);
340:       ctx.fillStyle = '#96908a';
341:       ctx.fillRect(cx - 2, cy + 3, 1, 1);
342:     }
343: 
344:     if (type !== 'path' && type !== 'plaza' && type !== 'plaza_light' && t.variant % 11 === 0) {
345:       ctx.fillStyle = shade(base, 0.14);
346:       ctx.fillRect(cx - 2, cy - 3, 1, 3);
347:       ctx.fillRect(cx + 2, cy + 1, 1, 2);
348:     }
349:     if (type === 'path' || type === 'plaza') {
350:       // cobble hints
351:       if (t.variant % 4 === 0) {
352:         ctx.fillStyle = shade(base, 0.09);
353:         ctx.fillRect(cx - 5, cy - 2, 5, 1);
354:         ctx.fillRect(cx + 2, cy + 2, 4, 1);
355:         ctx.fillStyle = shade(base, -0.07);
356:         ctx.fillRect(cx - 2, cy + 3, 6, 1);
357:       }
358:       // set cobblestone stones on some tiles
359:       if (t.variant % 3 === 0) {
360:         const stones = 1 + (t.variant % 2);
361:         for (let i = 0; i < stones; i++) {
362:           const sx = 12 + ((t.variant * 7 + i * 31) % 13);
363:           const sy = 4 + ((t.variant * 13 + i * 17) % 9);
364:           ctx.fillStyle = shade(base, 0.13);
365:           ctx.fillRect(cx - sx / 2, cy - 2 + sy * 0.6, sx, 2);
366:           ctx.fillStyle = shade(base, -0.1);
367:           ctx.fillRect(cx - sx / 2, cy + sy * 0.6, sx, 1);
368:         }
369:       }
370:       // path-side pebbles / weeds
371:       if (t.variant % 7 === 0) {
372:         ctx.fillStyle = shade(base, 0.05);
373:         ctx.fillRect(cx + w * 0.55, cy - 1, 2, 1);
374:         ctx.fillStyle = shade(base, -0.12);
375:         ctx.fillRect(cx - w * 0.6, cy + 1, 2, 1);
376:       }
377:     }
378:     if (type === 'plaza_light') {
379:       ctx.fillStyle = shade(base, 0.1);
380:       ctx.fillRect(cx - 14, cy - 2, 28, 1);
381:     }
382:   }
383: 
384:   // ------------------------------------------------------------
385:   // WEATHER
386:   // ------------------------------------------------------------
387:   makeWeather(kind) {
388:     const n = WEATHER_COUNT[kind] || 24;
389:     this.particles = [];
390:     for (let i = 0; i < n; i++) {
391:       this.particles.push({
392:         x: Math.random() * this.width,
393:         y: Math.random() * this.height,
394:         vx: (Math.random() - 0.5) * 12,
395:         vy: 8 + Math.random() * 26,
396:         size: 1 + Math.random() * 2,
397:         phase: Math.random() * Math.PI * 2,
398:         speed: 0.4 + Math.random() * 1.6,
399:         alpha: 0.25 + Math.random() * 0.5
400:       });
401:     }
402:     this.weatherKind = kind;
403:   }
404: 
405:   updateWeather(dt) {
406:     const kind = this.weatherKind;
407:     for (const p of this.particles) {
408:       p.phase += dt * p.speed;
409:       if (kind === 'embers') {
410:         p.y -= (14 + p.speed * 22) * dt;
411:         p.x += Math.sin(p.phase * 2) * 14 * dt;
412:       } else if (kind === 'snow') {
413:         p.y += p.vy * dt;
414:         p.x += Math.sin(p.phase) * 16 * dt;
415:       } else if (kind === 'sand') {
416:         p.x += (40 + p.speed * 45) * dt;
417:         p.y += Math.sin(p.phase) * 8 * dt;
418:       } else if (kind === 'stars') {
419:         // static twinkle
420:       } else if (kind === 'mist') {
421:         p.x += (4 + p.speed * 4) * dt;
422:         p.y += Math.sin(p.phase) * 2 * dt;
423:       } else {
424:         p.y += p.vy * dt * 0.7;
425:         p.x += Math.sin(p.phase * 1.4) * 20 * dt;
426:       }
427:       if (p.y > this.height + 20) { p.y = -20; p.x = Math.random() * this.width; }
428:       if (p.y < -30) { p.y = this.height + 10; p.x = Math.random() * this.width; }
429:       if (p.x > this.width + 20) p.x = -20;
430:       if (p.x < -20) p.x = this.width + 20;
431:     }
432:   }
433: 
434:   drawWeather(ctx) {
435:     const kind = this.weatherKind;
436:     const pal = this.world.region.palette;
437:     ctx.save();
438:     if (kind === 'leaves') {
439:       for (const p of this.particles) {
440:         ctx.globalAlpha = p.alpha;
441:         ctx.fillStyle = Math.sin(p.phase) > 0 ? pal.accent : '#d5a44c';
442:         ctx.fillRect(p.x, p.y, p.size + 1, p.size);
443:       }
444:     } else if (kind === 'embers') {
445:       for (const p of this.particles) {
446:         ctx.globalAlpha = p.alpha * (0.7 + Math.sin(p.phase * 2) * 0.3);
447:         ctx.fillStyle = Math.sin(p.phase) > 0 ? '#ffb23e' : '#ff5a3c';
448:         ctx.fillRect(p.x, p.y, p.size, p.size);
449:       }
450:     } else if (kind === 'spores') {
451:       for (const p of this.particles) {
452:         ctx.globalAlpha = p.alpha * (0.5 + Math.sin(p.phase) * 0.5);
453:         ctx.fillStyle = '#c9a0ff';
454:         ctx.fillRect(p.x, p.y, p.size, p.size);
455:         ctx.globalAlpha *= 0.4;
456:         ctx.fillRect(p.x - 1, p.y - 1, p.size + 2, p.size + 2);
457:       }
458:     } else if (kind === 'snow') {
459:       for (const p of this.particles) {
460:         ctx.globalAlpha = p.alpha;
461:         ctx.fillStyle = '#f2fbff';
462:         ctx.fillRect(p.x, p.y, p.size, p.size);
463:       }
464:     } else if (kind === 'sand') {
465:       for (const p of this.particles) {
466:         ctx.globalAlpha = p.alpha * 0.6;
467:         ctx.fillStyle = '#f0d79a';
468:         ctx.fillRect(p.x, p.y, p.size + 2, 1);
469:       }
470:     } else if (kind === 'stars') {
471:       for (const p of this.particles) {
472:         ctx.globalAlpha = 0.25 + Math.abs(Math.sin(p.phase)) * 0.6;
473:         ctx.fillStyle = Math.sin(p.phase * 2) > 0 ? '#fff4c4' : '#c9b4ff';
474:         ctx.fillRect(p.x, p.y, p.size, p.size);
475:       }
476:     } else if (kind === 'mist') {
477:       for (const p of this.particles) {
478:         ctx.globalAlpha = 0.05 + p.alpha * 0.05;
479:         ctx.fillStyle = '#b7d4ea';
480:         ctx.beginPath();
481:         ctx.ellipse(p.x, p.y, 90 + p.size * 25, 22 + p.size * 5, 0, 0, Math.PI * 2);
482:         ctx.fill();
483:       }
484:     }
485:     ctx.restore();
486:   }
487: 
488:   // ------------------------------------------------------------
489:   // MAIN RENDER
490:   // ------------------------------------------------------------
491:   render(game, dt) {
492:     const ctx = this.ctx;
493:     this.time += dt;
494:     this.updateWeather(dt);
495:     this.updateDust(dt);
496:     const world = this.world;
497:     if (!world || !game.player) return;
498:     const z = this.viewZoom;
499:     const vw = this.viewW(), vh = this.viewH();
500: 
501:     // camera follow (still smoothly centered on the player)
502:     const p = this.iso(game.player.x, game.player.y);
503:     this.camTarget.x = lerp(this.camTarget.x, p.x - vw / 2, 0.18);
504:     this.camTarget.y = lerp(this.camTarget.y, p.y - vh / 2 - 34, 0.18);
505:     this.clampCamera(this.camTarget);
506:     this.cam.x = lerp(this.cam.x, this.camTarget.x, 0.22);
507:     this.cam.y = lerp(this.cam.y, this.camTarget.y, 0.22);
508:     if (Math.abs(this.cam.x - this.camTarget.x) < 0.05) this.cam.x = this.camTarget.x;
509:     if (Math.abs(this.cam.y - this.camTarget.y) < 0.05) this.cam.y = this.camTarget.y;
510: 
511:     // ---- sky backdrop (screen space) ----
512:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
513:     ctx.imageSmoothingEnabled = false;
514:     const pal = world.region.palette;
515:     const bg = ctx.createLinearGradient(0, 0, 0, this.height);
516:     bg.addColorStop(0, pal.sky);
517:     bg.addColorStop(1, shade(pal.sky, -0.12));
518:     ctx.fillStyle = bg;
519:     ctx.fillRect(0, 0, this.width, this.height);
520: 
521:     // ---- world (zoomed slightly out to show more of the surrounding land) ----
522:     ctx.setTransform(this.dpr * z, 0, 0, this.dpr * z, 0, 0);
523:     // ground is the only pre-rendered bitmap — smooth its downscale so the pixel art stays clean
524:     ctx.imageSmoothingEnabled = true;
525:     if ('imageSmoothingQuality' in ctx) ctx.imageSmoothingQuality = 'high';
526:     ctx.drawImage(this.ground, -Math.round(this.cam.x), -Math.round(this.cam.y));
527:     ctx.imageSmoothingEnabled = false;
528: 
529:     this.drawWaterFX(ctx);
530: 
531:     // lights beneath objects
532:     this.drawGroundLights(ctx, world);
533: 
534:     // player running dust behind entities
535:     this.spawnDust(game);
536:     this.drawDust(ctx);
537: 
538:     // collect drawables
539:     const drawables = [];
540:     const margin = 260;
541:     const visible = (sx, sy) => sx > -margin && sx < vw + margin && sy > -margin - 100 && sy < vh + margin;
542: 
543:     for (const prop of world.props) {
544:       const s = this.worldToView(prop.x, prop.y);
545:       if (visible(s.x, s.y - 80)) drawables.push({ z: prop.x + prop.y, read: () => this.drawPropSprite(ctx, prop, s) });
546:     }
547:     for (const node of world.nodes) {
548:       if (node.respawnAt > Date.now()) continue;
549:       const s = this.worldToView(node.x, node.y);
550:       if (visible(s.x, s.y)) drawables.push({ z: node.x + node.y, read: () => this.drawNodeSprite(ctx, node, s) });
551:     }
552:     for (const h of world.hidden) {
553:       if (h.opened) continue;
554:       const s = this.worldToView(h.x, h.y);
555:       if (visible(s.x, s.y)) drawables.push({ z: h.x + h.y, read: () => this.drawChestSprite(ctx, h, s) });
556:     }
557:     for (const npc of world.npcs) {
558:       const s = this.worldToView(npc.x, npc.y);
559:       if (visible(s.x, s.y)) drawables.push({ z: npc.x + npc.y, read: () => this.drawNpcSprite(ctx, npc, s, game) });
560:     }
561:     for (const enemy of world.enemies) {
562:       if (!enemy.alive) continue;
563:       const s = this.worldToView(enemy.x, enemy.y);
564:       if (visible(s.x, s.y)) drawables.push({ z: enemy.x + enemy.y + 0.01, read: () => this.drawEnemySprite(ctx, enemy, s, game) });
565:     }
566:     if (game.groundLoot) {
567:       for (const loot of game.groundLoot) {
568:         const s = this.worldToView(loot.x, loot.y);
569:         if (visible(s.x, s.y)) drawables.push({ z: loot.x + loot.y + 0.005, read: () => this.drawLootSprite(ctx, loot, s) });
570:       }
571:     }
572:     // player
573:     const ps = this.worldToView(game.player.x, game.player.y);
574:     drawables.push({ z: game.player.x + game.player.y + 0.02, read: () => this.drawPlayerSprite(ctx, game, ps) });
575: 
576:     drawables.sort((a, b) => a.z - b.z);
577:     for (const d of drawables) d.read();
578: 
579:     // target ring under current target
580:     if (game.target && game.target.alive) this.drawTargetRing(ctx, game.target);
581:     if (game.interactTarget) this.drawInteractRing(ctx, game.interactTarget);
582: 
583:     // pets (drawn above world)
584:     if (game.state.char.petActive && game.state.petDef()) {
585:       const off = this.iso(game.player.x, game.player.y);
586:       ctx.save();
587:       const S = this.spriteScale();
588:       ctx.translate(ps.x + 28, ps.y - 20);
589:       ctx.scale(S * 0.8, S * 0.8);
590:       drawPet(ctx, game.state.petDef(), this.time);
591:       ctx.restore();
592:     }
593: 
594:     // skill / combat effects and projectiles
595:     this.drawEffects(ctx, game);
596: 
597:     // ---- screen-space atmosphere ----
598:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
599: 
600:     // soft light shafts over the forests
601:     if (['greendale', 'venomwood', 'ironcrag'].includes(world.regionId)) this.drawSunShafts(ctx);
602: 
603:     // weather
604:     this.drawWeather(ctx);
605: 
606:     // ambient fog / region tint
607:     ctx.save();
608:     const fog = ctx.createRadialGradient(this.width / 2, this.height / 2, Math.min(this.width, this.height) * 0.2, this.width / 2, this.height / 2, Math.max(this.width, this.height) * 0.76);
609:     fog.addColorStop(0, pal.fog);
610:     fog.addColorStop(1, 'rgba(5,4,10,0.46)');
611:     ctx.fillStyle = fog;
612:     ctx.fillRect(0, 0, this.width, this.height);
613:     ctx.restore();
614: 
615:     if (world.mode === 'dungeon') {
616:       ctx.fillStyle = 'rgba(8,4,14,0.16)';
617:       ctx.fillRect(0, 0, this.width, this.height);
618:     }
619: 
620:     // minimap occasionally
621:     const now = performance.now();
622:     if (this.minimapCanvas && now - this.lastMinimap > 220) {
623:       this.lastMinimap = now;
624:       this.drawMinimap(this.minimapCanvas, game);
625:     }
626:   }
627: 
628:   // ------------------------------------------------------------
629:   // RUNNING DUST
630:   // ------------------------------------------------------------
631:   spawnDust(game) {
632:     if (!game.player.moving || !this.world) return;
633:     this._dustAcc = (this._dustAcc || 0) + (this._dt || 0);
634:     if (this._dustAcc < 0.14) return;
635:     this._dustAcc = 0;
636:     const p = this.iso(game.player.x, game.player.y);
637:     this.dust.push({
638:       x: p.x - this.cam.x + (Math.random() - 0.5) * 8,
639:       y: p.y - this.cam.y + 2,
640:       vx: (Math.random() - 0.5) * 14,
641:       vy: -6 - Math.random() * 8,
642:       life: 0.55 + Math.random() * 0.3,
643:       maxLife: 0.85,
644:       size: 2 + Math.random() * 2
645:     });
646:   }
647: 
648:   updateDust(dt) {
649:     this._dt = dt;
650:     for (const d of this.dust) {
651:       d.life -= dt;
652:       d.x += d.vx * dt;
653:       d.y += d.vy * dt;
654:       d.vy += 20 * dt;
655:     }
656:     this.dust = this.dust.filter(d => d.life > 0);
657:   }
658: 
659:   drawDust(ctx) {
660:     const pal = this.world.region.palette;
661:     const base = shade(pal.ground1, 0.22);
662:     for (const d of this.dust) {
663:       const a = clamp(d.life / d.maxLife, 0, 1) * 0.3;
664:       ctx.globalAlpha = a;
665:       ctx.fillStyle = base;
666:       const s = d.size * (1 + (1 - d.life / d.maxLife));
667:       ctx.fillRect(d.x - s / 2, d.y - s / 2, s, s * 0.8);
668:     }
669:     ctx.globalAlpha = 1;
670:   }
671: 
672:   drawSunShafts(ctx) {
673:     const t = this.time;
674:     ctx.save();
675:     ctx.globalCompositeOperation = 'lighter';
676:     for (let i = 0; i < 3; i++) {
677:       const x = this.width * (0.18 + i * 0.3) + Math.sin(t * 0.15 + i * 2) * 26;
678:       const g = ctx.createLinearGradient(x, 0, x + 120, this.height);
679:       g.addColorStop(0, 'rgba(255,236,170,0.075)');
680:       g.addColorStop(0.75, 'rgba(255,220,140,0.02)');
681:       g.addColorStop(1, 'rgba(255,220,140,0)');
682:       ctx.fillStyle = g;
683:       ctx.beginPath();
684:       ctx.moveTo(x, -10);
685:       ctx.lineTo(x + 95, -10);
686:       ctx.lineTo(x + 230, this.height + 10);
687:       ctx.lineTo(x + 70, this.height + 10);
688:       ctx.closePath();
689:       ctx.fill();
690:     }
691:     ctx.restore();
692:   }
693: 
694:   spriteScale() {
695:     const base = Math.min(this.width, this.height) < 620 ? 2.0 : 2.35;
696:     return base;
697:   }
698: 
699:   // ------------------------------------------------------------
700:   // OBJECT RENDERING
701:   // ------------------------------------------------------------
702:   drawShadow(ctx, sx, sy, w, alpha = 0.28) {
703:     ctx.save();
704:     ctx.globalAlpha = alpha;
705:     ctx.fillStyle = '#08060d';
706:     ctx.beginPath();
707:     ctx.ellipse(sx, sy + 2, w, w * 0.4, 0, 0, Math.PI * 2);
708:     ctx.fill();
709:     ctx.restore();
710:   }
711: 
712:   drawPropSprite(ctx, prop, s) {
713:     const S = this.spriteScale() * (prop.scale || 1);
714:     const sc = this.spriteScale();
715:     const shadowW = prop.type === 'house' ? 36 : prop.type === 'tent' ? 26 : prop.kind === 'tree' ? 20 : 12;
716:     this.drawShadow(ctx, s.x, s.y, shadowW * sc * 0.55, prop.type === 'house' ? 0.35 : 0.22);
717:     ctx.save();
718:     ctx.translate(s.x, s.y);
719:     ctx.scale(S, S);
720:     drawProp(ctx, { ...prop, scale: 1 }, this.time, this.biomeStyle());
721:     ctx.restore();
722: 
723:     // prop light sources (flicker)
724:     if (['campfire', 'brazier', 'forge', 'crystal', 'void_crystal', 'star_well', 'lava_rock'].includes(prop.kind)) {
725:       const fl = 0.92 + Math.sin(this.time * 6 + s.x * 0.11) * 0.07;
726:       this.addLight(ctx, s.x, s.y - 12 * sc, (prop.kind === 'forge' ? 120 : 80) * fl, prop.kind === 'crystal' || prop.kind === 'void_crystal' ? '#8fe2ff' : '#ff8a3c');
727:     }
728:   }
729: 
730:   drawNodeSprite(ctx, node, s) {
731:     const S = this.spriteScale();
732:     this.drawShadow(ctx, s.x, s.y, 12, 0.2);
733:     ctx.save();
734:     ctx.translate(s.x, s.y);
735:     ctx.scale(S, S);
736:     drawProp(ctx, { ...node, kind: 'node', scale: node.scale || 1 }, this.time, this.biomeStyle());
737:     ctx.restore();
738:     this.addLight(ctx, s.x, s.y - 10, 45, '#b6ff9a', 0.25);
739:     // sparkle
740:     const t = this.time * 2 + node.x;
741:     ctx.save();
742:     ctx.globalAlpha = 0.5 + Math.sin(t) * 0.3;
743:     ctx.fillStyle = '#e8ffcc';
744:     ctx.fillRect(s.x + Math.sin(t * 1.7) * 12, s.y - 24 + Math.cos(t * 1.3) * 6, 2, 2);
745:     ctx.restore();
746:   }
747: 
748:   drawLootSprite(ctx, loot, s) {
749:     const item = loot.item;
750:     const isStone = item.kind === 'stone';
751:     const isMat = item.kind === 'material';
752:     const color = isStone ? '#ffd166' : isMat ? '#a8e07a' : (RARITIES[item.rarity]?.color || '#ffffff');
753:     const bob = Math.sin(this.time * 4 + (loot.bob || 0)) * 3;
754:     const x = s.x;
755:     const y = s.y + bob;
756:     ctx.save();
757:     // pickup beam
758:     ctx.globalAlpha = 0.18 + Math.sin(this.time * 5 + (loot.bob || 0)) * 0.06;
759:     const g = ctx.createLinearGradient(x, y - 50, x, y);
760:     g.addColorStop(0, 'rgba(255,255,255,0)');
761:     g.addColorStop(1, this.hexAlpha(color, 0.6));
762:     ctx.fillStyle = g;
763:     ctx.fillRect(x - 4, y - 50, 8, 50);
764:     ctx.globalAlpha = 1;
765:     // glow
766:     this.addLight(ctx, x, y - 10, 28, color, 0.18);
767:     // pouch / gem
768:     if (isMat) {
769:       ctx.fillStyle = '#3f4a32';
770:       ctx.fillRect(x - 5, y - 11, 10, 9);
771:       ctx.fillStyle = color;
772:       ctx.fillRect(x - 3, y - 13, 6, 5);
773:       ctx.fillStyle = '#e8ffd0';
774:       ctx.fillRect(x - 1, y - 12, 2, 2);
775:     } else if (isStone) {
776:       ctx.fillStyle = '#2b2130';
777:       ctx.fillRect(x - 5, y - 10, 10, 8);
778:       ctx.fillStyle = color;
779:       ctx.fillRect(x - 3, y - 13, 6, 6);
780:       ctx.fillStyle = '#fff6d0';
781:       ctx.fillRect(x - 1, y - 12, 2, 2);
782:     } else {
783:       ctx.fillStyle = '#2b2130';
784:       ctx.fillRect(x - 6, y - 11, 12, 9);
785:       ctx.fillStyle = this.hexAlpha(color, 0.9);
786:       ctx.fillRect(x - 4, y - 12, 8, 3);
787:       ctx.fillStyle = '#4a3a2a';
788:       ctx.fillRect(x - 6, y - 4, 12, 2);
789:       ctx.fillStyle = color;
790:       ctx.fillRect(x - 1, y - 8, 2, 2);
791:     }
792:     // sparkle
793:     ctx.globalAlpha = 0.6 + Math.sin(this.time * 6 + (loot.bob || 0)) * 0.4;
794:     ctx.fillStyle = '#fff8d8';
795:     ctx.fillRect(x + 8, y - 20, 2, 2);
796:     ctx.fillRect(x - 10, y - 15, 1, 1);
797:     ctx.restore();
798:   }
799: 
800:   drawChestSprite(ctx, h, s) {    const S = this.spriteScale();
801:     this.drawShadow(ctx, s.x, s.y, 12, 0.22);
802:     ctx.save();
803:     ctx.translate(s.x, s.y);
804:     ctx.scale(S, S);
805:     drawProp(ctx, { ...h, type: 'chest', kind: 'chest', scale: 1 }, this.time, this.biomeStyle());
806:     ctx.restore();
807:     this.addLight(ctx, s.x, s.y - 10, 55, '#ffdf37', 0.28);
808:     const t = this.time * 2.4 + h.x;
809:     ctx.save();
810:     ctx.globalAlpha = 0.6 + Math.sin(t) * 0.3;
811:     ctx.fillStyle = '#fff3a8';
812:     ctx.fillRect(s.x - 10 + Math.sin(t) * 3, s.y - 34 + Math.cos(t * 1.3) * 4, 2, 2);
813:     ctx.fillRect(s.x + 8 + Math.cos(t) * 3, s.y - 28 + Math.sin(t * 1.7) * 4, 2, 2);
814:     ctx.restore();
815:   }
816: 
817:   drawNpcSprite(ctx, npc, s, game) {
818:     const S = this.spriteScale();
819:     this.drawShadow(ctx, s.x, s.y, 10, 0.24);
820:     ctx.save();
821:     ctx.translate(s.x, s.y);
822:     ctx.scale(S, S);
823:     drawNpc(ctx, npc, this.time);
824:     ctx.restore();
825: 
826:     // name and role
827:     if (game.state.data.settings.showNames) {
828:       this.drawWorldLabel(ctx, npc.name, s.x, s.y - 104, '#f0d89a', 10);
829:     }
830:     const state = game.state;
831:     let marker = null;
832:     if (npc.role === 'Quest Keeper') {
833:       const available = state.availableQuests().some(q => q.region === npc.region);
834:       const complete = state.data.quests.active.some(a => {
835:         const q = game.questDef(a.id);
836:         return q && q.region === npc.region && state.isQuestComplete(q);
837:       });
838:       if (available) marker = '!';
839:       else if (complete) marker = '?';
840:     }
841:     if (marker) {
842:       const y = s.y - 126 + Math.sin(this.time * 2.5) * 3;
843:       ctx.save();
844:       ctx.font = 'bold 22px Georgia, serif';
845:       ctx.textAlign = 'center';
846:       ctx.lineWidth = 4;
847:       ctx.strokeStyle = 'rgba(12,8,18,0.9)';
848:       ctx.strokeText(marker, s.x, y);
849:       ctx.fillStyle = marker === '!' ? '#ffd15c' : '#7dffc1';
850:       ctx.fillText(marker, s.x, y);
851:       ctx.restore();
852:     }
853:   }
854: 
855:   drawEnemySprite(ctx, enemy, s, game) {
856:     const S = this.spriteScale();
857:     const def = enemy.def;
858:     const shadowW = def.boss ? 30 : enemy.elite ? 16 : 12;
859:     this.drawShadow(ctx, s.x, s.y, shadowW, def.boss ? 0.4 : 0.25);
860:     if (def.boss) {
861:       this.addLight(ctx, s.x, s.y - 30, 140, def.color, 0.18);
862:       // boss aura ring
863:       ctx.save();
864:       ctx.globalAlpha = 0.25 + Math.sin(this.time * 2) * 0.08;
865:       ctx.strokeStyle = def.color;
866:       ctx.lineWidth = 2;
867:       ctx.beginPath();
868:       ctx.ellipse(s.x, s.y, 46, 18, 0, 0, Math.PI * 2);
869:       ctx.stroke();
870:       ctx.restore();
871:     }
872:     if (enemy.elite) this.addLight(ctx, s.x, s.y - 20, 50, '#ffd166', 0.16);
873:     ctx.save();
874:     ctx.translate(s.x, s.y);
875:     ctx.scale(S, S);
876:     drawEnemy(ctx, enemy, this.time);
877:     ctx.restore();
878: 
879:     // hp bar
880:     const w = def.boss ? 92 : enemy.elite ? 56 : 40;
881:     const y = s.y - (def.boss ? 120 : enemy.elite ? 92 : 74) * (enemy.scale || 1) / 1.2;
882:     this.drawBar(ctx, s.x - w / 2, y, w, 4, enemy.hp / enemy.maxHp, def.boss ? '#ff5a5a' : enemy.elite ? '#ffd166' : '#65d67a');
883:     if (game.state.data.settings.showNames) {
884:       const nm = (enemy.elite ? 'Elite ' : '') + def.name + (def.boss ? '  ☠' : '');
885:       this.drawWorldLabel(ctx, nm, s.x, y - 5, def.boss ? '#ffb08a' : enemy.elite ? '#ffd166' : '#e6e2d8', def.boss ? 11 : 9);
886:     }
887:   }
888: 
889:   drawPlayerSprite(ctx, game, s) {
890:     const state = game.state;
891:     const c = state.char;
892:     const S = this.spriteScale();
893:     const eq = state.data.equipped;
894:     const wings = state.wingsDef();
895:     const mount = state.mountDef();
896:     const cosmetic = state.costumePalette();
897: 
898:     // equipment aura
899:     const aura = this.equipmentAura(state);
900:     if (aura) {
901:       this.addLight(ctx, s.x, s.y - 45, 80 + aura.strength * 20, aura.color, 0.13 + aura.strength * 0.05);
902:       ctx.save();
903:       ctx.globalAlpha = 0.25 + aura.strength * 0.08;
904:       ctx.strokeStyle = aura.color;
905:       ctx.lineWidth = 1.5;
906:       ctx.beginPath();
907:       ctx.ellipse(s.x, s.y, 26 + aura.strength * 5, 10 + aura.strength * 2, 0, 0, Math.PI * 2);
908:       ctx.stroke();
909:       ctx.restore();
910:     }
911:     this.drawShadow(ctx, s.x, s.y, mount ? 24 : 13, mount ? 0.32 : 0.26);
912: 
913:     // arcane sigil while casting
914:     if (game.player.casting) {
915:       const sigC = c.classId === 'mage' ? '#79d6ff' : '#ffb23e';
916:       ctx.save();
917:       ctx.globalAlpha = 0.4 + Math.sin(this.time * 9) * 0.15;
918:       ctx.strokeStyle = sigC;
919:       ctx.lineWidth = 1.4;
920:       ctx.beginPath();
921:       ctx.ellipse(s.x, s.y, 16, 7, 0, 0, Math.PI * 2);
922:       ctx.stroke();
923:       ctx.globalAlpha *= 0.7;
924:       ctx.beginPath();
925:       ctx.ellipse(s.x, s.y, 9, 4, 0, 0, Math.PI * 2);
926:       ctx.stroke();
927:       const spin = this.time * 6;
928:       for (let i = 0; i < 6; i++) {
929:         const a = spin + i * Math.PI / 3;
930:         ctx.fillStyle = sigC;
931:         ctx.fillRect(s.x + Math.cos(a) * 16, s.y + Math.sin(a) * 7, 1.5, 1.5);
932:       }
933:       ctx.restore();
934:     }
935: 
936:     ctx.save();
937:     ctx.translate(s.x, s.y);
938:     ctx.scale(S, S);
939:     drawCharacter(ctx, {
940:       faction: c.faction, classId: c.classId, gender: c.gender,
941:       hairStyle: c.hair, hairColor: state.hairColorHex(), eyeColor: state.eyeColorHex(),
942:       equipment: eq, wings, mount, cosmetic,
943:       time: this.time, moving: game.player.moving,
944:       facing: game.player.facing || 1,
945:       attack: game.player.attackAnim,
946:       casting: game.player.casting,
947:       aura: aura,
948:       weaponFx: state.weaponFxDef()
949:     });
950:     ctx.restore();
951: 
952:     // weapon fx particles
