213:   bindJoystick() {
214:     const joy = this.el.joystick;
215:     let active = false;
216:     let pointerId = null;
217:     let cx = 0, cy = 0, radius = 40;
218:     const start = (e) => {
219:       if (this.game?.transitioning) return;
220:       const rect = joy.getBoundingClientRect();
221:       cx = rect.left + rect.width / 2;
222:       cy = rect.top + rect.height / 2;
223:       radius = rect.width * 0.32;
224:       active = true;
225:       pointerId = e.pointerId;
226:       joy.setPointerCapture(pointerId);
227:       move(e);
228:       e.preventDefault();
229:     };
230:     const move = (e) => {
231:       if (!active) return;
232:       let dx = e.clientX - cx;
233:       let dy = e.clientY - cy;
234:       const len = Math.hypot(dx, dy);
235:       if (len > radius) { dx = dx / len * radius; dy = dy / len * radius; }
236:       const nx = dx / radius;
237:       const ny = dy / radius;
238:       this.game?.setJoystick(nx, ny);
239:       this.el.joyKnob.style.transform = `translate(${dx}px, ${dy}px)`;
240:       e.preventDefault();
241:     };
242:     const end = (e) => {
243:       if (!active) return;
244:       active = false;
245:       pointerId = null;
246:       this.game?.setJoystick(0, 0);
247:       this.el.joyKnob.style.transform = 'translate(0px, 0px)';
248:     };
249:     joy.addEventListener('pointerdown', start);
250:     joy.addEventListener('pointermove', move);
251:     joy.addEventListener('pointerup', end);
252:     joy.addEventListener('pointercancel', end);
253:     joy.addEventListener('pointerleave', (e) => { if (!active) return; end(e); });
254:   }
