1039:   drawWaterFX(ctx) {
1040:     const pal = this.world.region.palette;
1041:     const t = this.time;
1042:     ctx.save();
1043:     // drifting highlight waves
1044:     ctx.globalAlpha = 0.35;
1045:     for (let i = 0; i < this.waterTiles.length; i++) {
1046:       const tile = this.waterTiles[i];
1047:       if ((i + Math.floor(t * 2)) % 4 !== 0) continue;
1048:       const s = this.worldToView(tile.x, tile.y);
1049:       if (s.x < -40 || s.x > this.viewW() + 40 || s.y < -20 || s.y > this.viewH() + 20) continue;
1050:       const off = Math.sin(t * 1.8 + i) * 6;
1051:       ctx.fillStyle = '#d7f6ff';
1052:       ctx.fillRect(s.x + off - 5, s.y + 2, 10, 1);
1053:     }
1054:     // softer secondary shimmer offset from the first pass
1055:     ctx.globalAlpha = 0.18;
1056:     for (let i = 0; i < this.waterTiles.length; i++) {
1057:       const tile = this.waterTiles[i];
1058:       if ((i + Math.floor(t * 1.3) + 2) % 5 !== 0) continue;
1059:       const s = this.worldToView(tile.x, tile.y);
1060:       if (s.x < -40 || s.x > this.viewW() + 40 || s.y < -20 || s.y > this.viewH() + 20) continue;
1061:       const off = Math.cos(t * 1.1 + i * 1.7) * 7;
1062:       ctx.fillStyle = shade(pal.water, 0.3);
1063:       ctx.fillRect(s.x + off - 4, s.y - 2, 8, 1);
1064:     }
1065:     // occasional glint
1066:     ctx.globalAlpha = 0.8;
1067:     for (let i = 0; i < this.waterTiles.length; i++) {
1068:       if ((i + Math.floor(t * 0.7)) % 17 !== 0) continue;
1069:       const tile = this.waterTiles[i];
1070:       const s = this.worldToView(tile.x, tile.y);
1071:       if (s.x < -40 || s.x > this.viewW() + 40 || s.y < -20 || s.y > this.viewH() + 20) continue;
1072:       const tw = Math.sin(t * 3 + i);
1073:       if (tw <= 0.55) continue;
1074:       ctx.fillStyle = '#ffffff';
1075:       ctx.fillRect(s.x + tw * 3, s.y - 1 - tw * 2, 2, 1);
1076:     }
1077:     ctx.restore();
1078:   }
