1224:   drawBar(ctx, x, y, w, h, pct, color) {
1225:     ctx.save();
1226:     ctx.fillStyle = 'rgba(8,6,14,0.75)';
1227:     ctx.fillRect(x - 1, y - 1, w + 2, h + 2);
1228:     ctx.fillStyle = 'rgba(255,255,255,0.08)';
1229:     ctx.fillRect(x, y, w, h);
1230:     ctx.fillStyle = color;
1231:     ctx.fillRect(x, y, Math.max(0, w * clamp(pct, 0, 1)), h);
1232:     ctx.fillStyle = 'rgba(255,255,255,0.35)';
