450: export function drawWings(ctx, wings, time, y, demon) {
451:   const flap = Math.sin(time * 2.4) * 0.10;
452:   const pal = wings.palette || (demon ? ['#2b1728', '#5a2031', '#d94a4a'] : ['#fff8df', '#ffe9a3', '#e8c46a']);
453:   ctx.save();
454:   ctx.translate(0, y);
455:   ctx.scale(1, 1 + flap);
456:   const style = wings.style;
457:   const pairs = style === 'seraph' ? 3 : 1;
458:   for (let k = 0; k < pairs; k++) {
459:     const spread = 1 - k * 0.25;
460:     const yy = k * 7;
461:     for (const dir of [-1, 1]) {
462:       ctx.save();
463:       ctx.scale(dir, 1);
464:       if (style === 'bat' || style === 'abyss') {
465:         // bat-like membrane
466:         const c1 = pal[0], c2 = pal[1] || '#5a2031', c3 = pal[2] || '#d94a4a';
467:         p(ctx, 4, 0 + yy, 5, 2, c1);
468:         p(ctx, 8, -2 + yy, 5, 3, c1);
469:         p(ctx, 12, -5 + yy, 6, 4, c2);
470:         p(ctx, 15, -9 + yy, 7, 5, c2);
471:         p(ctx, 10, 1 + yy, 8, 5, c2);
472:         p(ctx, 14, -4 + yy, 3, 2, c3);
473:         p(ctx, 18, -8 + yy, 2, 2, c3);
474:         // bone spikes
475:         p(ctx, 21, -11 + yy, 2, 4, c1);
476:         p(ctx, 18, -2 + yy, 2, 3, c1);
477:         p(ctx, 8, 2 + yy, 1, 4, c1);
478:         if (style === 'abyss') {
479:           p(ctx, 12, 6 + yy, 4, 2, c3);
480:           p(ctx, 20, -4 + yy, 1, 6, c3);
481:         }
482:       } else {
483:         // feather layers
484:         const c1 = pal[0], c2 = pal[1], c3 = pal[2];
485:         p(ctx, 4, 0 + yy, 8, 2, c2);
486:         p(ctx, 8, -2 + yy, 8, 3, c1);
487:         p(ctx, 12, -5 + yy, 8, 3, c1);
488:         p(ctx, 15, -8 + yy, 8, 3, c1);
489:         p(ctx, 10, 2 + yy, 8, 2, c2);
490:         p(ctx, 14, -2 + yy, 6, 2, c2);
491:         p(ctx, 16, -10 + yy, 4, 2, c3);
492:         p(ctx, 19, -7 + yy, 2, 5, c3);
493:         p(ctx, 8, 1 + yy, 1, 3, c3);
494:         if (style === 'seraph') {
495:           p(ctx, 18, -12 + yy, 3, 2, shade(c3, 0.15));
496:           p(ctx, 11, -7 + yy, 5, 1, '#fffdf2');
497:         }
498:       }
499:       ctx.restore();
500:     }
501:   }
502:   ctx.restore();
503: }
