726:       p(ctx, -7, -21, 14, 6, C(light));
727:       p(ctx, -5, -18, 3, 3, '#ff4d6d'); p(ctx, 2, -18, 3, 3, '#ff4d6d');
728:       p(ctx, -3, -14, 6, 1, C(dark));
729:       break;
730:     }
731:     case 'lurker': case 'toad': {
732:       const wide = kind === 'toad' ? 14 : 11;
733:       p(ctx, -wide, -13, wide * 2, 13, C(c));
734:       p(ctx, -wide + 2, -17, wide * 2 - 4, 6, C(light));
735:       p(ctx, -6, -17, 4, 4, '#ffd166'); p(ctx, 2, -17, 4, 4, '#ffd166');
736:       p(ctx, -8, -4, 4, 4, C(dark)); p(ctx, 4, -4, 4, 4, C(dark));
737:       p(ctx, -4, -8, 8, 2, C(dark));
738:       if (kind === 'toad') {
739:         p(ctx, -9, -11, 2, 3, C(light)); p(ctx, 7, -11, 2, 3, C(light));
740:       } else {
741:         p(ctx, -12, -10, 3, 8, C(dark)); p(ctx, 9, -10, 3, 8, C(dark));
742:       }
743:       break;
744:     }
745:     case 'ghost': {
746:       ctx.globalAlpha = 0.85;
747:       p(ctx, -8, -28, 16, 16, C(c));
748:       p(ctx, -7, -33, 14, 7, C(light));
749:       p(ctx, -9, -30, 3, 8, C(dark)); p(ctx, 6, -30, 3, 8, C(dark));
750:       p(ctx, -5, -25, 3, 3, '#1a1a2a'); p(ctx, 2, -25, 3, 3, '#1a1a2a');
751:       p(ctx, -6, -15, 12, 10, C(c));
752:       p(ctx, -6, -6, 3, 4, 'rgba(180,220,255,0.35)');
753:       p(ctx, 0, -9, 3, 6, 'rgba(180,220,255,0.35)');
754:       p(ctx, 5, -6, 2, 3, 'rgba(180,220,255,0.3)');
755:       ctx.globalAlpha = 1;
756:       break;
757:     }
758:     case 'skeleton': {
759:       p(ctx, -5, -27, 10, 2, C('#d8d5c8'));
760:       p(ctx, -1, -25, 2, 12, C('#c9c6b8'));
761:       for (let i = 0; i < 3; i++) p(ctx, -5, -24 + i * 3, 10, 1, C('#c9c6b8'));
762:       p(ctx, -6, -14, 3, 10, C('#c9c6b8')); p(ctx, 3, -14, 3, 10, C('#c9c6b8'));
763:       p(ctx, -4, -35, 8, 8, C('#e2dfd2'));
764:       p(ctx, -3, -32, 2, 2, '#3c2f55'); p(ctx, 2, -32, 2, 2, '#3c2f55');
765:       p(ctx, -1, -28, 2, 1, '#3c2f55');
766:       // sword
767:       const ws = Math.round(atk * 4);
768:       p(ctx, 8, -29 - ws, 2, 18, '#c7ccd6');
769:       p(ctx, 6, -13 - ws, 6, 2, '#8a6a45');
