504:   addFeed(msg, type = '') {
505:     if (this.el.eventFeed.children.length > 7) this.el.eventFeed.firstElementChild.remove();
506:     const line = document.createElement('div');
507:     line.className = `feed-line ${type === 'gold' ? 'gold' : ''}`;
508:     line.textContent = msg;
509:     this.el.eventFeed.appendChild(line);
510:     setTimeout(() => line.remove(), 9000);
511:   }
