1317: // ------------------------------------------------------------
1318: export function renderCharacterPreview(canvas, opts = {}) {
1319:   const ctx = canvas.getContext('2d');
1320:   const dpr = Math.min(window.devicePixelRatio || 1, 2);
1321:   const rect = canvas.getBoundingClientRect();
1322:   const w = Math.max(120, rect.width || 180);
1323:   const h = Math.max(160, rect.height || 240);
1324:   canvas.width = Math.floor(w * dpr);
1325:   canvas.height = Math.floor(h * dpr);
1326:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
1327:   ctx.imageSmoothingEnabled = false;
1328:   const bg = ctx.createRadialGradient(w / 2, h * 0.45, 10, w / 2, h * 0.5, w * 0.75);
1329:   bg.addColorStop(0, opts.bg1 || 'rgba(120,100,190,0.25)');
1330:   bg.addColorStop(1, 'rgba(6,5,12,0)');
1331:   ctx.fillStyle = bg;
1332:   ctx.fillRect(0, 0, w, h);
1333: 
1334:   // pedestal
1335:   ctx.save();
1336:   ctx.globalAlpha = 0.5;
1337:   ctx.fillStyle = '#151020';
1338:   ctx.beginPath();
