1033:   hexAlpha(hex, a) {
1034:     const h = hex.replace('#', '');
1035:     const n = parseInt(h.length === 3 ? h.split('').map(c => c + c).join('') : h, 16);
1036:     return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
1037:   }
