1080:   drawEffects(ctx, game) {
1081:     for (const fx of game.effects) {
1082:       const s = this.worldToView(fx.x, fx.y);
1083:       const life = 1 - fx.life / fx.maxLife;
1084:       if (fx.type === 'dmg') {
1085:         ctx.save();
1086:         ctx.globalAlpha = Math.min(1, fx.life / 0.4);
1087:         ctx.font = `bold ${(fx.big ? 20 : 14) / this.viewZoom}px Georgia, serif`;
1088:         ctx.textAlign = 'center';
1089:         ctx.lineWidth = 3;
1090:         ctx.strokeStyle = 'rgba(10,8,16,0.85)';
1091:         const y = s.y - 70 - life * 34 + (fx.offset || 0);
1092:         ctx.strokeText(fx.text, s.x + (fx.dx || 0), y);
1093:         ctx.fillStyle = fx.color;
1094:         ctx.fillText(fx.text, s.x + (fx.dx || 0), y);
1095:         ctx.restore();
1096:       } else if (fx.type === 'ring') {
1097:         ctx.save();
1098:         ctx.globalAlpha = Math.max(0, fx.life / fx.maxLife) * 0.7;
1099:         ctx.strokeStyle = fx.color;
1100:         ctx.lineWidth = fx.width || 3;
1101:         ctx.beginPath();
1102:         ctx.ellipse(s.x, s.y - 10, fx.radius * life * 2.2, fx.radius * life * 0.9, 0, 0, Math.PI * 2);
1103:         ctx.stroke();
1104:         ctx.restore();
1105:       } else if (fx.type === 'slash') {
1106:         ctx.save();
1107:         ctx.globalAlpha = Math.max(0, fx.life / fx.maxLife) * 0.8;
1108:         ctx.strokeStyle = fx.color;
1109:         ctx.lineWidth = 4;
1110:         ctx.beginPath();
1111:         ctx.arc(s.x, s.y - 32, 34, -1.2 + life * 0.4, 0.9 + life * 1.2);
1112:         ctx.stroke();
1113:         ctx.restore();
1114:       } else if (fx.type === 'beam') {
1115:         ctx.save();
1116:         ctx.globalAlpha = Math.max(0, fx.life / fx.maxLife) * 0.7;
1117:         ctx.strokeStyle = fx.color;
1118:         ctx.lineWidth = 2 + Math.sin(this.time * 20) * 1;
1119:         ctx.beginPath();
1120:         ctx.moveTo(s.x, s.y - 46);
1121:         ctx.lineTo(s.x + (fx.dx || 0), s.y - 46 + (fx.dy || -80));
1122:         ctx.stroke();
1123:         ctx.restore();
1124:       } else if (fx.type === 'burst') {
1125:         ctx.save();
1126:         ctx.globalAlpha = Math.max(0, fx.life / fx.maxLife);
1127:         for (let i = 0; i < 8; i++) {
1128:           const a = i / 8 * Math.PI * 2 + life * 2;
1129:           ctx.fillStyle = fx.color;
1130:           ctx.fillRect(s.x + Math.cos(a) * life * 40, s.y - 30 + Math.sin(a) * life * 18, 3, 3);
1131:         }
1132:         ctx.restore();
1133:       }
1134:     }
1135:     // projectiles
1136:     for (const pr of game.projectiles) {
1137:       const s = this.worldToView(pr.x, pr.y);
1138:       ctx.save();
1139:       if (pr.type === 'arrow') {
1140:         // motion streak
1141:         ctx.globalAlpha = 0.35;
1142:         ctx.strokeStyle = '#e8dcc0';
1143:         ctx.lineWidth = 1.5;
1144:         ctx.beginPath();
1145:         ctx.moveTo(s.x - 22, s.y - 40);
1146:         ctx.lineTo(s.x - 10, s.y - 42);
1147:         ctx.stroke();
1148:         ctx.globalAlpha = 1;
1149:         ctx.strokeStyle = '#e8dcc0';
1150:         ctx.lineWidth = 2;
1151:         ctx.beginPath();
1152:         ctx.moveTo(s.x - 10, s.y - 42);
1153:         ctx.lineTo(s.x + 6, s.y - 36);
1154:         ctx.stroke();
1155:         ctx.fillStyle = '#cfd8e2';
1156:         ctx.fillRect(s.x + 5, s.y - 39, 4, 4);
1157:       } else if (pr.type === 'fire') {
1158:         // trailing embers
1159:         ctx.globalAlpha = 0.4;
1160:         for (let i = 1; i <= 3; i++) {
1161:           ctx.fillStyle = i === 1 ? '#ffd166' : '#ff7a3c';
1162:           ctx.fillRect(s.x - 8 - i * 5, s.y - 33 - Math.sin(i) * 3, 2, 2);
1163:         }
1164:         ctx.globalAlpha = 1;
1165:         const gr = ctx.createRadialGradient(s.x, s.y - 34, 1, s.x, s.y - 34, 10);
1166:         gr.addColorStop(0, '#fff4c4');
1167:         gr.addColorStop(0.4, '#ffb23e');
1168:         gr.addColorStop(1, 'rgba(255,80,40,0)');
1169:         ctx.fillStyle = gr;
1170:         ctx.fillRect(s.x - 12, s.y - 46, 24, 24);
1171:       } else {
1172:         ctx.globalAlpha = 0.3;
1173:         ctx.fillStyle = pr.color || '#b079ff';
1174:         ctx.fillRect(s.x - 10, s.y - 41, 9, 5);
1175:         ctx.globalAlpha = 1;
1176:         ctx.fillStyle = pr.color || '#b079ff';
1177:         ctx.fillRect(s.x - 3, s.y - 38, 6, 6);
1178:         ctx.fillStyle = 'rgba(255,255,255,0.6)';
1179:         ctx.fillRect(s.x - 2, s.y - 37, 2, 2);
1180:         ctx.globalAlpha = 0.4;
1181:         ctx.fillRect(s.x - 6, s.y - 41, 12, 12);
1182:       }
1183:       ctx.restore();
1184:     }
1185:   }
