1037:         px(ctx, 0, -11, '#e8f0ff');
1038:         px(ctx, -4, -9, '#e8f0ff');
1039:       }
1040:       break;
1041:     }
1042:     case 'flowers': {
1043:       const cols = ['#ffd166', '#ff8fa3', '#a99bff', '#8fe2ff', '#f7f4ea'];
1044:       for (let i = 0; i < 7; i++) {
