611:     p(ctx, -5, -10, 2, 3, shade(c, -0.25)); p(ctx, 4, -10, 2, 3, shade(c, -0.25));
612:     p(ctx, -2, -4, 2, 3, shade(c, -0.2)); p(ctx, 1, -4, 2, 3, shade(c, -0.2));
613:   } else {
