615:     p(ctx, -5, -8, 10, 6, c);
616:     p(ctx, -4, -11, 8, 5, c);
617:     p(ctx, -4, -13, 2, 3, shade(c, -0.2)); p(ctx, 2, -13, 2, 3, shade(c, -0.2));
