662:       p(ctx, -3, -15, 2, 2, '#ffd166'); p(ctx, 1, -15, 2, 2, '#ffd166');
663:       p(ctx, -9, -4, 3, 4 + run, C(dark)); p(ctx, 2, -4, 3, 4 - run, C(dark));
664:       p(ctx, -2, -13, 3, 1, '#f7f0dc');
665:       // tail
