628:   // ------------------------------------------------------------
629:   // RUNNING DUST
630:   // ------------------------------------------------------------
631:   spawnDust(game) {
632:     if (!game.player.moving || !this.world) return;
633:     this._dustAcc = (this._dustAcc || 0) + (this._dt || 0);
634:     if (this._dustAcc < 0.14) return;
635:     this._dustAcc = 0;
636:     const p = this.iso(game.player.x, game.player.y);
637:     this.dust.push({
638:       x: p.x - this.cam.x + (Math.random() - 0.5) * 8,
639:       y: p.y - this.cam.y + 2,
640:       vx: (Math.random() - 0.5) * 14,
641:       vy: -6 - Math.random() * 8,
642:       life: 0.55 + Math.random() * 0.3,
643:       maxLife: 0.85,
644:       size: 2 + Math.random() * 2
645:     });
646:   }
647: 
648:   updateDust(dt) {
649:     this._dt = dt;
650:     for (const d of this.dust) {
651:       d.life -= dt;
652:       d.x += d.vx * dt;
653:       d.y += d.vy * dt;
654:       d.vy += 20 * dt;
655:     }
656:     this.dust = this.dust.filter(d => d.life > 0);
657:   }
658: 
659:   drawDust(ctx) {
660:     const pal = this.world.region.palette;
661:     const base = shade(pal.ground1, 0.22);
662:     for (const d of this.dust) {
663:       const a = clamp(d.life / d.maxLife, 0, 1) * 0.3;
664:       ctx.globalAlpha = a;
665:       ctx.fillStyle = base;
666:       const s = d.size * (1 + (1 - d.life / d.maxLife));
667:       ctx.fillRect(d.x - s / 2, d.y - s / 2, s, s * 0.8);
668:     }
669:     ctx.globalAlpha = 1;
670:   }
671: 
672:   drawSunShafts(ctx) {
673:     const t = this.time;
674:     ctx.save();
675:     ctx.globalCompositeOperation = 'lighter';
676:     for (let i = 0; i < 3; i++) {
677:       const x = this.width * (0.18 + i * 0.3) + Math.sin(t * 0.15 + i * 2) * 26;
678:       const g = ctx.createLinearGradient(x, 0, x + 120, this.height);
679:       g.addColorStop(0, 'rgba(255,236,170,0.075)');
680:       g.addColorStop(0.75, 'rgba(255,220,140,0.02)');
681:       g.addColorStop(1, 'rgba(255,220,140,0)');
682:       ctx.fillStyle = g;
683:       ctx.beginPath();
684:       ctx.moveTo(x, -10);
685:       ctx.lineTo(x + 95, -10);
686:       ctx.lineTo(x + 230, this.height + 10);
687:       ctx.lineTo(x + 70, this.height + 10);
688:       ctx.closePath();
689:       ctx.fill();
690:     }
691:     ctx.restore();
692:   }
693: 
694:   spriteScale() {
695:     const base = Math.min(this.width, this.height) < 620 ? 2.0 : 2.35;
696:     return base;
697:   }
