712:   drawPropSprite(ctx, prop, s) {
713:     const S = this.spriteScale() * (prop.scale || 1);
714:     const sc = this.spriteScale();
715:     const shadowW = prop.type === 'house' ? 36 : prop.type === 'tent' ? 26 : prop.kind === 'tree' ? 20 : 12;
716:     this.drawShadow(ctx, s.x, s.y, shadowW * sc * 0.55, prop.type === 'house' ? 0.35 : 0.22);
717:     ctx.save();
718:     ctx.translate(s.x, s.y);
719:     ctx.scale(S, S);
720:     drawProp(ctx, { ...prop, scale: 1 }, this.time, this.biomeStyle());
721:     ctx.restore();
722: 
723:     // prop light sources (flicker)
724:     if (['campfire', 'brazier', 'forge', 'crystal', 'void_crystal', 'star_well', 'lava_rock'].includes(prop.kind)) {
725:       const fl = 0.92 + Math.sin(this.time * 6 + s.x * 0.11) * 0.07;
726:       this.addLight(ctx, s.x, s.y - 12 * sc, (prop.kind === 'forge' ? 120 : 80) * fl, prop.kind === 'crystal' || prop.kind === 'void_crystal' ? '#8fe2ff' : '#ff8a3c');
727:     }
728:   }
