441:       this.el.qtTitle.textContent = q.title;
442:       this.el.qtDesc.textContent = q.desc;
443:       this.el.qtFill.style.width = `${Math.min(100, progress / q.required * 100)}%`;
444:       this.el.qtCount.textContent = complete ? 'Ready to claim — tap here' : `${progress} / ${q.required}`;
445:       this.el.qtFill.style.background = complete ? 'linear-gradient(90deg,#3a9f57,#7dffc1)' : '';
446:     }
447:     this.updateMinimap();
