711:         </div>`;
712:     } else if (item.kind === 'material') {
713:       body = `
714:         <p class="panel-lead">${escapeHtml(item.desc || MATERIALS[item.materialId]?.desc || 'A crafting material.')}</p>
715:         <div class="row wrap mt8">
716:           <span class="tag green">×${item.count} in bag</span>
717:           <span class="tag">Used for quests, Legendary crafting and trading.</span>
718:         </div>
719:         <div class="row wrap mt12">
720:           <button class="btn btn-sm" data-act="sell" data-uid="${uid}">Sell stack</button>
721:           <button class="btn btn-sm" data-act="deposit" data-uid="${uid}">Store</button>
722:           <button class="btn btn-sm btn-ghost" data-act="item-back">← Back</button>
723:         </div>`;
