991:   equipmentAura(state) {
992:     let best = null;
993:     for (const slot of SLOTS) {
994:       const item = state.data.equipped[slot.id];
995:       if (!item) continue;
996:       const score = (8 - item.tier) * 10 + (RARITIES[item.rarity]?.order || 0) * 4;
997:       if (!best || score > best.score) {
998:         best = { score, tier: item.tier, rarity: item.rarity };
999:       }
1000:     }
1001:     if (!best) return null;
1002:     if (best.tier === 3 && (RARITIES[best.rarity]?.order || 0) < 4) return null;
1003:     return {
1004:       tier: best.tier,
1005:       color: RARITIES[best.rarity]?.color || '#ffe08a',
1006:       strength: best.tier === 1 ? 3 : best.tier === 2 ? 2 : 1
1007:     };
1008:   }
