1199:   drawInteractRing(ctx, entity) {
1200:     const s = this.worldToView(entity.x, entity.y);
1201:     ctx.save();
1202:     ctx.strokeStyle = '#ffe08a';
1203:     ctx.lineWidth = 1.5;
