939: export function drawProp(ctx, prop, time, biome = {}) {
940:   const v = prop.variant || 0;
941:   const s = prop.scale || 1;
942:   const flick = Math.sin(time * 4 + v) * 0.5 + 0.5;
943:   const type = prop.kind || prop.type;
944:   ctx.save();
945:   if (prop.flip) ctx.scale(-1, 1);
946:   ctx.scale(s, s);
947:   switch (type) {
948:     case 'tree': {
949:       const leaf = biome.leaf || '#4f8a4b';
950:       const leaf2 = shade(leaf, 0.14);
951:       const leaf3 = shade(leaf, -0.2);
952:       const leaf4 = shade(leaf, 0.24);
953:       const sway = Math.sin(time * 1.4 + v * 0.7) * 0.7;
954:       const sway2 = Math.sin(time * 1.4 + v * 0.7 + 0.9) * 0.9;
955:       // trunk with moss and root flare
956:       p(ctx, -3, -18, 6, 18, '#6a4a2f');
957:       p(ctx, -3, -18, 2, 18, '#7d5836');
958:       p(ctx, -5, -14, 3, 3, '#5a8a3e');           // moss clump
959:       p(ctx, 2, -8, 2, 2, shade('#5a8a3e', -0.1));
960:       p(ctx, -5, -14, 4, 2, '#5a3f27');
961:       p(ctx, -2, -1, 10, 2, '#5a3f27');           // root flare
962:       // crown layers (sway with the wind)
963:       p(ctx, -18 + sway, -26, 9, 8, leaf3);
964:       p(ctx, 9 + sway, -28, 7, 7, leaf);
965:       p(ctx, -12 + sway, -30, 24, 14, leaf3);
966:       p(ctx, -10 + sway, -38, 20, 12, leaf);
967:       p(ctx, -7 + sway2, -44, 14, 9, leaf2);
968:       p(ctx, -3 + sway2, -47, 8, 5, shade(leaf, 0.3));
969:       p(ctx, 4 + sway, -36, 5, 3, leaf2);
970:       p(ctx, 12 + sway, -33, 5, 4, shade(leaf, 0.2));
971:       // sunlit edge + shadowed underside
972:       p(ctx, -12 + sway, -30, 24, 2, leaf4);
973:       p(ctx, -12 + sway, -18, 20, 2, 'rgba(0,0,10,0.18)');
974:       p(ctx, -8 + sway, -41, 4, 2, 'rgba(255,255,255,0.14)');
975:       p(ctx, 2 + sway2, -45, 3, 2, 'rgba(255,255,255,0.2)');
976:       break;
977:     }
978:     case 'pine': case 'pine_snow': {
979:       const snow = type === 'pine_snow';
980:       const leaf = snow ? '#2f5946' : (biome.pine || '#356044');
981:       const leaf2 = shade(leaf, 0.16);
982:       const leaf3 = shade(leaf, -0.16);
983:       const sway = Math.sin(time * 1.1 + v) * 0.6;
