1250:       leaf: { greendale: '#4f8a4b', ironcrag: '#4c6a3c', venomwood: '#4e5f34', mistgrave: '#3d4a48', frostpeak: '#3f6b5b', sunscorch: '#6b7a3f', ashen: '#4a3030', tower: '#3a3a6b' }[id],
1251:       pine: { greendale: '#356044', ironcrag: '#33523c', venomwood: '#334d3a', mistgrave: '#2e3f42', frostpeak: '#2f5946', sunscorch: '#4f6138', ashen: '#352b2b', tower: '#373a68' }[id],
