1082:       ctx.lineWidth = 1;
1083:       ctx.beginPath(); ctx.moveTo(-2, -19); ctx.lineTo(1, -12); ctx.lineTo(-2, -6); ctx.stroke();
1084:       if (v % 3 === 0) {
