30:       if (!State.load()) {
31:         ui.toast({ msg: 'No compatible save found. Start a new adventure.', type: 'warn', duration: 4000 });
32:         ui.showStart();
33:         return;
34:       }
35:       launch();
36:     } catch (err) {
37:       console.error('Could not load save', err);
38:       ui.toast({ msg: 'Save could not be loaded. Start a new adventure.', type: 'danger', duration: 5000 });
39:       ui.showStart();
40:     }
