48: function launch() {
49:   // Keep the audio engine asleep until a gesture; the first tap resumes it.
50:   game.sfx.enabled = State.data?.settings?.sound !== false;
51: 
52:   ui.el.start.classList.add('hidden');
53:   ui.el.creation.classList.add('hidden');
54:   ui.el.modalRoot.classList.add('hidden');
55:   ui.panel = null;
56:   ui.el.deathOverlay.classList.add('hidden');
57:   game.start();
