61: // GLOBAL LIFECYCLE
62: // ------------------------------------------------------------
63: let lastVisibilitySave = 0;
64: 
65: function saveNow(reason) {
66:   if (!State.data) return;
67:   State.save();
68:   if (reason === 'manual') Events.emit('toast', { msg: 'Game saved locally.', type: 'success', small: true });
69: }
70: 
71: document.addEventListener('visibilitychange', () => {
72:   if (document.hidden && State.data) {
73:     const now = Date.now();
74:     // avoid hammering localStorage when switching tabs repeatedly
75:     if (now - lastVisibilitySave > 3000) {
76:       lastVisibilitySave = now;
77:       saveNow('visibility');
78:     }
79:   } else if (!document.hidden) {
80:     game.sfx.resume();
81:   }
82: });
