drawShadow(ctx, sx, sy, w, alpha = 0.28) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = '#08060d';
  ctx.beginPath();
  ctx.ellipse(sx, sy + 2, w, w * 0.4, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

drawPropSprite(ctx, prop, s) {
  const S = this.spriteScale() * (prop.scale || 1);
