/* ============================== TOAST ============================== */
.toast-host { position: absolute; top: 14px; left: 50%; transform: translateX(-50%); z-index: 90; display: flex; flex-direction: column; align-items: center; gap: 6px; pointer-events: none; width: min(520px, 92vw); }
/* Keep feedback visible without covering the top of an open sheet. */
#modalRoot:not(.hidden) ~ .toast-host { top: 10px; left: 50%; transform: translateX(-50%); width: min(520px, 92vw); align-items: center; }
.toast {
  max-width: 100%; padding: 8px 13px; border-radius: 8px; font-size: 10px; line-height: 1.4;
  background: rgba(18,14,28,0.95); border: 1px solid var(--line); color: var(--text);
  box-shadow: 0 8px 26px rgba(0,0,0,0.5); animation: toastIn .22s ease; text-align: center;
  backdrop-filter: blur(4px);
}
.toast.success { border-color: rgba(101,214,122,0.5); color: #c8ffd4; }
.toast.warn { border-color: rgba(255,178,62,0.5); color: #ffe0ad; }
.toast.danger { border-color: rgba(255,93,115,0.55); color: #ffc2ca; }
.toast.region { font-family: var(--serif); font-size: 13px; padding: 10px 18px; color: var(--gold-2); border-color: var(--line-strong); }
.toast.loot { border-color: rgba(230,196,106,0.3); }
.toast.small { font-size: 9px; padding: 6px 10px; }
.toast.out { animation: toastOut .25s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }

/* ============================== DEATH ============================== */
.death-overlay { position: absolute; inset: 0; z-index: 45; display: grid; place-content: center; text-align: center; background: radial-gradient(circle, rgba(70,5,14,0.25), rgba(5,2,6,0.7)); pointer-events: none; animation: deathIn .6s ease; }
@keyframes deathIn { from { opacity: 0; } to { opacity: 1; } }
.death-word { font-family: var(--serif); font-size: clamp(28px, 7vw, 64px); letter-spacing: .22em; color: #ffb0b8; text-shadow: 0 0 40px rgba(255,40,60,0.45); }
.death-overlay p { font-size: 11px; color: var(--muted); letter-spacing: 1px; }

